impl RustNativeExtension for SteelsearchRuntimeExtension {
    fn descriptor(&self) -> RustNativeExtensionDescriptor {
        RustNativeExtensionDescriptor {
            module: "steelsearch-runtime",
            feature: "runtime-observability",
            description: "Steelsearch development runtime plugin surface",
            classname: "org.steelsearch.runtime.Plugin",
            rest_routes: &[
                "/_cat/plugins",
                "/_steelsearch/dev/extensions",
                "/_steelsearch/dev/extensions/_shutdown",
                "/_steelsearch/dev/extensions/_recovery_failed",
            ],
            transport_actions: &[],
            lifecycle_hooks: &[
                "sync_shared_runtime_state_from_disk",
                "refuse_task_submission_if_unavailable",
                "set_live_shutdown_in_progress",
                "set_shared_runtime_state_recovery_failed",
            ],
        }
    }
}

