#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct ExtensionBoundaryManifest {
    #[serde(default)]
    knn_plugin_enabled: bool,
    #[serde(default)]
    ml_commons_enabled: bool,
    #[serde(default)]
    java_plugin_abi: Option<Value>,
    #[serde(default)]
    java_plugins: Vec<Value>,
}

impl ExtensionBoundaryRegistry {
    pub fn load_manifest(path: impl AsRef<Path>) -> std::io::Result<Self> {
        let path = path.as_ref();
        let bytes = fs::read(path)?;
        let manifest: ExtensionBoundaryManifest =
            serde_json::from_slice(&bytes).map_err(|error| {
                std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!("invalid extension manifest [{}]: {error}", path.display()),
                )
            })?;
        if manifest.java_plugin_abi.is_some() || !manifest.java_plugins.is_empty() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!(
                    "unsupported Java plugin ABI manifest [{}]: Java plugin descriptors cannot be loaded by the Rust-native extension registry",
                    path.display()
                ),
            ));
        }
        Ok(Self {
            manifest_path: Some(path.to_path_buf()),
            knn_plugin_enabled: manifest.knn_plugin_enabled,
            ml_commons_enabled: manifest.ml_commons_enabled,
        })
    }

    pub fn registered_components(&self) -> Vec<&'static str> {
        self.rust_native_extension_descriptors()
            .into_iter()
            .map(|descriptor| descriptor.module)
            .collect()
    }

    pub fn registration_table(&self) -> Vec<ExtensionRegistrationEntry> {
        self.rust_native_extension_descriptors()
            .into_iter()
            .map(|descriptor| ExtensionRegistrationEntry {
                module: descriptor.module,
                feature: descriptor.feature,
                rest_routes: descriptor.rest_routes,
                transport_actions: descriptor.transport_actions,
                lifecycle_hooks: descriptor.lifecycle_hooks,
            })
            .collect()
    }

    pub fn rust_native_extension_descriptors(&self) -> Vec<RustNativeExtensionDescriptor> {
        let mut descriptors = vec![SteelsearchRuntimeExtension.descriptor()];
        if self.knn_plugin_enabled {
            descriptors.push(KnnCompatibilityExtension.descriptor());
        }
        if self.ml_commons_enabled {
            descriptors.push(MlCommonsCompatibilityExtension.descriptor());
        }
        descriptors
    }

    fn registered_plugin_specs(&self) -> Vec<ExtensionPluginSpec> {
        self.rust_native_extension_descriptors()
            .into_iter()
            .map(|descriptor| ExtensionPluginSpec {
                component: descriptor.module,
                description: descriptor.description,
                classname: descriptor.classname,
            })
            .collect()
    }
}

