    fn handle_field_caps_route(&self, target: Option<&str>) -> RestResponse {
        let requested_target = target.unwrap_or("_all");
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        let mut indices = Vec::new();
        let mut fields = serde_json::Map::new();

        if let Some(index_map) = manifest["indices"].as_object() {
            for (index, metadata) in index_map {
                if requested_target != "_all" && !matches_index_selector(requested_target, index) {
                    continue;
                }
                indices.push(Value::String(index.clone()));
                if let Some(properties) = metadata
                    .get("mappings")
                    .and_then(|mappings| mappings.get("properties"))
                    .and_then(Value::as_object)
                {
                    for (field_name, field_spec) in properties {
                        let field_type = field_spec
                            .get("type")
                            .and_then(Value::as_str)
                            .unwrap_or("keyword");
                        fields.entry(field_name.clone()).or_insert_with(|| {
                            serde_json::json!({
                                field_type: {
                                    "type": field_type,
                                    "searchable": true,
                                    "aggregatable": true,
                                    "metadata_field": false
                                }
                            })
                        });
                    }
                }
            }
        }

        if fields.is_empty() {
            for (key, record) in docs.iter() {
                let Some(index) = key.split(':').next() else {
                    continue;
                };
                if requested_target != "_all" && !matches_index_selector(requested_target, index) {
                    continue;
                }
                if !indices.iter().any(|value| value == index) {
                    indices.push(Value::String(index.to_string()));
                }
                if let Some(source) = record.source.as_object() {
                    for (field_name, value) in source {
                        let field_type = infer_field_caps_type(value);
                        fields.entry(field_name.clone()).or_insert_with(|| {
                            serde_json::json!({
                                field_type: {
                                    "type": field_type,
                                    "searchable": true,
                                    "aggregatable": field_type != "text",
                                    "metadata_field": false
                                }
                            })
                        });
                    }
                }
            }
        }

        RestResponse::json(
            200,
            serde_json::json!({
                "indices": indices,
                "fields": Value::Object(fields)
            }),
        )
    }

    fn handle_tier_all_route(&self) -> RestResponse {
        RestResponse::json(
            200,
            serde_json::json!({
                "tiers": ["hot", "warm", "cold", "frozen"]
            }),
        )
    }

    fn handle_index_tier_route(&self, index: &str) -> RestResponse {
        if index.split(',').filter(|value| !value.is_empty()).count() != 1 {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "request should contain single index",
            );
        }
        let tier = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned")["indices"][index]["tier_preference"]
            .as_str()
            .unwrap_or("hot")
            .to_string();
        RestResponse::json(
            200,
            serde_json::json!({
                "index": index,
                "tiers": [tier]
            }),
        )
    }

    fn handle_index_target_tier_route(&self, index: &str, target_tier: &str) -> RestResponse {
        let matched = match self.resolve_index_metadata_targets(index, false, false, "open") {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for matched_index in &matched {
            manifest["indices"][matched_index]["tier_preference"] =
                Value::String(target_tier.to_string());
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "acknowledged": true,
                "indices": matched,
                "target_tier": target_tier
            }),
        )
    }

    fn handle_cancel_index_tier_route(&self, index: &str) -> RestResponse {
        let matched = match self.resolve_index_metadata_targets(index, false, false, "open") {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for matched_index in &matched {
            if let Some(index_state) = manifest["indices"][matched_index].as_object_mut() {
                index_state.remove("tier_preference");
            }
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "acknowledged": true,
                "indices": matched
            }),
        )
    }

    fn search_template_search_body(
        &self,
        target: Option<&str>,
        request: &RestRequest,
        template_id: Option<&str>,
    ) -> Result<Value, RestResponse> {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            serde_json::from_slice::<Value>(&request.body)
                .unwrap_or_else(|_| Value::Object(serde_json::Map::new()))
        };
        self.search_template_payload_body(target, &payload, &request.headers, template_id)
    }

    fn search_template_payload_body(
        &self,
        target: Option<&str>,
        payload: &Value,
        request_headers: &std::collections::BTreeMap<String, String>,
        template_id: Option<&str>,
    ) -> Result<Value, RestResponse> {
        let body = self.resolve_template_source(
            template_id,
            payload,
            TemplateSourceValidation::SearchJsonParseError,
        )?;
        let requested_target = target.unwrap_or("_all");
        let mut search_request =
            RestRequest::new(RestMethod::Post, format!("/{requested_target}/_search"))
                .with_json_body(body);
        search_request.headers = request_headers.clone();
        let response = self.handle_index_search_route(requested_target, &search_request);
        if response.status == 200 {
            Ok(response.body)
        } else {
            Err(response)
        }
    }

    fn resolve_template_source(
        &self,
        template_id: Option<&str>,
        payload: &Value,
        validation: TemplateSourceValidation,
    ) -> Result<Value, RestResponse> {
        let stored_template_id = template_id.or_else(|| payload.get("id").and_then(Value::as_str));
        let source = if let Some(source) = payload.get("source") {
            source.clone()
        } else if let Some(template_name) = stored_template_id {
            let Some(source) = self.load_stored_script_source(template_name) else {
                return Err(build_resource_not_found_search_response(&format!(
                    "unable to find script [{template_name}] in cluster state"
                )));
            };
            source
        } else {
            serde_json::json!({ "query": { "match_all": {} } })
        };
        validate_template_source(&source, validation)?;
        Ok(substitute_template_params(
            &source,
            payload.get("params").and_then(Value::as_object),
        ))
    }

    fn load_stored_script_source(&self, script_id: &str) -> Option<Value> {
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        manifest["stored_scripts"]
            .as_object()
            .and_then(|scripts| scripts.get(script_id))
            .and_then(|script| script.get("source"))
            .cloned()
    }

    fn handle_count_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        let mut payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(_) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parsing_exception",
                                "reason": "Failed to parse"
                            },
                            "status": 400
                        }),
                    );
                }
            }
        };
        if let Some(response) =
            apply_url_query_string_search_params(&mut payload, &request.query_params)
        {
            return response;
        }
        let default_query = serde_json::json!({ "match_all": {} });
        let query = payload.get("query").unwrap_or(&default_query);
        let (valid, explanation) = validate_query_payload_for_validate_route(payload.get("query"));
        if !valid {
            return build_unsupported_search_response(&format!(
                "unsupported count query: {explanation}"
            ));
        }
        let requested_target = target.unwrap_or("_all");
        let resolved_indices = if requested_target == "_all" {
            Some(
                match self.resolve_search_targets("*", false, true, "open") {
                    Ok(indices) => indices,
                    Err(response) => return response,
                },
            )
        } else {
            let ignore_unavailable =
                query_param_is_true(request.query_params.get("ignore_unavailable"));
            let allow_no_indices =
                query_param_is_true(request.query_params.get("allow_no_indices"));
            let mut indices = Vec::new();
            for selector in requested_target
                .split(',')
                .map(str::trim)
                .filter(|selector| !selector.is_empty())
            {
                let selector_uses_wildcard = selector.contains('*') || selector.contains('?');
                match self.resolve_search_targets(
                    selector,
                    ignore_unavailable,
                    allow_no_indices || selector_uses_wildcard,
                    "open",
                ) {
                    Ok(mut matched) => indices.append(&mut matched),
                    Err(response) => return response,
                }
            }
            indices.sort();
            indices.dedup();
            Some(indices)
        };
        let shard_total = resolved_indices
            .as_ref()
            .map(|indices| {
                indices
                    .iter()
                    .map(|index| self.index_primary_shard_count(index))
                    .sum::<usize>()
            })
            .unwrap_or(1);
        let requested_routing_values = request
            .query_params
            .get("routing")
            .cloned()
            .or_else(|| self.resolve_alias_search_routing(requested_target))
            .map(|routing| parse_routing_values(&routing))
            .filter(|routing| !routing.is_empty());
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        let count = docs
            .iter()
            .filter(|(key, record)| {
                let mut parts = key.splitn(3, ':');
                let Some(index) = parts.next() else {
                    return false;
                };
                let Some(id) = parts.next() else {
                    return false;
                };
                if let Some(indices) = &resolved_indices {
                    if !indices.iter().any(|resolved| resolved == index) {
                        return false;
                    }
                }
                if let Some(routings) = requested_routing_values.as_ref() {
                    if !document_matches_requested_routing_shards(
                        index,
                        id,
                        record,
                        routings,
                        |index_name| self.index_primary_shard_count(index_name),
                    ) {
                        return false;
                    }
                }
                matches_query_body(&record.source, Some(query))
            })
            .count();
        RestResponse::json(
            200,
            serde_json::json!({
                "count": count,
                "_shards": {
                    "total": shard_total,
                    "successful": shard_total,
                    "skipped": 0,
                    "failed": 0
                }
            }),
        )
    }

    fn handle_rank_eval_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parse_exception",
                                "reason": error.to_string()
                            },
                            "status": 400
                        }),
                    );
                }
            }
        };
        let requested_target = target.unwrap_or("_all");
        let requests = payload
            .get("requests")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let precision_metric = payload
            .get("metric")
            .and_then(|metric| metric.get("precision"))
            .and_then(Value::as_object);
        let relevant_rating_threshold = precision_metric
            .and_then(|metric| metric.get("relevant_rating_threshold"))
            .and_then(Value::as_i64)
            .unwrap_or(1);
        let ignore_unlabeled = precision_metric
            .and_then(|metric| metric.get("ignore_unlabeled"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let precision_k = precision_metric
            .and_then(|metric| metric.get("k"))
            .and_then(Value::as_u64)
            .unwrap_or(10) as usize;
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        let mut details = serde_json::Map::new();
        let mut scores = Vec::new();
        for request in &requests {
            let request_id = request
                .get("id")
                .and_then(Value::as_str)
                .unwrap_or("rank_eval_request");
            let query = request
                .get("request")
                .and_then(|request| request.get("query"))
                .or_else(|| payload.get("query"));
            let sort = request
                .get("request")
                .and_then(|request| request.get("sort"))
                .unwrap_or(&Value::Null);
            let ratings = request
                .get("ratings")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut ratings_by_key = BTreeMap::new();
            for rating in ratings {
                let Some(index) = rating.get("_index").and_then(Value::as_str) else {
                    continue;
                };
                let Some(id) = rating.get("_id").and_then(Value::as_str) else {
                    continue;
                };
                let Some(score) = rating.get("rating").and_then(Value::as_i64) else {
                    continue;
                };
                ratings_by_key.insert((index.to_string(), id.to_string()), score);
            }
            let mut hits = docs
                .iter()
                .filter_map(|(key, record)| {
                    let (index, id, _) = split_document_key(key)?;
                    if requested_target != "_all"
                        && !matches_index_selector(requested_target, index)
                    {
                        return None;
                    }
                    if !matches_query_body(&record.source, query) {
                        return None;
                    }
                    Some(serde_json::json!({
                        "_index": index,
                        "_id": id,
                        "_source": record.source.clone(),
                        "_score": 1.0,
                        "_seq_no": record.seq_no
                    }))
                })
                .collect::<Vec<_>>();
            apply_search_sort(&mut hits, sort);
            if sort.is_null() {
                hits.sort_by(|left, right| {
                    right["_score"]
                        .as_f64()
                        .unwrap_or(0.0)
                        .partial_cmp(&left["_score"].as_f64().unwrap_or(0.0))
                        .unwrap_or(std::cmp::Ordering::Equal)
                        .then_with(|| {
                            left["_seq_no"]
                                .as_i64()
                                .unwrap_or_default()
                                .cmp(&right["_seq_no"].as_i64().unwrap_or_default())
                        })
                });
            }
            hits.truncate(precision_k);
            append_search_hit_sort_values(
                &mut hits,
                request
                    .get("request")
                    .and_then(|request| request.get("sort")),
            );
            let mut relevant_docs_retrieved = 0;
            let mut docs_retrieved = 0;
            let mut rated_hits = Vec::new();
            let mut unrated_docs = Vec::new();
            for mut hit in hits {
                let index = hit
                    .get("_index")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string();
                let id = hit
                    .get("_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string();
                let rating = ratings_by_key
                    .get(&(index.to_string(), id.to_string()))
                    .copied();
                if let Some(rating) = rating {
                    docs_retrieved += 1;
                    if rating >= relevant_rating_threshold {
                        relevant_docs_retrieved += 1;
                    }
                } else {
                    unrated_docs.push(serde_json::json!({
                        "_index": index,
                        "_id": id
                    }));
                    if !ignore_unlabeled {
                        docs_retrieved += 1;
                    }
                }
                if let Some(hit_object) = hit.as_object_mut() {
                    hit_object.remove("_source");
                    hit_object.remove("_seq_no");
                    if !sort.is_null() {
                        hit_object.insert("_score".to_string(), Value::Null);
                    }
                }
                let mut rated_hit = serde_json::Map::new();
                rated_hit.insert("hit".to_string(), hit);
                if let Some(rating) = rating {
                    rated_hit.insert("rating".to_string(), Value::from(rating));
                }
                rated_hits.push(Value::Object(rated_hit));
            }
            let metric_score = if docs_retrieved > 0 {
                relevant_docs_retrieved as f64 / docs_retrieved as f64
            } else {
                0.0
            };
            scores.push(metric_score);
            details.insert(
                request_id.to_string(),
                serde_json::json!({
                    "metric_score": metric_score,
                    "unrated_docs": unrated_docs,
                    "hits": rated_hits,
                    "metric_details": {
                        "precision": {
                            "relevant_docs_retrieved": relevant_docs_retrieved,
                            "docs_retrieved": docs_retrieved
                        }
                    }
                }),
            );
        }
        let metric_score = if scores.is_empty() {
            0.0
        } else {
            scores.iter().sum::<f64>() / scores.len() as f64
        };
        RestResponse::json(
            200,
            serde_json::json!({
                "metric_score": metric_score,
                "details": Value::Object(details),
                "failures": {}
            }),
        )
    }

    fn handle_validate_query_route(
        &self,
        target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(_) => {
                    return RestResponse::json(200, serde_json::json!({ "valid": false }));
                }
            }
        };
        let query = payload.get("query");
        let (valid, explanation) = validate_query_payload_for_validate_route(query);
        let mut body = serde_json::json!({
            "valid": valid,
            "_shards": {
                "total": 1,
                "successful": 1,
                "skipped": 0,
                "failed": 0
            }
        });
        if let Some(index) = target {
            body["_indices"] = serde_json::json!([index]);
        }
        if query.is_some() && (!valid || request.query_params.contains_key("rewrite")) {
            body["explanations"] = serde_json::json!([{
                "index": target.unwrap_or("_all"),
                "valid": valid,
                "explanation": explanation
            }]);
        }
        RestResponse::json(200, body)
    }

    fn handle_explain_route(&self, index: &str, id: &str, request: &RestRequest) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parse_exception",
                                "reason": error.to_string()
                            },
                            "status": 400
                        }),
                    );
                }
            }
        };
        let resolved_indices = if index.contains('*') || index.contains('?') {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "index_not_found_exception",
                        "reason": format!("no such index [{index}]")
                    },
                    "status": 404
                }),
            );
        } else if self.index_or_alias_exists(index) {
            vec![self.resolve_index_or_alias(index)]
        } else {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "index_not_found_exception",
                        "reason": format!("no such index [{index}]")
                    },
                    "status": 404
                }),
            );
        };
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        let routing = request
            .query_params
            .get("routing")
            .cloned()
            .or_else(|| self.resolve_alias_read_routing(index));
        let found = resolved_indices.iter().find_map(|resolved_index| {
            if let Some(routing) = routing.as_deref() {
                let key = format!("{resolved_index}:{id}:{routing}");
                docs.get(&key)
                    .map(|record| (resolved_index.clone(), record))
            } else {
                let key_prefix = format!("{resolved_index}:{id}:");
                docs.iter()
                    .find(|(key, _)| key.starts_with(&key_prefix))
                    .map(|(_, record)| (resolved_index.clone(), record))
            }
        });
        let Some((resolved_index, record)) = found else {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "_index": if resolved_indices.len() == 1 { resolved_indices[0].clone() } else { index.to_string() },
                    "_id": id,
                    "matched": false
                }),
            );
        };
        let default_query = serde_json::json!({ "match_all": {} });
        let query = payload.get("query").unwrap_or(&default_query);
        let (valid, explanation) = validate_query_payload_for_validate_route(
            payload.get("query").or(Some(&default_query)),
        );
        if !valid {
            return build_unsupported_search_response(&format!(
                "unsupported explain query: {explanation}"
            ));
        }
        let matched = matches_query_body(&record.source, Some(query));
        RestResponse::json(
            200,
            serde_json::json!({
                "_index": resolved_index,
                "_id": id,
                "matched": matched,
                "explanation": {
                    "value": if matched { 1.0 } else { 0.0 },
                    "description": if matched {
                        opensearch_like_query_explanation(query)
                            .unwrap_or_else(|| "query matched document".to_string())
                    } else {
                        opensearch_like_query_explanation(query)
                            .unwrap_or_else(|| "query did not match document".to_string())
                    }
                },
                "get": {
                    "found": true,
                    "_source": record.source
                }
            }),
        )
    }

    fn handle_grok_processor_get_route(&self) -> RestResponse {
        RestResponse::json(
            200,
            serde_json::json!({
                "patterns": {
                    "WORD": "\\\\b\\\\w+\\\\b",
                    "INT": "[+-]?\\\\d+",
                    "GREEDYDATA": ".*"
                }
            }),
        )
    }

    fn handle_painless_context_route(&self) -> RestResponse {
        RestResponse::json(
            200,
            serde_json::json!({
                "contexts": [
                    { "name": "score", "methods": [] },
                    { "name": "filter", "methods": [] },
                    { "name": "template", "methods": [] },
                    { "name": "update", "methods": [] }
                ]
            }),
        )
    }

    fn handle_painless_execute_route(&self, request: &RestRequest) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parse_exception",
                                "reason": error.to_string()
                            },
                            "status": 400
                        }),
                    );
                }
            }
        };
        let result = payload
            .get("params")
            .and_then(|params| params.get("value"))
            .cloned()
            .or_else(|| {
                payload
                    .get("script")
                    .and_then(|script| script.get("params"))
                    .and_then(|params| params.get("value"))
                    .cloned()
            })
            .or_else(|| {
                payload
                    .get("context_setup")
                    .and_then(|setup| setup.get("document"))
                    .cloned()
            })
            .unwrap_or_else(|| Value::String("painless_execute_ok".to_string()));
        RestResponse::json(200, serde_json::json!({ "result": result }))
    }

    fn handle_termvectors_route(
        &self,
        index: &str,
        path_id: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parse_exception",
                                "reason": error.to_string()
                            },
                            "status": 400
                        }),
                    );
                }
            }
        };

        if path_id.is_none() && payload.get("id").is_some() {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "parse_exception",
                        "reason": "failed to parse term vectors request. unknown field [id]"
                    },
                    "status": 400
                }),
            );
        }

        let requested_id = path_id;
        let Some(id) = requested_id else {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "action_request_validation_exception",
                        "reason": "id is missing"
                    },
                    "status": 400
                }),
            );
        };

        let routing = payload
            .get("routing")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .or_else(|| self.resolve_alias_read_routing(index))
            .unwrap_or_default();
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        RestResponse::json(
            200,
            self.mtermvectors_doc_response(&docs, index, id, &routing),
        )
    }

    fn handle_index_search_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "search") {
            Ok(_) => {}
            Err(response) => return response,
        }
        let _thread_pool = match self.enter_runtime_thread_pool("search", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        if let Some(search_type) = request.query_params.get("search_type") {
            if search_type != "query_then_fetch" && search_type != "dfs_query_then_fetch" {
                return build_unsupported_search_response("unsupported search_type");
            }
        }
        if let Some(pre_filter_shard_size) = request.query_params.get("pre_filter_shard_size") {
            if let Some(response) = validate_minimum_search_int_query_param(
                "pre_filter_shard_size",
                pre_filter_shard_size,
                1,
                "preFilterShardSize must be >= 1",
            ) {
                return response;
            }
        }
        for (param, minimum, reason) in [
            (
                "batched_reduce_size",
                2_i64,
                "batchedReduceSize must be >= 2",
            ),
            (
                "max_concurrent_shard_requests",
                1_i64,
                "maxConcurrentShardRequests must be >= 1",
            ),
        ] {
            if let Some(raw) = request.query_params.get(param) {
                if let Some(response) =
                    validate_minimum_search_int_query_param(param, raw, minimum, reason)
                {
                    return response;
                }
            }
        }
        let mut body = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::opensearch_error(
                        400,
                        "unexpected_end_of_input_exception",
                        error.to_string(),
                    );
                }
            }
        };
        if let Some(response) =
            apply_url_query_string_search_params(&mut body, &request.query_params)
        {
            return response;
        }
        let search_pipeline_config = match request.query_params.get("search_pipeline") {
            Some(pipeline_id) => match self.resolve_search_pipeline_execution_config(pipeline_id) {
                Ok(config) => config,
                Err(response) => return response,
            },
            None => SearchPipelineExecutionConfig::default(),
        };
        let rewritten_query = match self.rewrite_neural_query_with_model(
            &body["query"],
            search_pipeline_config.default_model_id.as_deref(),
        ) {
            Ok(rewritten_query) => rewritten_query,
            Err(response) => return response,
        };
        let rewritten_query = match self.rewrite_sparse_encoder_query_with_model(&rewritten_query) {
            Ok(rewritten_query) => rewritten_query,
            Err(response) => return response,
        };
        if body.get("query").is_some() {
            body["query"] = rewritten_query;
        }
        if let Some(response) = apply_search_source_query_params(&mut body, &request.query_params) {
            return response;
        }
        if let Some(response) = normalize_search_source_scalar_body_options(&mut body) {
            return response;
        }
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("request_cache"))
        {
            return response;
        }
        if let Some(cancel_after_time_interval) =
            request.query_params.get("cancel_after_time_interval")
        {
            if parse_time_value_millis(cancel_after_time_interval).is_none() {
                return search_time_query_param_parse_error(
                    "cancel_after_time_interval",
                    cancel_after_time_interval,
                );
            }
        }
        for field in [
            "phase_took",
            "verbose_pipeline",
            "track_scores",
            "include_named_queries_score",
        ] {
            if let Some(response) =
                validate_opensearch_boolean_query_param(request.query_params.get(field))
            {
                return response;
            }
        }
        if let Some(response) = validate_opensearch_boolean_query_param(
            request.query_params.get("allow_partial_search_results"),
        ) {
            return response;
        }
        if let Some(response) = validate_scroll_context_request_body(
            &body,
            request.query_params.contains_key("scroll"),
            query_param_is_true(request.query_params.get("request_cache")),
        ) {
            return response;
        }
        if let Some(response) =
            validate_search_request_body(&body, request.query_params.contains_key("scroll"))
        {
            return response;
        }
        if let Some(response) =
            validate_shard_doc_sort_request_body(&body, request.query_params.contains_key("scroll"))
        {
            return response;
        }
        if let Some(response) = validate_opensearch_boolean_query_param(
            request.query_params.get("rest_total_hits_as_int"),
        ) {
            return response;
        }
        let rest_total_hits_as_int =
            query_param_is_true(request.query_params.get("rest_total_hits_as_int"));
        if rest_total_hits_as_int {
            if let Some(threshold) = search_track_total_hits_threshold(&body) {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!(
                                "[rest_total_hits_as_int] cannot be used if the tracking of total hits is not accurate, got {threshold}"
                            )
                        },
                        "status": 400
                    }),
                );
            }
        }
        let mut point_in_time_response_id = None;
        let pit_context = if let Some(pit_id) = body
            .get("pit")
            .and_then(Value::as_object)
            .and_then(|pit| pit.get("id"))
            .and_then(Value::as_str)
        {
            if pit_id.is_empty() {
                return create_pit_invalid_empty_id_response();
            }
            if !pit_search_id_has_local_shape(pit_id) {
                return delete_pit_invalid_id_response(pit_id);
            }
            if let Some(response) = validate_point_in_time_search_request(index, request) {
                return response;
            }
            let keep_alive = body
                .get("pit")
                .and_then(Value::as_object)
                .and_then(|pit| pit.get("keep_alive"))
                .and_then(Value::as_str);
            let keep_alive_millis = match keep_alive {
                Some(keep_alive) => match parse_time_value_millis(keep_alive) {
                    Some(millis) => {
                        if millis > DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS {
                            return pit_search_keep_alive_limit_response(
                                millis,
                                self.pit_context_first_index(pit_id),
                            );
                        }
                        if millis == 0 {
                            None
                        } else {
                            Some(millis)
                        }
                    }
                    None => {
                        let reason = "[1:198] [pit] failed to parse field [keep_alive]";
                        let caused_by_reason = keep_alive_parse_error_reason(keep_alive);
                        return RestResponse::json(
                            400,
                            serde_json::json!({
                                "error": {
                                    "type": "x_content_parse_exception",
                                    "reason": reason,
                                    "root_cause": [
                                        {
                                            "type": "x_content_parse_exception",
                                            "reason": reason
                                        }
                                    ],
                                    "caused_by": {
                                        "type": "illegal_argument_exception",
                                        "reason": caused_by_reason
                                    }
                                },
                                "status": 400
                            }),
                        );
                    }
                },
                None => None,
            };
            match self.resolve_pit_context(pit_id, keep_alive_millis) {
                Ok(context) => {
                    if let Some(missing_index) = context
                        .indices
                        .iter()
                        .find(|index_name| !self.index_or_alias_exists(index_name))
                    {
                        self.remove_pit_context(pit_id);
                        return index_not_found_response(missing_index);
                    }
                    if context
                        .indices
                        .iter()
                        .any(|index_name| self.index_is_closed(index_name))
                    {
                        self.remove_pit_context(pit_id);
                        return search_phase_missing_pit_context_response(pit_id);
                    }
                    point_in_time_response_id = Some(pit_id.to_string());
                    Some(context)
                }
                Err(response) => return response,
            }
        } else {
            None
        };
        let resolved_indices = if let Some(context) = pit_context.as_ref() {
            context.indices.clone()
        } else {
            let ignore_unavailable = request
                .query_params
                .get("ignore_unavailable")
                .is_some_and(|value| value == "true");
            let allow_no_indices = request
                .query_params
                .get("allow_no_indices")
                .is_some_and(|value| value == "true");
            let expand_wildcards = request
                .query_params
                .get("expand_wildcards")
                .map(String::as_str)
                .unwrap_or("open");
            if expand_wildcards == "none"
                && (index.contains('*') || index.contains('?') || index == "_all")
            {
                Vec::new()
            } else {
                match self.resolve_search_targets(
                    index,
                    ignore_unavailable,
                    allow_no_indices,
                    expand_wildcards,
                ) {
                    Ok(indices) => indices,
                    Err(response) => return response,
                }
            }
        };
        if let Some(closed_index) = resolved_indices
            .iter()
            .find(|index_name| self.index_is_closed(index_name))
        {
            if request
                .query_params
                .get("expand_wildcards")
                .is_some_and(|value| value == "closed")
            {
                return RestResponse::opensearch_error_kind(
                    os_rest::RestErrorKind::IllegalArgument,
                    "To expand [CLOSE] wildcard, please set forbid_closed_indices to `false`",
                );
            }
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "index_closed_exception",
                        "reason": format!("closed index [{closed_index}]")
                    },
                    "status": 400
                }),
            );
        }
        let requested_routing_values = request
            .query_params
            .get("routing")
            .cloned()
            .or_else(|| self.resolve_alias_search_routing(index))
            .map(|routing| parse_routing_values(&routing))
            .filter(|routing| !routing.is_empty());
        let index_mappings = {
            let manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            let mut mappings = std::collections::HashMap::new();
            for index_name in &resolved_indices {
                mappings.insert(
                    index_name.clone(),
                    manifest["indices"][index_name]["mappings"].clone(),
                );
            }
            mappings
        };
        if let Some(response) =
            validate_search_after_sort_values_against_mappings(&body, &index_mappings)
        {
            return response;
        }
        if let Some(response) = validate_search_sort_modes_against_mappings(&body, &index_mappings)
        {
            return response;
        }
        let sort_unmapped_failures =
            collect_search_sort_unmapped_field_failures(&body, &index_mappings);
        if !sort_unmapped_failures.is_empty()
            && sort_unmapped_failures.len() == resolved_indices.len()
        {
            let field_name = sort_unmapped_failures
                .values()
                .next()
                .map(String::as_str)
                .unwrap_or_default();
            return search_after_validation_error(format!(
                "No mapping found for [{field_name}] in order to sort on"
            ));
        }
        if let Some(response) =
            self.validate_knn_target_capabilities(&body["query"], &resolved_indices)
        {
            return response;
        }
        let geo_failed_indices = if let Some(field) = extract_geo_query_field(&body["query"]) {
            let manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            resolved_indices
                .iter()
                .filter(|index_name| {
                    let field_type =
                        manifest["indices"][*index_name]["mappings"]["properties"][&field]["type"]
                            .as_str();
                    matches!(field_type, Some(value) if value != "geo_point" && value != "geo_shape")
                })
                .cloned()
                .collect::<std::collections::BTreeSet<_>>()
        } else {
            std::collections::BTreeSet::new()
        };
        let mut failed_indices = geo_failed_indices.clone();
        failed_indices.extend(sort_unmapped_failures.keys().cloned());
        if pit_context.is_none()
            && !resolved_indices.is_empty()
            && failed_indices.is_empty()
            && requested_routing_values.is_none()
            && !request.query_params.contains_key("search_type")
            && !request.query_params.contains_key("pre_filter_shard_size")
            && !request.query_params.contains_key("ignore_unavailable")
            && standalone_search_body_allows_native_engine(&body)
        {
            if let Some(response) = self.try_native_engine_search_response(
                &resolved_indices,
                &body,
                rest_total_hits_as_int,
            ) {
                return response;
            }
        }
        let needs_suggest_snapshot = body.get("suggest").is_some();
        let (candidate_documents, docs_snapshot_for_suggest) = {
            let live_docs;
            let docs = if let Some(context) = pit_context.as_ref() {
                context.documents.as_ref()
            } else {
                live_docs = self
                    .documents_state
                    .lock()
                    .expect("documents state lock poisoned");
                &*live_docs
            };
            let docs_snapshot_for_suggest = needs_suggest_snapshot.then(|| docs.clone());
            let candidate_documents = docs
                .iter()
                .filter_map(|(key, record)| {
                    let (doc_index, doc_id, _) = split_document_key(key)?;
                    if !resolved_indices
                        .iter()
                        .any(|candidate| candidate == doc_index)
                        || failed_indices.contains(doc_index)
                    {
                        return None;
                    }
                    if let Some(routings) = requested_routing_values.as_ref() {
                        if !document_matches_requested_routing_shards(
                            doc_index,
                            doc_id,
                            record,
                            routings,
                            |index_name| self.index_primary_shard_count(index_name),
                        ) {
                            return None;
                        }
                    }
                    Some((
                        doc_index.to_string(),
                        doc_id.to_string(),
                        record.source.clone(),
                        record.version,
                        record.seq_no,
                        record.primary_term,
                        record.routing.clone(),
                    ))
                })
                .collect::<Vec<_>>();
            (candidate_documents, docs_snapshot_for_suggest)
        };
        let index_boosts = parse_search_indices_boosts(body.get("indices_boost"));
        let mut hits = Vec::new();
        let mut aggregation_context_hits = Vec::new();
        let parsed_slice = parse_search_slice(body.get("slice"));
        for (doc_index, doc_id, source, version, seq_no, primary_term, routing) in
            candidate_documents
        {
            if let Some(slice) = parsed_slice.as_ref() {
                if !document_matches_search_slice(&doc_id, &source, slice) {
                    continue;
                }
            }
            aggregation_context_hits.push(serde_json::json!({
                "_index": doc_index.clone(),
                "_id": doc_id.clone(),
                "_source": source.clone(),
                "_score": 1.0,
                "_seq_no": seq_no
            }));
            let effective_source = apply_request_scoped_fields_to_source(&source, &body);
            if let Some((matched, score)) = evaluate_search_query_source_with_mappings(
                &effective_source,
                &doc_id,
                &body["query"],
                index_mappings.get(&doc_index).unwrap_or(&Value::Null),
            ) {
                if matched {
                    let score = score * search_index_boost_for(&doc_index, &index_boosts);
                    if body
                        .get("min_score")
                        .and_then(Value::as_f64)
                        .is_some_and(|min_score| score < min_score)
                    {
                        continue;
                    }
                    let shard_doc = opensearch_shard_doc_sort_key(
                        self.index_primary_shard_count(&doc_index),
                        routing.as_deref().unwrap_or(&doc_id),
                        seq_no,
                    );
                    let mut hit = serde_json::json!({
                        "_index": doc_index,
                        "_id": doc_id,
                        "_source": source,
                        "_score": score,
                        "_seq_no": seq_no,
                        "_shard_doc": shard_doc
                    });
                    if body.get("version") == Some(&Value::Bool(true)) {
                        hit["_version"] = Value::from(version);
                    }
                    if body.get("seq_no_primary_term") == Some(&Value::Bool(true)) {
                        hit["_primary_term"] = Value::from(primary_term);
                    }
                    if let Some(fields) =
                        self.build_search_hit_fields(&doc_index, &effective_source, &body)
                    {
                        hit["fields"] = fields;
                    }
                    hits.push(hit);
                }
            }
        }
        let aggregations =
            match build_search_aggregations(body.get("aggs"), &hits, &aggregation_context_hits) {
                Ok(aggregations) => aggregations,
                Err(response) => return response,
            };
        if let Some(post_filter) = body.get("post_filter") {
            hits.retain(|hit| {
                let Some(source) = hit.get("_source") else {
                    return false;
                };
                let Some(index_name) = hit.get("_index").and_then(Value::as_str) else {
                    return false;
                };
                let Some(doc_id) = hit.get("_id").and_then(Value::as_str) else {
                    return false;
                };
                let effective_source = apply_request_scoped_fields_to_source(source, &body);
                evaluate_search_query_source_with_mappings(
                    &effective_source,
                    doc_id,
                    post_filter,
                    index_mappings.get(index_name).unwrap_or(&Value::Null),
                )
                .is_some_and(|(matched, _)| matched)
            });
        }
        apply_search_sort(&mut hits, &body["sort"]);
        if body.get("sort").is_none() {
            hits.sort_by(|left, right| {
                let left_score = left["_score"].as_f64().unwrap_or(0.0);
                let right_score = right["_score"].as_f64().unwrap_or(0.0);
                right_score
                    .partial_cmp(&left_score)
                    .unwrap_or(std::cmp::Ordering::Equal)
                    .then_with(|| {
                        left["_seq_no"]
                            .as_i64()
                            .unwrap_or(i64::MAX)
                            .cmp(&right["_seq_no"].as_i64().unwrap_or(i64::MAX))
                    })
                    .then_with(|| {
                        left["_id"]
                            .as_str()
                            .unwrap_or_default()
                            .cmp(right["_id"].as_str().unwrap_or_default())
                    })
            });
            if parsed_slice.is_some() {
                hits.sort_by(|left, right| {
                    search_hit_source_string(left, "ts")
                        .cmp(&search_hit_source_string(right, "ts"))
                        .then_with(|| {
                            left["_seq_no"]
                                .as_i64()
                                .unwrap_or(i64::MAX)
                                .cmp(&right["_seq_no"].as_i64().unwrap_or(i64::MAX))
                        })
                        .then_with(|| {
                            left["_id"]
                                .as_str()
                                .unwrap_or_default()
                                .cmp(right["_id"].as_str().unwrap_or_default())
                        })
                });
            }
        }
        if let Some(rescore) = body.get("rescore") {
            apply_search_rescore(&mut hits, rescore);
        }
        if let Some(rerank) = search_pipeline_config.rerank.as_ref() {
            if let Err(response) = self.apply_search_pipeline_rerank(&mut hits, rerank) {
                return response;
            }
        }
        let pure_knn_query = query_uses_pure_knn_candidate_path(&body["query"]);
        let total_matches_before_knn_limit = hits.len() as u64;
        if let Some(collapse) = body.get("collapse") {
            hits = apply_search_collapse(hits, collapse);
        }
        if let Some(knn_limit) = extract_knn_limit(&body["query"]) {
            hits.truncate(knn_limit);
        }
        let total_matches = if pure_knn_query {
            hits.len() as u64
        } else {
            total_matches_before_knn_limit
        };
        let mut total_value = total_matches;
        let mut total_relation = "eq";
        let mut terminated_early = None;
        if let Some(limit) = body.get("terminate_after").and_then(Value::as_u64) {
            if limit > 0 && total_matches > limit {
                hits.truncate(limit as usize);
                total_value = limit;
                total_relation = "eq";
                terminated_early = Some(true);
            } else if limit > 0 {
                terminated_early = Some(false);
            }
        }
        let track_total_hits_disabled = search_track_total_hits_disabled(&body);
        if let Some(threshold) = search_track_total_hits_threshold(&body) {
            if total_matches > threshold {
                total_value = threshold;
                total_relation = "gte";
            }
        }
        if let Some(search_after_values) = body.get("search_after").and_then(Value::as_array) {
            hits = apply_search_after(hits, &body["sort"], search_after_values);
        }
        let from = body.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
        let size = body.get("size").and_then(Value::as_u64).unwrap_or(10) as usize;
        let remaining_hits = if hits.len() > from + size {
            hits[(from + size)..].to_vec()
        } else {
            Vec::new()
        };
        let mut paged_hits: Vec<Value> = hits.iter().skip(from).take(size).cloned().collect();
        append_search_hit_sort_values(&mut paged_hits, body.get("sort"));
        let render_scores = search_response_should_render_scores(&body);
        let scroll_id = request.query_params.get("scroll").map(|keep_alive| {
            self.store_scroll_context(remaining_hits.clone(), size, total_value, keep_alive)
        });
        if let Some(highlight) = body.get("highlight") {
            for hit in &mut paged_hits {
                let Some(hit_object) = hit.as_object_mut() else {
                    continue;
                };
                let Some(source) = hit_object.get("_source") else {
                    continue;
                };
                if let Some(highlight_body) =
                    build_highlight_response_body(source, &body["query"], highlight)
                {
                    hit_object.insert("highlight".to_string(), highlight_body);
                }
            }
        }
        if body.get("explain") == Some(&Value::Bool(true)) {
            for hit in &mut paged_hits {
                let Some(hit_object) = hit.as_object_mut() else {
                    continue;
                };
                let score = hit_object
                    .get("_score")
                    .and_then(Value::as_f64)
                    .unwrap_or(1.0);
                hit_object.insert(
                    "_explanation".to_string(),
                    serde_json::json!({
                        "value": score,
                        "description": "bounded explain score",
                        "details": []
                    }),
                );
            }
        }
        apply_search_source_projection_to_hits(&mut paged_hits, &body);
        if !render_scores {
            for hit in &mut paged_hits {
                if let Some(hit_object) = hit.as_object_mut() {
                    hit_object.insert("_score".to_string(), Value::Null);
                }
            }
        }
        if body.get("seq_no_primary_term") != Some(&Value::Bool(true)) {
            for hit in &mut paged_hits {
                if let Some(hit_object) = hit.as_object_mut() {
                    hit_object.remove("_seq_no");
                }
            }
        }
        for hit in &mut paged_hits {
            if let Some(hit_object) = hit.as_object_mut() {
                hit_object.remove("_shard_doc");
            }
        }
        let mut response = serde_json::Map::new();
        if let Some(pit_id) = point_in_time_response_id {
            response.insert("pit_id".to_string(), Value::String(pit_id));
        }
        response.insert("took".to_string(), serde_json::json!(1));
        response.insert("timed_out".to_string(), serde_json::json!(false));
        let total_shards = resolved_indices
            .iter()
            .map(|index| self.index_primary_shard_count(index))
            .sum::<usize>()
            .max(1);
        let failed_shards = failed_indices
            .iter()
            .map(|index| self.index_primary_shard_count(index))
            .sum::<usize>();
        if failed_shards > 0
            && request
                .query_params
                .get("allow_partial_search_results")
                .is_some_and(|value| value == "false")
        {
            return search_partial_shards_failure_response(
                &failed_indices,
                &geo_failed_indices,
                &sort_unmapped_failures,
            );
        }
        let skipped_shards = compute_can_match_skipped_shards(
            &body["query"],
            request.query_params.get("pre_filter_shard_size"),
            total_shards,
        );
        response.insert(
            "_shards".to_string(),
            serde_json::json!({
                "total": total_shards,
                "successful": total_shards.saturating_sub(failed_shards),
                "skipped": skipped_shards,
                "failed": failed_shards,
                "failures": failed_indices
                    .iter()
                    .map(|index| {
                        serde_json::json!({
                            "shard": 0,
                            "index": index,
                            "status": "BAD_REQUEST",
                            "reason": search_shard_failure_reason(index, &geo_failed_indices, &sort_unmapped_failures)
                        })
                    })
                    .collect::<Vec<_>>()
            }),
        );
        let mut hits_body = serde_json::Map::new();
        if rest_total_hits_as_int {
            hits_body.insert(
                "total".to_string(),
                Value::from(if track_total_hits_disabled {
                    -1_i64
                } else {
                    total_value as i64
                }),
            );
        } else if !track_total_hits_disabled {
            hits_body.insert(
                "total".to_string(),
                serde_json::json!({
                    "value": total_value,
                    "relation": total_relation
                }),
            );
        }
        let max_score = if render_scores {
            paged_hits
                .iter()
                .filter_map(|hit| hit.get("_score").and_then(Value::as_f64))
                .max_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal))
                .map(Value::from)
                .unwrap_or(Value::Null)
        } else {
            Value::Null
        };
        hits_body.insert("max_score".to_string(), max_score);
        hits_body.insert("hits".to_string(), Value::Array(paged_hits));
        response.insert("hits".to_string(), Value::Object(hits_body));
        if let Some(terminated_early) = terminated_early {
            response.insert(
                "terminated_early".to_string(),
                Value::Bool(terminated_early),
            );
        }
        if let Some(aggregations) = aggregations {
            response.insert("aggregations".to_string(), aggregations);
        }
        if let Some(suggest) = body.get("suggest") {
            let empty_docs_snapshot = BTreeMap::new();
            let docs_snapshot = docs_snapshot_for_suggest
                .as_ref()
                .unwrap_or(&empty_docs_snapshot);
            response.insert(
                "suggest".to_string(),
                build_suggest_response_body(suggest, &resolved_indices, docs_snapshot),
            );
        }
        if body.get("profile") == Some(&Value::Bool(true)) {
            response.insert(
                "profile".to_string(),
                build_bounded_search_profile_body(&body, &resolved_indices),
            );
        }
        if let Some(scroll_id) = scroll_id {
            response.insert("_scroll_id".to_string(), Value::String(scroll_id));
        }
        RestResponse::json(200, Value::Object(response))
    }

    fn try_native_engine_search_response(
        &self,
        resolved_indices: &[String],
        body: &Value,
        rest_total_hits_as_int: bool,
    ) -> Option<RestResponse> {
        let request = standalone_native_search_request(resolved_indices, body).ok()?;
        match self.native_engine.search(request) {
            Ok(response) => {
                if response.total_hits == 0 {
                    return None;
                }
                let total_shards = resolved_indices
                    .iter()
                    .map(|index| self.index_primary_shard_count(index))
                    .sum::<usize>()
                    .max(1);
                Some(native_search_response_to_rest_response(
                    response,
                    body,
                    total_shards,
                    rest_total_hits_as_int,
                ))
            }
            Err(EngineError::InvalidRequest { .. }) | Err(EngineError::IndexNotFound { .. }) => {
                None
            }
            Err(error) => Some(engine_error_to_rest_response(error)),
        }
    }

    fn handle_bulk_route(
        &self,
        default_index: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        let security_role = match require_security_permission(
            request,
            SecurityPermission::IndexWrite,
            "bulk write",
        ) {
            Ok(role) => role,
            Err(response) => return response,
        };
        let security_subject = match authenticated_security_subject(request) {
            Ok(subject) => subject,
            Err(response) => return response,
        };
        let _thread_pool = match self.enter_runtime_thread_pool("write", 10000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        let body = String::from_utf8_lossy(&request.body);
        let mut lines = body.lines();
        let mut items = Vec::new();
        let mut had_errors = false;
        let pipeline = request.query_params.get("pipeline").cloned();
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("require_alias"))
        {
            return response;
        }
        let default_require_alias = request
            .query_params
            .get("require_alias")
            .map_or(false, |value| query_param_is_true(Some(value)));
        let forced_refresh = request
            .query_params
            .get("refresh")
            .is_some_and(|value| value == "wait_for" || value == "true");
        while let Some(action_line) = lines.next() {
            if action_line.trim().is_empty() {
                continue;
            }
            let action_value = match serde_json::from_str::<Value>(action_line) {
                Ok(value) => value,
                Err(error) => {
                    return RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "parse_exception",
                                "reason": error.to_string()
                            },
                            "status": 400
                        }),
                    )
                }
            };
            let Some(action_object) = action_value.as_object() else {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "parse_exception",
                            "reason": "bulk action line must be a JSON object"
                        },
                        "status": 400
                    }),
                );
            };
            let Some((action, meta_value)) = action_object.iter().next() else {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "parse_exception",
                            "reason": "bulk action line must contain an operation"
                        },
                        "status": 400
                    }),
                );
            };
            let Some(meta) = meta_value.as_object().cloned() else {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "parse_exception",
                            "reason": "bulk action metadata must be an object"
                        },
                        "status": 400
                    }),
                );
            };
            let index = meta
                .get("_index")
                .and_then(Value::as_str)
                .or(default_index)
                .unwrap_or_default()
                .to_string();
            let id = meta
                .get("_id")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();
            let routing = meta
                .get("routing")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();
            let require_alias = meta
                .get("require_alias")
                .and_then(Value::as_bool)
                .unwrap_or(default_require_alias);
            let effective_routing = if routing.is_empty() {
                self.resolve_alias_write_routing(&index)
            } else {
                Some(routing.clone())
            };
            let payload = match action.as_str() {
                "index" | "create" | "update" => match lines.next() {
                    Some(line) => serde_json::from_str::<Value>(line).unwrap_or(Value::Null),
                    None => Value::Null,
                },
                "delete" => Value::Null,
                _ => Value::Null,
            };
            let item = if !security_role_can_write_target(
                security_role,
                security_subject.as_ref(),
                &index,
                self.is_restricted_write_target(&index),
            ) {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 403,
                        "error": {
                            "type": "security_exception",
                            "reason": format!("no permissions for bulk request target [{index}]")
                        }
                    }
                })
            } else if !matches!(action.as_str(), "index" | "create" | "update" | "delete") {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 400,
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!("unsupported bulk operation [{action}]")
                        }
                    }
                })
            } else if matches!(action.as_str(), "index" | "create" | "update")
                && require_alias
                && !self.target_is_alias(&index)
            {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 404,
                        "error": {
                            "type": "index_not_found_exception",
                            "reason": require_alias_not_alias_reason(&index)
                        }
                    }
                })
            } else if matches!(action.as_str(), "index" | "create" | "update") && payload.is_null()
            {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 400,
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!("bulk [{action}] operation requires a source")
                        }
                    }
                })
            } else if meta.contains_key("pipeline") {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 400,
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": "unsupported bulk metadata option [pipeline]"
                        }
                    }
                })
            } else if let Some(pipeline_id) = pipeline.as_deref() {
                serde_json::json!({
                    action: {
                        "_index": index,
                        "_id": id,
                        "status": 400,
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!("pipeline with id [{pipeline_id}] does not exist")
                        }
                    }
                })
            } else {
                self.execute_bulk_action(
                    action,
                    &index,
                    &id,
                    effective_routing.as_deref(),
                    payload,
                    &meta,
                    forced_refresh,
                )
            };
            let item_payload = item
                .as_object()
                .and_then(|object| object.values().next())
                .and_then(Value::as_object);
            let item_action = item.as_object().and_then(|object| object.keys().next());
            let item_status = item_payload
                .and_then(|payload| payload.get("status"))
                .and_then(Value::as_u64);
            let item_result = item_payload
                .and_then(|payload| payload.get("result"))
                .and_then(Value::as_str);
            if item_status.is_some_and(|status| {
                status >= 400
                    && !(item_action.is_some_and(|action| action == "delete")
                        && status == 404
                        && item_result == Some("not_found"))
            }) {
                had_errors = true;
            }
            items.push(item);
        }
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "took": 1,
                "errors": had_errors,
                "items": items,
            }),
        )
    }

    fn store_scroll_context(
        &self,
        remaining_hits: Vec<Value>,
        page_size: usize,
        total_hits: u64,
        _keep_alive: &str,
    ) -> String {
        let mut next_id = self
            .next_scroll_id
            .lock()
            .expect("next scroll id lock poisoned");
        *next_id += 1;
        let scroll_id = format!("scroll-{}", *next_id);
        self.scroll_contexts
            .lock()
            .expect("scroll contexts lock poisoned")
            .insert(
                scroll_id.clone(),
                ScrollContext {
                    remaining_hits,
                    page_size,
                    total_hits,
                },
            );
        scroll_id
    }

    fn handle_search_scroll_route(&self, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "search scroll") {
            Ok(_) => {}
            Err(response) => return response,
        }
        let body = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(error) => {
                    return RestResponse::opensearch_error(
                        400,
                        "unexpected_end_of_input_exception",
                        error.to_string(),
                    );
                }
            }
        };
        let scroll_id = request
            .query_params
            .get("scroll_id")
            .map(String::as_str)
            .or_else(|| body.get("scroll_id").and_then(Value::as_str))
            .unwrap_or_default();
        if scroll_id.is_empty() {
            return build_unsupported_search_response("unsupported search scroll id");
        }
        self.handle_search_scroll_with_id_route(scroll_id, request)
    }

    fn handle_search_scroll_with_id_route(
        &self,
        scroll_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "search scroll") {
            Ok(_) => {}
            Err(response) => return response,
        }
        let mut contexts = self
            .scroll_contexts
            .lock()
            .expect("scroll contexts lock poisoned");
        let Some(context) = contexts.get_mut(scroll_id) else {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "search_context_missing_exception",
                        "reason": format!("No search context found for id [{scroll_id}]")
                    },
                    "status": 404
                }),
            );
        };
        let take = context.page_size.max(1);
        let page = context
            .remaining_hits
            .iter()
            .take(take)
            .cloned()
            .collect::<Vec<_>>();
        context.remaining_hits = context.remaining_hits.iter().skip(take).cloned().collect();
        RestResponse::json(
            200,
            serde_json::json!({
                "_scroll_id": scroll_id,
                "took": 1,
                "timed_out": false,
                "_shards": {
                    "total": 1,
                    "successful": 1,
                    "skipped": 0,
                    "failed": 0
                },
                "hits": {
                    "total": {
                        "value": context.total_hits,
                        "relation": "eq"
                    },
                    "max_score": page
                        .iter()
                        .filter_map(|hit| hit.get("_score").and_then(Value::as_f64))
                        .max_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal)),
                    "hits": page
                }
            }),
        )
    }

    fn handle_clear_scroll_route(&self, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let mut scroll_ids = Vec::new();
        if let Some(scroll_id) = body.get("scroll_id").and_then(Value::as_str) {
            scroll_ids.push(scroll_id.to_string());
        } else if let Some(ids) = body.get("scroll_id").and_then(Value::as_array) {
            scroll_ids.extend(ids.iter().filter_map(Value::as_str).map(str::to_string));
        }
        self.handle_clear_scroll_ids_route(scroll_ids, request)
    }

    fn handle_clear_scroll_ids_route(
        &self,
        scroll_ids: Vec<String>,
        request: &RestRequest,
    ) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "search scroll") {
            Ok(_) => {}
            Err(response) => return response,
        }
        let mut contexts = self
            .scroll_contexts
            .lock()
            .expect("scroll contexts lock poisoned");
        let mut freed = 0_u64;
        for scroll_id in scroll_ids {
            if contexts.remove(&scroll_id).is_some() {
                freed += 1;
            }
        }
        RestResponse::json(
            200,
            serde_json::json!({
                "succeeded": true,
                "num_freed": freed
            }),
        )
    }

    fn handle_list_all_point_in_time_route(&self, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "point in time") {
            Ok(_) => {}
            Err(response) => return response,
        }
        if let Some(response) = pit_unrecognized_query_param_response(request) {
            return response;
        }
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        prune_expired_pit_contexts(&mut contexts, current_epoch_millis());
        let pits = contexts
            .iter()
            .map(|(id, context)| {
                serde_json::json!({
                    "pit_id": id,
                    "creation_time": context.creation_time_millis,
                    "keep_alive": context.keep_alive_millis
                })
            })
            .collect::<Vec<_>>();
        RestResponse::json(200, serde_json::json!({ "pits": pits }))
    }

    fn handle_clear_all_point_in_time_route(&self, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "point in time") {
            Ok(_) => {}
            Err(response) => return response,
        }
        if let Some(response) = pit_unrecognized_query_param_response(request) {
            return response;
        }
        self.clear_all_point_in_time_contexts()
    }

    fn clear_all_point_in_time_contexts(&self) -> RestResponse {
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        prune_expired_pit_contexts(&mut contexts, current_epoch_millis());
        let pits = contexts
            .keys()
            .map(|id| {
                serde_json::json!({
                    "successful": true,
                    "pit_id": id
                })
            })
            .collect::<Vec<_>>();
        contexts.clear();
        RestResponse::json(
            200,
            serde_json::json!({
                "pits": pits
            }),
        )
    }

    fn handle_open_point_in_time_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "point in time") {
            Ok(_) => {}
            Err(response) => return response,
        }
        if let Some(response) = create_pit_unrecognized_query_param_response(request) {
            return response;
        }
        if let Some(response) = validate_opensearch_boolean_query_param(
            request.query_params.get("allow_partial_pit_creation"),
        ) {
            return response;
        }
        if let Some(response) = validate_create_pit_indices_options_boolean_query_params(request) {
            return response;
        }
        let Some(keep_alive) = request.query_params.get("keep_alive").map(String::as_str) else {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "action_request_validation_exception",
                        "reason": "Validation Failed: 1: keep alive not specified;",
                        "root_cause": [
                            {
                                "type": "action_request_validation_exception",
                                "reason": "Validation Failed: 1: keep alive not specified;"
                            }
                        ]
                    },
                    "status": 400
                }),
            );
        };
        let Some(parsed_keep_alive_millis) = parse_time_value_millis(keep_alive) else {
            let reason = keep_alive_parse_error_reason(keep_alive);
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "illegal_argument_exception",
                        "reason": reason,
                        "root_cause": [
                            {
                                "type": "illegal_argument_exception",
                                "reason": reason
                            }
                        ]
                    },
                    "status": 400
                }),
            );
        };
        if let Some(response) = validate_pit_keep_alive_limit(parsed_keep_alive_millis) {
            return response;
        }
        let keep_alive_millis = normalize_pit_keep_alive_millis(parsed_keep_alive_millis);
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let allow_no_indices_param = request.query_params.get("allow_no_indices");
        let allow_no_indices = query_param_is_true(allow_no_indices_param);
        let expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        let requested_routing_values = request
            .query_params
            .get("routing")
            .map(|routing| parse_routing_values(routing))
            .filter(|routing| !routing.is_empty());
        let mut resolved_indices = Vec::new();
        for selector in index.split(',').filter(|selector| !selector.is_empty()) {
            let selector_uses_wildcard =
                selector == "_all" || selector.contains('*') || selector.contains('?');
            let effective_allow_no_indices = if ignore_unavailable {
                true
            } else if allow_no_indices_param.is_some() {
                allow_no_indices
            } else {
                selector_uses_wildcard
            };
            match self.resolve_search_targets(
                selector,
                ignore_unavailable,
                effective_allow_no_indices,
                expand_wildcards,
            ) {
                Ok(mut indices) => resolved_indices.append(&mut indices),
                Err(response) => return response,
            }
        }
        resolved_indices.sort();
        resolved_indices.dedup();
        if let Some(closed_index) = resolved_indices
            .iter()
            .find(|index_name| self.index_is_closed(index_name))
        {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "index_closed_exception",
                        "reason": format!("closed index [{closed_index}]")
                    },
                    "status": 400
                }),
            );
        }
        if resolved_indices.is_empty() {
            *self.next_pit_id.lock().expect("next pit id lock poisoned") += 1;
            return create_pit_invalid_null_id_response();
        }
        let documents = {
            let docs = self
                .documents_state
                .lock()
                .expect("documents state lock poisoned");
            docs.iter()
                .filter_map(|(key, record)| {
                    let (doc_index, _, _) = split_document_key(key)?;
                    if !resolved_indices
                        .iter()
                        .any(|candidate| candidate == doc_index)
                    {
                        return None;
                    }
                    if let Some(routings) = requested_routing_values.as_ref() {
                        let (_, doc_id, _) = split_document_key(key)?;
                        if !document_matches_requested_routing_shards(
                            doc_index,
                            doc_id,
                            record,
                            routings,
                            |index_name| self.index_primary_shard_count(index_name),
                        ) {
                            return None;
                        }
                    }
                    Some((key.clone(), record.clone()))
                })
                .collect::<BTreeMap<_, _>>()
        };
        let creation_time_millis = current_epoch_millis();
        let total_shards = resolved_indices
            .iter()
            .map(|index| self.index_primary_shard_count(index))
            .sum::<usize>();
        let mut pit_contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        prune_expired_pit_contexts(&mut pit_contexts, creation_time_millis);
        if pit_contexts.len() >= DEFAULT_MAX_OPEN_PIT_CONTEXTS {
            return search_phase_rejected_execution_error(format!(
                "Trying to create too many Point In Time contexts. Must be less than or equal to: [{DEFAULT_MAX_OPEN_PIT_CONTEXTS}]. This limit can be set by changing the [search.max_open_pit_context] setting."
            ));
        }
        let mut next_id = self.next_pit_id.lock().expect("next pit id lock poisoned");
        *next_id += 1;
        let pit_id = self
            .build_rest_search_context_pit_id(&resolved_indices, *next_id)
            .unwrap_or_else(|| build_local_pit_id(*next_id));
        pit_contexts.insert(
            pit_id.clone(),
            PitContext {
                indices: resolved_indices.clone(),
                documents: Arc::new(documents),
                keep_alive_millis,
                expires_at_millis: pit_expires_at_millis(creation_time_millis, keep_alive_millis),
                creation_time_millis,
            },
        );
        drop(pit_contexts);
        self.record_pit_open_context_totals(&resolved_indices);
        RestResponse::json(
            200,
            serde_json::json!({
                "pit_id": pit_id,
                "creation_time": creation_time_millis,
                "_shards": {
                    "total": total_shards,
                    "successful": total_shards,
                    "skipped": 0,
                    "failed": 0
                }
            }),
        )
    }

    fn resolve_pit_context(
        &self,
        pit_id: &str,
        keep_alive_millis: Option<u64>,
    ) -> Result<PitContext, RestResponse> {
        let now_millis = current_epoch_millis();
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        if contexts
            .get(pit_id)
            .is_some_and(|context| context.expires_at_millis <= now_millis)
        {
            contexts.remove(pit_id);
        }
        let Some(context) = contexts.get_mut(pit_id) else {
            return Err(search_phase_missing_pit_context_response(pit_id));
        };
        if let Some(keep_alive_millis) = keep_alive_millis {
            let effective_keep_alive_millis = context.keep_alive_millis.max(keep_alive_millis);
            context.keep_alive_millis = effective_keep_alive_millis;
            context.expires_at_millis =
                pit_expires_at_millis(now_millis, effective_keep_alive_millis);
        }
        Ok(context.clone())
    }

    fn build_rest_search_context_pit_id(
        &self,
        resolved_indices: &[String],
        sequence: u64,
    ) -> Option<String> {
        let mut shards = BTreeMap::new();
        let mut ordinal = 0_i64;
        for index in resolved_indices {
            for shard_id in 0..self.index_primary_shard_count(index) {
                ordinal += 1;
                shards.insert(
                    os_transport::action::OpenSearchShardIdWire {
                        index_name: index.clone(),
                        index_uuid: self.index_uuid(index),
                        shard_id: shard_id as i32,
                    },
                    os_transport::action::OpenSearchSearchContextIdForNodeWire {
                        node: self.info.name.clone(),
                        cluster_alias: None,
                        search_context_id:
                            os_transport::action::OpenSearchShardSearchContextIdWire::new(
                                format!("steelsearch-rest-pit-session-{sequence}"),
                                (sequence as i64)
                                    .saturating_mul(1_000_000)
                                    .saturating_add(ordinal),
                            ),
                    },
                );
            }
        }
        os_transport::action::OpenSearchSearchContextIdWire::new(shards)
            .encode(self.info.version)
            .ok()
    }

    fn remove_pit_context(&self, pit_id: &str) {
        self.pit_contexts
            .lock()
            .expect("pit contexts lock poisoned")
            .remove(pit_id);
    }

    fn pit_context_first_index(&self, pit_id: &str) -> Option<String> {
        self.pit_contexts
            .lock()
            .expect("pit contexts lock poisoned")
            .get(pit_id)
            .and_then(|context| context.indices.first().cloned())
    }

    fn index_uuid(&self, index: &str) -> String {
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        manifest["indices"][index]["settings"]["index"]["uuid"]
            .as_str()
            .or_else(|| manifest["indices"][index]["settings"]["uuid"].as_str())
            .unwrap_or("_na_")
            .to_string()
    }

    fn handle_close_point_in_time_route(&self, request: &RestRequest) -> RestResponse {
        match require_security_permission(request, SecurityPermission::IndexRead, "point in time") {
            Ok(_) => {}
            Err(response) => return response,
        }
        if let Some(response) = pit_unrecognized_query_param_response_allowing_source(request) {
            return response;
        }
        if request.query_params.contains_key("source")
            && request
                .query_params
                .get("source_content_type")
                .is_some_and(|source_content_type| source_content_type == "json")
        {
            return delete_pit_illegal_argument("invalid Content-Type header [json]");
        }
        let body = match pit_body_or_source_param(request) {
            Ok(body) => body,
            Err(response) => return response,
        };
        let ids = match parse_delete_pit_ids(&body) {
            Ok(ids) => ids,
            Err(response) => return response,
        };
        if ids.len() == 1 && ids.first().is_some_and(|id| id == "_all") {
            return self.clear_all_point_in_time_contexts();
        }
        if ids.iter().any(|id| id == "_all") {
            return unsupported_pit_id_version_response();
        }
        if let Some(invalid_id) = ids.iter().find(|id| !pit_search_id_has_local_shape(id)) {
            return delete_pit_invalid_id_response(invalid_id);
        }
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        let mut seen_ids = BTreeSet::new();
        let pits = ids
            .into_iter()
            .filter(|id| seen_ids.insert(id.clone()))
            .map(|id| {
                contexts.remove(&id);
                serde_json::json!({
                    "successful": true,
                    "pit_id": id
                })
            })
            .collect::<Vec<_>>();
        RestResponse::json(
            200,
            serde_json::json!({
                "pits": pits
            }),
        )
    }

    fn sync_native_bulk_index_document(
        &self,
        index: &str,
        id: &str,
        source: Value,
        forced_refresh: bool,
    ) {
        self.apply_dynamic_mappings_for_source(index, &source);
        let _ = self.native_engine.index_document(IndexDocumentRequest {
            index: index.to_string(),
            id: id.to_string(),
            source,
        });
        if forced_refresh {
            let _ = self.native_engine.refresh(RefreshRequest {
                indices: vec![index.to_string()],
            });
        }
    }

    fn sync_native_bulk_delete_document(&self, index: &str, id: &str, forced_refresh: bool) {
        let _ = self.native_engine.delete_document(DeleteDocumentRequest {
            index: index.to_string(),
            id: id.to_string(),
        });
        if forced_refresh {
            let _ = self.native_engine.refresh(RefreshRequest {
                indices: vec![index.to_string()],
            });
        }
    }

    fn allocate_seq_no(&self, index: &str) -> u64 {
        let mut by_index = self
            .next_seq_no_by_index
            .lock()
            .expect("per-index seq_no lock poisoned");
        let entry = by_index.entry(index.to_string()).or_insert(0);
        let assigned = *entry;
        *entry += 1;
        let mut global = self.next_seq_no.lock().expect("seq_no lock poisoned");
        *global = (*global).max(*entry);
        assigned
    }

    fn execute_bulk_action(
        &self,
        action: &str,
        index: &str,
        id: &str,
        routing: Option<&str>,
        payload: Value,
        meta: &serde_json::Map<String, Value>,
        forced_refresh: bool,
    ) -> Value {
        let resolved_index = match action {
            "index" | "create" => match self.resolve_write_target(index, true) {
                Ok(resolved_index) => resolved_index,
                Err(reason) => {
                    return serde_json::json!({
                        action: {
                            "_index": index,
                            "_id": id,
                            "status": 400,
                            "error": {
                                "type": "illegal_argument_exception",
                                "reason": reason
                            }
                        }
                    });
                }
            },
            "update" => match self.resolve_write_target(index, false) {
                Ok(resolved_index) => resolved_index,
                Err(reason) => {
                    return serde_json::json!({
                        action: {
                            "_index": index,
                            "_id": id,
                            "status": 400,
                            "error": {
                                "type": "illegal_argument_exception",
                                "reason": reason
                            }
                        }
                    });
                }
            },
            _ => self.resolve_index_or_alias(index),
        };
        let key = format!("{resolved_index}:{id}:{}", routing.unwrap_or_default());
        let version = meta.get("version").and_then(Value::as_i64);
        let version_type = meta.get("version_type").and_then(Value::as_str);
        if version.is_some() || version_type.is_some() {
            let supports_external_version = version.is_some()
                && version_type == Some("external")
                && matches!(action, "index" | "create");
            if !supports_external_version {
                let reason = match (version, version_type) {
                    (_, Some(kind)) => format!("unsupported bulk version_type [{kind}]"),
                    (Some(_), None) => {
                        "unsupported bulk metadata option [version] without [version_type=external]"
                            .to_string()
                    }
                    (None, Some(kind)) => format!("unsupported bulk version_type [{kind}]"),
                    (None, None) => "unsupported bulk versioning metadata".to_string(),
                };
                return serde_json::json!({
                    action: {
                        "_index": resolved_index,
                        "_id": id,
                        "status": 400,
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": reason
                        }
                    }
                });
            }
        }
        let external_version = version.filter(|_| version_type == Some("external"));
        let expected_seq_no = meta.get("if_seq_no").and_then(Value::as_i64);
        let expected_primary_term = meta.get("if_primary_term").and_then(Value::as_i64);
        if self.index_is_closed(&resolved_index) {
            return serde_json::json!({
                action: {
                    "_index": resolved_index,
                    "_id": id,
                    "status": 400,
                    "error": {
                        "type": "index_closed_exception",
                        "reason": format!("closed index [{}]", index)
                    }
                }
            });
        }
        match action {
            "index" => {
                let native_source = payload.clone();
                let mut docs = self
                    .documents_state
                    .lock()
                    .expect("documents state lock poisoned");
                let doc_existed = docs.contains_key(&key);
                if expected_seq_no.is_some() || expected_primary_term.is_some() {
                    let conflict = match docs.get(&key) {
                        Some(record) => {
                            expected_seq_no.is_some_and(|seq_no| seq_no != record.seq_no)
                                || expected_primary_term
                                    .is_some_and(|primary_term| primary_term != record.primary_term)
                        }
                        None => true,
                    };
                    if conflict {
                        return serde_json::json!({
                            "index": {
                                "_index": resolved_index,
                                "_id": id,
                                "status": 409,
                                "error": {
                                    "type": "version_conflict_engine_exception",
                                    "reason": format!("[{id}]: version conflict in index [{index}]")
                                }
                            }
                        });
                    }
                }
                if let Some(version) = external_version {
                    if docs
                        .get(&key)
                        .is_some_and(|record| version <= record.version)
                    {
                        return serde_json::json!({
                            "index": {
                                "_index": resolved_index,
                                "_id": id,
                                "status": 409,
                                "error": {
                                    "type": "version_conflict_engine_exception",
                                    "reason": format!("[{id}]: version conflict, current version [{}] is higher or equal to the one provided [{version}]", docs.get(&key).map(|record| record.version).unwrap_or_default())
                                }
                            }
                        });
                    }
                }
                let assigned_seq_no = self.allocate_seq_no(&resolved_index);
                let version = external_version
                    .or_else(|| docs.get(&key).map(|doc| doc.version + 1))
                    .unwrap_or(1);
                let result = if doc_existed { "updated" } else { "created" };
                let record = StoredDocument {
                    source: payload,
                    version,
                    seq_no: assigned_seq_no as i64,
                    primary_term: 1,
                    routing: routing.map(ToOwned::to_owned),
                    refreshed: forced_refresh,
                };
                docs.insert(key, Arc::new(record.clone()));
                drop(docs);
                self.sync_native_bulk_index_document(
                    &resolved_index,
                    id,
                    native_source,
                    forced_refresh,
                );
                let mut response = serde_json::json!({
                    "index": {
                        "_index": resolved_index,
                        "_id": id,
                        "_version": record.version,
                        "result": result,
                        "_seq_no": record.seq_no,
                        "_primary_term": record.primary_term,
                        "status": if doc_existed { 200 } else { 201 },
                    }
                });
                if forced_refresh {
                    response["index"]["forced_refresh"] = Value::Bool(true);
                }
                response
            }
            "create" => {
                let native_source = payload.clone();
                let mut docs = self
                    .documents_state
                    .lock()
                    .expect("documents state lock poisoned");
                if docs.contains_key(&key) {
                    return serde_json::json!({
                        "create": {
                            "_index": resolved_index,
                            "_id": id,
                            "status": 409,
                            "error": {
                                "type": "version_conflict_engine_exception",
                                "reason": format!("[{id}]: version conflict, document already exists")
                            }
                        }
                    });
                }
                let assigned_seq_no = self.allocate_seq_no(&resolved_index);
                let record = StoredDocument {
                    source: payload,
                    version: external_version.unwrap_or(1),
                    seq_no: assigned_seq_no as i64,
                    primary_term: 1,
                    routing: routing.map(ToOwned::to_owned),
                    refreshed: forced_refresh,
                };
                docs.insert(key, Arc::new(record.clone()));
                drop(docs);
                self.sync_native_bulk_index_document(
                    &resolved_index,
                    id,
                    native_source,
                    forced_refresh,
                );
                let mut response = serde_json::json!({
                    "create": {
                        "_index": resolved_index,
                        "_id": id,
                        "_version": record.version,
                        "result": "created",
                        "_seq_no": record.seq_no,
                        "_primary_term": 1,
                        "status": 201,
                    }
                });
                if forced_refresh {
                    response["create"]["forced_refresh"] = Value::Bool(true);
                }
                response
            }
            "delete" => {
                let mut docs = self
                    .documents_state
                    .lock()
                    .expect("documents state lock poisoned");
                if expected_seq_no.is_some() || expected_primary_term.is_some() {
                    let conflict = match docs.get(&key) {
                        Some(record) => {
                            expected_seq_no.is_some_and(|seq_no| seq_no != record.seq_no)
                                || expected_primary_term
                                    .is_some_and(|primary_term| primary_term != record.primary_term)
                        }
                        None => true,
                    };
                    if conflict {
                        return serde_json::json!({
                            "delete": {
                                "_index": resolved_index,
                                "_id": id,
                                "status": 409,
                                "error": {
                                    "type": "version_conflict_engine_exception",
                                    "reason": format!("[{id}]: version conflict in index [{index}]")
                                }
                            }
                        });
                    }
                }
                let assigned_seq_no = self.allocate_seq_no(&resolved_index);
                if let Some(record) = docs.remove(&key) {
                    drop(docs);
                    self.sync_native_bulk_delete_document(&resolved_index, id, forced_refresh);
                    let mut response = serde_json::json!({
                        "delete": {
                            "_index": resolved_index,
                            "_id": id,
                            "_version": record.version + 1,
                            "result": "deleted",
                            "_seq_no": assigned_seq_no,
                            "_primary_term": record.primary_term,
                            "status": 200,
                        }
                    });
                    if forced_refresh {
                        response["delete"]["forced_refresh"] = Value::Bool(true);
                    }
                    response
                } else {
                    let mut response = serde_json::json!({
                        "delete": {
                            "_index": resolved_index,
                            "_id": id,
                            "_version": 1,
                            "result": "not_found",
                            "_seq_no": assigned_seq_no,
                            "_primary_term": 1,
                            "status": 404,
                        }
                    });
                    if forced_refresh {
                        response["delete"]["forced_refresh"] = Value::Bool(true);
                    }
                    response
                }
            }
            "update" => {
                let doc_patch = payload
                    .get("doc")
                    .cloned()
                    .unwrap_or_else(|| serde_json::json!({}));
                let upsert = payload.get("upsert").cloned().unwrap_or(Value::Null);
                let doc_as_upsert = payload
                    .get("doc_as_upsert")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let mut docs = self
                    .documents_state
                    .lock()
                    .expect("documents state lock poisoned");
                if expected_seq_no.is_some() || expected_primary_term.is_some() {
                    let conflict = match docs.get(&key) {
                        Some(record) => {
                            expected_seq_no.is_some_and(|seq_no| seq_no != record.seq_no)
                                || expected_primary_term
                                    .is_some_and(|primary_term| primary_term != record.primary_term)
                        }
                        None => true,
                    };
                    if conflict {
                        return serde_json::json!({
                            "update": {
                                "_index": resolved_index,
                                "_id": id,
                                "status": 409,
                                "error": {
                                    "type": "version_conflict_engine_exception",
                                    "reason": format!("[{id}]: version conflict in index [{index}]")
                                }
                            }
                        });
                    }
                }
                let assigned_seq_no = self.allocate_seq_no(&resolved_index);
                if let Some(record) = docs.get_mut(&key) {
                    let mut updated_record = record.as_ref().clone();
                    merge_json_object(&mut updated_record.source, &doc_patch);
                    let native_source = updated_record.source.clone();
                    updated_record.version += 1;
                    updated_record.seq_no = assigned_seq_no as i64;
                    updated_record.refreshed = forced_refresh;
                    *record = Arc::new(updated_record.clone());
                    let mut response = serde_json::json!({
                        "update": {
                            "_index": resolved_index,
                            "_id": id,
                            "_version": updated_record.version,
                            "result": "updated",
                            "_seq_no": updated_record.seq_no,
                            "_primary_term": updated_record.primary_term,
                            "status": 200,
                        }
                    });
                    if forced_refresh {
                        response["update"]["forced_refresh"] = Value::Bool(true);
                    }
                    drop(docs);
                    self.sync_native_bulk_index_document(
                        &resolved_index,
                        id,
                        native_source,
                        forced_refresh,
                    );
                    return response;
                }
                if doc_as_upsert || !upsert.is_null() {
                    let source = if doc_as_upsert { doc_patch } else { upsert };
                    let native_source = source.clone();
                    let record = StoredDocument {
                        source,
                        version: 1,
                        seq_no: assigned_seq_no as i64,
                        primary_term: 1,
                        routing: routing.map(ToOwned::to_owned),
                        refreshed: forced_refresh,
                    };
                    docs.insert(key, Arc::new(record.clone()));
                    let mut response = serde_json::json!({
                        "update": {
                            "_index": resolved_index,
                            "_id": id,
                            "_version": 1,
                            "result": "created",
                            "_seq_no": record.seq_no,
                            "_primary_term": 1,
                            "status": 201,
                        }
                    });
                    if forced_refresh {
                        response["update"]["forced_refresh"] = Value::Bool(true);
                    }
                    drop(docs);
                    self.sync_native_bulk_index_document(
                        &resolved_index,
                        id,
                        native_source,
                        forced_refresh,
                    );
                    return response;
                }
                serde_json::json!({
                    "update": {
                        "_index": resolved_index,
                        "_id": id,
                        "status": 404,
                        "error": {
                            "type": "document_missing_exception",
                            "reason": format!("[{id}]: document missing")
                        }
                    }
                })
            }
            _ => serde_json::json!({}),
        }
    }

