    fn handle_weighted_routing_put_route(
        &self,
        attribute: &str,
        request: &RestRequest,
    ) -> RestResponse {
        let awareness_attributes =
            self.cluster_setting_csv("cluster.routing.allocation.awareness.attributes");
        if !awareness_attributes
            .iter()
            .any(|configured| configured == attribute)
        {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "action_request_validation_exception",
                            "reason": format!("Validation Failed: 1: invalid awareness attribute {attribute} requested for weighted routing;")
                        }],
                        "type": "action_request_validation_exception",
                        "reason": format!("Validation Failed: 1: invalid awareness attribute {attribute} requested for weighted routing;")
                    },
                    "status": 400
                }),
            );
        }
        let request_body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let Some(requested_version) = request_body.get("_version").and_then(Value::as_i64) else {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "action_request_validation_exception",
                            "reason": "Validation Failed: 1: Version is missing;"
                        }],
                        "type": "action_request_validation_exception",
                        "reason": "Validation Failed: 1: Version is missing;"
                    },
                    "status": 400
                }),
            );
        };
        let weights = request_body
            .get("weights")
            .cloned()
            .unwrap_or_else(|| serde_json::json!({}));
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let current_version = manifest["cluster_admin_state"]["weighted_routing_version"]
            .as_i64()
            .unwrap_or(-1);
        if requested_version != current_version {
            return RestResponse::json(
                409,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "unsupported_weighted_routing_state_exception",
                            "reason": format!("requested version is {requested_version} but cluster weighted routing metadata is at a different version {current_version} ")
                        }],
                        "type": "unsupported_weighted_routing_state_exception",
                        "reason": format!("requested version is {requested_version} but cluster weighted routing metadata is at a different version {current_version} ")
                    },
                    "status": 409
                }),
            );
        }
        manifest["cluster_admin_state"]["weighted_routing"][attribute] =
            serde_json::json!({ "weights": weights });
        manifest["cluster_admin_state"]["weighted_routing_version"] =
            serde_json::json!(current_version + 1);
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_weighted_routing_delete_route(
        &self,
        attribute: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(attribute) = attribute {
            let awareness_attributes =
                self.cluster_setting_csv("cluster.routing.allocation.awareness.attributes");
            if !awareness_attributes
                .iter()
                .any(|configured| configured == attribute)
            {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "root_cause": [{
                                "type": "action_request_validation_exception",
                                "reason": format!("Validation Failed: 1: invalid awareness attribute {attribute} requested for weighted routing;")
                            }],
                            "type": "action_request_validation_exception",
                            "reason": format!("Validation Failed: 1: invalid awareness attribute {attribute} requested for weighted routing;")
                        },
                        "status": 400
                    }),
                );
            }
        }
        let request_body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let requested_version = request_body
            .get("_version")
            .and_then(Value::as_i64)
            .unwrap_or(-2);
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let current_version = manifest["cluster_admin_state"]["weighted_routing_version"]
            .as_i64()
            .unwrap_or(-1);
        if requested_version != current_version {
            return RestResponse::json(
                409,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "unsupported_weighted_routing_state_exception",
                            "reason": format!("requested version is {requested_version} but cluster weighted routing metadata is at a different version {current_version} ")
                        }],
                        "type": "unsupported_weighted_routing_state_exception",
                        "reason": format!("requested version is {requested_version} but cluster weighted routing metadata is at a different version {current_version} ")
                    },
                    "status": 409
                }),
            );
        }
        if let Some(attribute) = attribute {
            let Some(weighted_routing) =
                manifest["cluster_admin_state"]["weighted_routing"].as_object_mut()
            else {
                return RestResponse::json(
                    404,
                    serde_json::json!({
                        "error": {
                            "root_cause": [{
                                "type": "resource_not_found_exception",
                                "reason": format!("weighted routing metadata does not have weights set for awareness attribute {attribute}")
                            }],
                            "type": "resource_not_found_exception",
                            "reason": format!("weighted routing metadata does not have weights set for awareness attribute {attribute}")
                        },
                        "status": 404
                    }),
                );
            };
            let missing = weighted_routing
                .get(attribute)
                .and_then(|state| state.get("weights"))
                .and_then(Value::as_object)
                .map(|weights| weights.is_empty())
                .unwrap_or(true);
            if missing {
                return RestResponse::json(
                    404,
                    serde_json::json!({
                        "error": {
                            "root_cause": [{
                                "type": "resource_not_found_exception",
                                "reason": format!("weighted routing metadata does not have weights set for awareness attribute {attribute}")
                            }],
                            "type": "resource_not_found_exception",
                            "reason": format!("weighted routing metadata does not have weights set for awareness attribute {attribute}")
                        },
                        "status": 404
                    }),
                );
            }
            weighted_routing.remove(attribute);
            manifest["cluster_admin_state"]["weighted_routing_version"] =
                serde_json::json!(current_version + 1);
        } else {
            let has_weights = manifest["cluster_admin_state"]["weighted_routing"]
                .as_object()
                .cloned()
                .unwrap_or_default()
                .values()
                .filter_map(|state| state.get("weights"))
                .filter_map(Value::as_object)
                .any(|weights| !weights.is_empty());
            if !has_weights {
                return RestResponse::json(
                    404,
                    serde_json::json!({
                        "error": {
                            "root_cause": [{
                                "type": "resource_not_found_exception",
                                "reason": "weighted routing metadata does not have weights set"
                            }],
                            "type": "resource_not_found_exception",
                            "reason": "weighted routing metadata does not have weights set"
                        },
                        "status": 404
                    }),
                );
            }
            manifest["cluster_admin_state"]["weighted_routing"] = serde_json::json!({});
            manifest["cluster_admin_state"]["weighted_routing_version"] =
                serde_json::json!(current_version + 1);
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_voting_config_exclusions_post_route(&self, request: &RestRequest) -> RestResponse {
        let node_names = request
            .query_params
            .get("node_names")
            .map(String::as_str)
            .unwrap_or_default()
            .split(',')
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
            .collect::<BTreeSet<_>>();
        if node_names.is_empty() {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "action_request_validation_exception",
                            "reason": "Validation Failed: 1: node_names or node_ids is missing;"
                        }],
                        "type": "action_request_validation_exception",
                        "reason": "Validation Failed: 1: node_names or node_ids is missing;"
                    },
                    "status": 400
                }),
            );
        }
        if request
            .query_params
            .get("timeout")
            .is_some_and(|timeout| timeout == "1ms")
        {
            let exclusions = node_names.iter().cloned().collect::<Vec<_>>().join(",");
            return RestResponse::json(
                500,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "timeout_exception",
                            "reason": format!("timed out waiting for voting config exclusions [{exclusions}] to take effect")
                        }],
                        "type": "timeout_exception",
                        "reason": format!("timed out waiting for voting config exclusions [{exclusions}] to take effect")
                    },
                    "status": 500
                }),
            );
        }
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let existing = manifest["cluster_admin_state"]["voting_config_exclusions"]
            .as_array()
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter_map(|value| value.as_str().map(ToOwned::to_owned))
            .collect::<BTreeSet<_>>();
        let merged = existing
            .into_iter()
            .chain(node_names)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .map(Value::String)
            .collect::<Vec<_>>();
        manifest["cluster_admin_state"]["voting_config_exclusions"] = Value::Array(merged);
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::raw(200, "", "application/json")
    }

    fn handle_voting_config_exclusions_delete_route(&self) -> RestResponse {
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        manifest["cluster_admin_state"]["voting_config_exclusions"] = Value::Array(Vec::new());
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::raw(200, "", "application/json")
    }

    fn handle_cluster_reroute_route(&self, request: &RestRequest) -> RestResponse {
        let _thread_pool = match self.enter_runtime_thread_pool("cluster_manager", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        let state = self.cluster_state_body();
        let mut response = serde_json::Map::new();
        response.insert("acknowledged".to_string(), Value::Bool(true));
        response.insert(
            "state".to_string(),
            serde_json::json!({
                "cluster_uuid": state["cluster_uuid"].clone(),
                "version": state["version"].clone(),
                "state_uuid": state["state_uuid"].clone(),
                "master_node": state["master_node"].clone(),
                "cluster_manager_node": state["master_node"].clone(),
                "blocks": state["blocks"].clone(),
                "nodes": state["nodes"].clone(),
                "routing_table": state["routing_table"].clone(),
                "routing_nodes": state["routing_nodes"].clone()
            }),
        );
        if request
            .query_params
            .get("explain")
            .is_some_and(|value| value == "true")
        {
            response.insert("explanations".to_string(), Value::Array(Vec::new()));
        }
        RestResponse::json(200, Value::Object(response))
    }

    fn cluster_setting_csv(&self, key: &str) -> Vec<String> {
        let state = self
            .cluster_settings_state
            .lock()
            .expect("cluster settings state lock poisoned");
        let transient = state
            .get("transient")
            .and_then(Value::as_object)
            .and_then(|section| section.get(key))
            .and_then(Value::as_str);
        let persistent = state
            .get("persistent")
            .and_then(Value::as_object)
            .and_then(|section| section.get(key))
            .and_then(Value::as_str);
        transient
            .or(persistent)
            .unwrap_or_default()
            .split(',')
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
            .collect()
    }

    fn handle_tasks_get_route(&self, request: &RestRequest) -> RestResponse {
        let Some(task_id) = request.path.strip_prefix("/_tasks/") else {
            return RestResponse::not_found_for(request.method, &request.path);
        };
        if task_id.is_empty() || task_id == "_cancel" {
            return RestResponse::not_found_for(request.method, &request.path);
        }
        if let Some(response) =
            validate_tasks_boolean_query_params(request, &["wait_for_completion"])
        {
            return response;
        }
        if let Some(response) = validate_tasks_time_query_params(request, &["timeout"]) {
            return response;
        }
        if let Some(task) = self.find_task(task_id) {
            return RestResponse::json(
                200,
                tasks_route_registration::invoke_tasks_get_live_route(&serde_json::json!({
                    "task": task
                })),
            );
        }
        RestResponse::json(
            404,
            tasks_route_registration::build_unknown_task_error(task_id),
        )
    }

    fn handle_tasks_list_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(group_by) = invalid_tasks_group_by(request.query_params.get("group_by")) {
            return invalid_tasks_group_by_response(group_by);
        }
        if let Some(response) =
            validate_tasks_boolean_query_params(request, &["detailed", "wait_for_completion"])
        {
            return response;
        }
        if let Some(response) = validate_tasks_time_query_params(request, &["timeout"]) {
            return response;
        }
        let body = self.tasks_body();
        let response = match request.query_params.get("group_by").map(String::as_str) {
            Some("nodes") | None => tasks_route_registration::invoke_tasks_list_live_route(&body),
            Some("parents") => {
                tasks_route_registration::invoke_tasks_list_by_parent_live_route(&body)
            }
            Some("none") => tasks_route_registration::invoke_tasks_list_flat_live_route(&body),
            Some(_) => unreachable!("invalid task group_by is rejected before response shaping"),
        };
        RestResponse::json(200, response)
    }

    fn handle_cluster_pending_tasks_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_tasks_boolean_query_params(request, &["local"]) {
            return response;
        }
        if let Some(response) = validate_tasks_time_query_params(
            request,
            &["cluster_manager_timeout", "master_timeout"],
        ) {
            return response;
        }
        RestResponse::json(
            200,
            pending_tasks_route_registration::invoke_pending_tasks_live_route(
                &self.pending_tasks_body(),
            ),
        )
    }

    fn handle_tasks_cancel_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(group_by) = invalid_tasks_group_by(request.query_params.get("group_by")) {
            return invalid_tasks_group_by_response(group_by);
        }
        if let Some(response) =
            validate_tasks_boolean_query_params(request, &["wait_for_completion"])
        {
            return response;
        }
        if let Some(parent_task_id) = request.query_params.get("parent_task_id") {
            let tasks = self.tasks_matching_parent_task_id(parent_task_id);
            if tasks.is_empty() {
                return RestResponse::json(
                    200,
                    serde_json::json!({
                        "nodes": {},
                        "task_failures": [],
                        "node_failures": []
                    }),
                );
            }
            for task in &tasks {
                let cancellable = task
                    .get("cancellable")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                if !cancellable {
                    let task_id = self.task_value_id(task);
                    return RestResponse::json(
                        400,
                        tasks_route_registration::build_non_cancellable_task_error(&task_id),
                    );
                }
            }
            {
                let mut cancelled_task_ids = self
                    .cancelled_task_ids
                    .lock()
                    .expect("cancelled task ids lock poisoned");
                for task in &tasks {
                    cancelled_task_ids.insert(self.task_value_id(task));
                }
            }
            self.persist_shared_runtime_state_to_disk();
            let tasks = self.tasks_matching_parent_task_id(parent_task_id);
            return RestResponse::json(200, self.tasks_cancel_response_for_tasks(tasks));
        }
        let Some(task_id) = self.task_id_from_cancel_request(request) else {
            return RestResponse::json(
                200,
                serde_json::json!({
                    "nodes": {},
                    "task_failures": [],
                    "node_failures": []
                }),
            );
        };
        if let Some(task) = self.find_task(task_id) {
            let cancellable = task
                .get("cancellable")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if !cancellable {
                return RestResponse::json(
                    400,
                    tasks_route_registration::build_non_cancellable_task_error(task_id),
                );
            }
            self.cancelled_task_ids
                .lock()
                .expect("cancelled task ids lock poisoned")
                .insert(task_id.to_string());
            self.persist_shared_runtime_state_to_disk();
            let task = self.find_task(task_id).unwrap_or(task);
            let task_node_id = task.get("node").and_then(Value::as_str).unwrap_or_default();
            return RestResponse::json(
                200,
                tasks_route_registration::invoke_tasks_cancel_live_route(&serde_json::json!({
                    "node": self.task_node_metadata(task_node_id),
                    "task": task
                })),
            );
        }
        RestResponse::json(200, self.unknown_task_cancel_body(task_id))
    }

    fn handle_tasks_rethrottle_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = self.refuse_task_submission_if_unavailable() {
            return response;
        }
        let Some(task_id) = self.rethrottle_task_id_from_request(request) else {
            return RestResponse::not_found_for(request.method, &request.path);
        };
        let requested_rate = match self.requested_rethrottle_rate(request) {
            Ok(rate) => rate,
            Err(reason) => {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": reason
                        },
                        "status": 400
                    }),
                );
            }
        };
        if let Some(task) = self.find_task(task_id) {
            let cancelled = task
                .get("cancelled")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if cancelled || !self.task_is_active(task_id) {
                return RestResponse::json(
                    400,
                    tasks_route_registration::build_non_cancellable_task_error(task_id),
                );
            }
            if let Some(rate) = requested_rate {
                self.rethrottled_task_rates
                    .lock()
                    .expect("rethrottled task rates lock poisoned")
                    .insert(task_id.to_string(), rate);
                self.persist_shared_runtime_state_to_disk();
                if let Some(task) = self.find_task(task_id) {
                    return RestResponse::json(
                        200,
                        serde_json::json!({
                            "task": task
                        }),
                    );
                }
            }
            return RestResponse::json(
                200,
                serde_json::json!({
                    "task": task
                }),
            );
        }
        RestResponse::json(
            404,
            tasks_route_registration::build_unknown_task_error(task_id),
        )
    }

    fn handle_reindex_route(&self, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let Some(source_index) = body
            .get("source")
            .and_then(|source| source.get("index"))
            .and_then(Value::as_str)
        else {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "illegal_argument_exception",
                        "reason": "reindex source.index is required"
                    },
                    "status": 400
                }),
            );
        };
        let Some(dest_index) = body
            .get("dest")
            .and_then(|dest| dest.get("index"))
            .and_then(Value::as_str)
        else {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "illegal_argument_exception",
                        "reason": "reindex dest.index is required"
                    },
                    "status": 400
                }),
            );
        };
        let script = body.get("script");
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("require_alias"))
        {
            return response;
        }
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("wait_for_completion"))
        {
            return response;
        }
        let wait_for_completion = !request
            .query_params
            .get("wait_for_completion")
            .is_some_and(|value| value == "false");
        let requests_per_second = match Self::bulk_by_scroll_requests_per_second(request) {
            Ok(rate) => rate,
            Err(response) => return response,
        };
        if request
            .query_params
            .get("require_alias")
            .is_some_and(|value| query_param_is_true(Some(value)))
            && !self.target_is_alias(dest_index)
        {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "index_not_found_exception",
                        "reason": require_alias_not_alias_reason(dest_index)
                    },
                    "status": 404
                }),
            );
        }
        let dest_routing = body
            .get("dest")
            .and_then(|dest| dest.get("routing"))
            .and_then(Value::as_str);
        if dest_routing.is_some_and(|routing| {
            routing != "keep" && routing != "discard" && !routing.starts_with('=')
        }) {
            return action_request_validation_error(vec![
                "routing must be unset, [keep], [discard] or [=<some new value>]",
            ]);
        }
        if let Some(response) = self.refuse_task_submission_if_unavailable() {
            return response;
        }
        let _thread_pool = match self.enter_runtime_thread_pool("task_submission", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };

        let resolved_dest = match self.resolve_write_target(dest_index, true) {
            Ok(index) => index,
            Err(reason) => {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": reason
                        },
                        "status": 400
                    }),
                );
            }
        };

        let source_docs: Vec<(String, String, SharedStoredDocument)> = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned")
            .iter()
            .filter_map(|(key, doc)| {
                let mut parts = key.splitn(3, ':');
                let index = parts.next()?;
                let id = parts.next()?;
                let routing = parts.next().unwrap_or_default();
                if matches_index_selector(source_index, index) {
                    Some((id.to_string(), routing.to_string(), doc.clone()))
                } else {
                    None
                }
            })
            .collect();

        let total = source_docs.len() as u64;
        let mut created = 0_u64;
        let mut updated = 0_u64;
        {
            let mut docs = self
                .documents_state
                .lock()
                .expect("documents state lock poisoned");
            for (id, routing, doc) in source_docs {
                let resolved_routing = match dest_routing {
                    None | Some("keep") => routing,
                    Some("discard") => String::new(),
                    Some(forced) if forced.starts_with('=') => forced[1..].to_string(),
                    Some(_) => unreachable!("destination routing was validated above"),
                };
                let mut dest_doc = doc.as_ref().clone();
                if let Some(script) = script {
                    if let Err(response) =
                        apply_source_assignment_script(&mut dest_doc.source, script)
                    {
                        return response;
                    }
                }
                dest_doc.routing = if resolved_routing.is_empty() {
                    None
                } else {
                    Some(resolved_routing.clone())
                };
                let key = format!("{resolved_dest}:{id}:{resolved_routing}");
                if docs.insert(key, Arc::new(dest_doc)).is_some() {
                    updated += 1;
                } else {
                    created += 1;
                }
            }
        }
        self.persist_shared_runtime_state_to_disk();

        let response = serde_json::json!({
            "took": 1,
            "timed_out": false,
            "total": total,
            "updated": updated,
            "created": created,
            "deleted": 0,
            "batches": if total == 0 { 0 } else { 1 },
            "version_conflicts": 0,
            "noops": 0,
            "retries": {
                "bulk": 0,
                "search": 0
            },
            "throttled_millis": 0,
            "requests_per_second": requests_per_second,
            "throttled_until_millis": 0,
            "failures": []
        });
        if !wait_for_completion {
            let task = self.record_completed_bulk_by_scroll_task(
                "reindex from source",
                "reindex",
                "indices:data/write/reindex",
                &response,
            );
            self.persist_shared_runtime_state_to_disk();
            return RestResponse::json(200, serde_json::json!({ "task": task }));
        }
        RestResponse::json(200, response)
    }

    fn handle_delete_by_query_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("wait_for_completion"))
        {
            return response;
        }
        let wait_for_completion = !request
            .query_params
            .get("wait_for_completion")
            .is_some_and(|value| value == "false");
        let requests_per_second = match Self::bulk_by_scroll_requests_per_second(request) {
            Ok(rate) => rate,
            Err(response) => return response,
        };
        if let Some(response) = self.refuse_task_submission_if_unavailable() {
            return response;
        }
        let _thread_pool = match self.enter_runtime_thread_pool("task_submission", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let resolved_index = self.resolve_index_or_alias(index);
        let requested_routing_values = request
            .query_params
            .get("routing")
            .cloned()
            .or_else(|| self.resolve_alias_search_routing(index))
            .map(|routing| parse_routing_values(&routing))
            .filter(|routing| !routing.is_empty());
        let mut deleted = 0_u64;
        {
            let mut docs = self
                .documents_state
                .lock()
                .expect("documents state lock poisoned");
            let keys: Vec<String> = docs
                .iter()
                .filter_map(|(key, doc)| {
                    let mut parts = key.splitn(3, ':');
                    let doc_index = parts.next()?;
                    let doc_id = parts.next()?;
                    if doc_index != resolved_index {
                        return None;
                    }
                    if let Some(routings) = requested_routing_values.as_ref() {
                        if !document_matches_requested_routing_shards(
                            doc_index,
                            doc_id,
                            doc,
                            routings,
                            |index_name| self.index_primary_shard_count(index_name),
                        ) {
                            return None;
                        }
                    }
                    if matches_query_body(&doc.source, body.get("query")) {
                        Some(key.clone())
                    } else {
                        None
                    }
                })
                .collect();
            deleted = keys.len() as u64;
            for key in keys {
                docs.remove(&key);
            }
        }
        self.persist_shared_runtime_state_to_disk();
        let response = serde_json::json!({
            "took": 1,
            "timed_out": false,
            "total": deleted,
            "deleted": deleted,
            "batches": if deleted == 0 { 0 } else { 1 },
            "version_conflicts": 0,
            "noops": 0,
            "retries": {
                "bulk": 0,
                "search": 0
            },
            "throttled_millis": 0,
            "requests_per_second": requests_per_second,
            "throttled_until_millis": 0,
            "failures": []
        });
        if !wait_for_completion {
            let mut task_response = response.clone();
            task_response["created"] = serde_json::json!(0);
            task_response["updated"] = serde_json::json!(0);
            let task = self.record_completed_bulk_by_scroll_task(
                format!("delete by query [{index}]"),
                "delete_by_query",
                "indices:data/write/delete/byquery",
                &task_response,
            );
            self.persist_shared_runtime_state_to_disk();
            return RestResponse::json(200, serde_json::json!({ "task": task }));
        }
        RestResponse::json(200, response)
    }

    fn handle_update_by_query_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("wait_for_completion"))
        {
            return response;
        }
        let wait_for_completion = !request
            .query_params
            .get("wait_for_completion")
            .is_some_and(|value| value == "false");
        let requests_per_second = match Self::bulk_by_scroll_requests_per_second(request) {
            Ok(rate) => rate,
            Err(response) => return response,
        };
        if let Some(response) = self.refuse_task_submission_if_unavailable() {
            return response;
        }
        let _thread_pool = match self.enter_runtime_thread_pool("task_submission", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let resolved_index = self.resolve_index_or_alias(index);
        let requested_routing_values = request
            .query_params
            .get("routing")
            .cloned()
            .or_else(|| self.resolve_alias_search_routing(index))
            .map(|routing| parse_routing_values(&routing))
            .filter(|routing| !routing.is_empty());
        let mut total = 0_u64;
        let mut updated = 0_u64;
        let mut noops = 0_u64;
        {
            let mut docs = self
                .documents_state
                .lock()
                .expect("documents state lock poisoned");
            for (key, doc) in docs.iter_mut() {
                let mut parts = key.splitn(3, ':');
                let doc_index = parts.next().unwrap_or_default();
                let doc_id = parts.next().unwrap_or_default();
                if doc_index != resolved_index {
                    continue;
                }
                if let Some(routings) = requested_routing_values.as_ref() {
                    if !document_matches_requested_routing_shards(
                        doc_index,
                        doc_id,
                        doc,
                        routings,
                        |index_name| self.index_primary_shard_count(index_name),
                    ) {
                        continue;
                    }
                }
                if !matches_query_body(&doc.source, body.get("query")) {
                    continue;
                }
                total += 1;
                let original_source = doc.source.clone();
                if let Some(script) = body.get("script") {
                    let mut updated_doc = doc.as_ref().clone();
                    apply_update_by_query_script(&mut updated_doc.source, script);
                    if updated_doc.source == original_source {
                        noops += 1;
                    } else {
                        updated += 1;
                        *doc = Arc::new(updated_doc);
                    }
                } else if doc.source == original_source {
                    noops += 1;
                } else {
                    updated += 1;
                }
            }
        }
        self.persist_shared_runtime_state_to_disk();
        let response = serde_json::json!({
            "took": 1,
            "timed_out": false,
            "total": total,
            "updated": updated,
            "deleted": 0,
            "batches": if total == 0 { 0 } else { 1 },
            "version_conflicts": 0,
            "noops": noops,
            "retries": {
                "bulk": 0,
                "search": 0
            },
            "throttled_millis": 0,
            "requests_per_second": requests_per_second,
            "throttled_until_millis": 0,
            "failures": []
        });
        if !wait_for_completion {
            let mut task_response = response.clone();
            task_response["created"] = serde_json::json!(0);
            let task = self.record_completed_bulk_by_scroll_task(
                format!("update by query [{index}]"),
                "update_by_query",
                "indices:data/write/update/byquery",
                &task_response,
            );
            self.persist_shared_runtime_state_to_disk();
            return RestResponse::json(200, serde_json::json!({ "task": task }));
        }
        RestResponse::json(200, response)
    }

    fn cluster_health_body(&self, target: Option<&str>) -> Option<Value> {
        let node_count = self
            .cluster_view
            .as_ref()
            .map(|view| view.nodes.len())
            .unwrap_or_default() as u64;
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned");
        let selected_indices = match target {
            None => created_indices.iter().cloned().collect::<Vec<_>>(),
            Some(selector) => {
                let selected = created_indices
                    .iter()
                    .filter(|index| matches_index_selector(selector, index))
                    .cloned()
                    .collect::<Vec<_>>();
                if selected.is_empty() {
                    return None;
                }
                selected
            }
        };
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned")
            .clone();
        let (open_primary_shards, open_replica_shards, closed_count) = selected_indices
            .iter()
            .fold((0_u64, 0_u64, 0_u64), |acc, index| {
                let is_closed = manifest["indices"][index]["state"]
                    .as_str()
                    .is_some_and(|state| state == "close");
                if is_closed {
                    (acc.0, acc.1, acc.2 + 1)
                } else {
                    let primary_shards = self.index_primary_shard_count(index) as u64;
                    let replica_shards = primary_shards * self.index_replica_count(index) as u64;
                    (acc.0 + primary_shards, acc.1 + replica_shards, acc.2)
                }
            });
        let unassigned_shards = if open_primary_shards > 0 && node_count == 1 {
            open_replica_shards
        } else {
            0
        };
        let active_primary_shards = open_primary_shards;
        let active_shards = open_primary_shards;
        let status = if open_primary_shards == 0 && closed_count > 0 {
            "red"
        } else if unassigned_shards > 0 {
            "yellow"
        } else {
            "green"
        };
        let active_shards_percent = if open_primary_shards == 0 && closed_count > 0 {
            0.0
        } else if selected_indices.is_empty() {
            100.0
        } else {
            (active_shards as f64 / (active_shards + unassigned_shards) as f64) * 100.0
        };
        Some(serde_json::json!({
            "cluster_name": self
                .cluster_view
                .as_ref()
                .map(|view| view.cluster_name.clone())
                .unwrap_or_else(|| self.info.name.clone()),
            "status": status,
            "timed_out": false,
            "number_of_nodes": node_count,
            "number_of_data_nodes": node_count,
            "active_primary_shards": active_primary_shards,
            "active_shards": active_shards,
            "relocating_shards": 0,
            "initializing_shards": 0,
            "unassigned_shards": unassigned_shards,
            "delayed_unassigned_shards": 0,
            "number_of_pending_tasks": self.tasks_len(),
            "number_of_in_flight_fetch": 0,
            "task_max_waiting_in_queue_millis": 0,
            "active_shards_percent_as_number": active_shards_percent
        }))
    }

    fn cluster_state_body(&self) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let mut nodes = serde_json::Map::new();
        let master_node = view
            .nodes
            .first()
            .map(|node| node.node_id.clone())
            .unwrap_or_else(|| "node-a".to_string());
        for node in &view.nodes {
            nodes.insert(
                node.node_id.clone(),
                serde_json::json!({
                    "name": node.node_name,
                    "transport_address": node.transport_address,
                    "roles": node.roles,
                }),
            );
        }
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .clone();
        let metadata_manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned")
            .clone();
        let manifest_indices = metadata_manifest["indices"]
            .as_object()
            .cloned()
            .unwrap_or_default();
        let mut metadata_indices = serde_json::Map::new();
        let mut routing_indices = serde_json::Map::new();
        let mut routing_nodes = Vec::new();
        for index in created_indices {
            let index_metadata = manifest_indices
                .get(&index)
                .cloned()
                .unwrap_or_else(|| serde_json::json!({}));
            let aliases = index_metadata
                .get("aliases")
                .and_then(Value::as_object)
                .map(|aliases| {
                    Value::Array(
                        aliases
                            .keys()
                            .cloned()
                            .map(Value::String)
                            .collect::<Vec<_>>(),
                    )
                })
                .unwrap_or_else(|| Value::Array(Vec::new()));
            metadata_indices.insert(
                index.clone(),
                serde_json::json!({
                    "state": index_metadata
                        .get("state")
                        .and_then(Value::as_str)
                        .unwrap_or("open"),
                    "settings": index_metadata.get("settings").cloned().unwrap_or_else(|| serde_json::json!({})),
                    "mappings": index_metadata.get("mappings").cloned().unwrap_or_else(|| serde_json::json!({})),
                    "aliases": aliases,
                }),
            );
            routing_indices.insert(
                index.clone(),
                serde_json::json!({
                    "shards": {
                        "0": [
                            {
                                "state": "STARTED",
                                "primary": true,
                                "node": master_node,
                                "relocating_node": Value::Null,
                                "shard_routing_state": "STARTED",
                                "shard": 0,
                                "index": index,
                                "index_uuid": format!("{index}-uuid"),
                                "allocation_id": {
                                    "id": format!("{index}-p-0")
                                },
                                "expected_shard_size_in_bytes": 0
                            }
                        ]
                    }
                }),
            );
            routing_nodes.push(serde_json::json!({
                "index": index,
                "node": master_node.clone(),
                "primary": true,
                "state": "STARTED",
                "shard": 0,
                "allocation_id": format!("{index}-p-0")
            }));
        }
        let mut routing_node_map = serde_json::Map::new();
        routing_node_map.insert(master_node.clone(), Value::Array(routing_nodes));
        serde_json::json!({
            "cluster_name": view.cluster_name,
            "cluster_uuid": view.cluster_uuid,
            "version": 1,
            "state_uuid": "steelsearch-state-uuid",
            "master_node": master_node,
            "blocks": {},
            "metadata": {
                "cluster_uuid": view.cluster_uuid,
                "indices": metadata_indices
            },
            "nodes": nodes,
            "routing_nodes": {
                "unassigned": [],
                "nodes": routing_node_map
            },
            "routing_table": {
                "indices": routing_indices
            }
        })
    }

    fn cluster_settings_body(
        &self,
        flat_settings: bool,
        include_defaults: bool,
        settings_filter: Option<&String>,
    ) -> Value {
        let state = self
            .cluster_settings_state
            .lock()
            .expect("cluster settings state lock poisoned")
            .clone();
        let persistent = render_cluster_settings_section(
            &filter_cluster_settings_section(
                state
                    .get("persistent")
                    .unwrap_or(&Value::Object(serde_json::Map::new())),
                settings_filter,
            ),
            flat_settings,
        );
        let transient = render_cluster_settings_section(
            &filter_cluster_settings_section(
                state
                    .get("transient")
                    .unwrap_or(&Value::Object(serde_json::Map::new())),
                settings_filter,
            ),
            flat_settings,
        );
        if include_defaults {
            return cluster_settings_route_registration::build_cluster_settings_response_body_with_defaults(
                &persistent,
                &transient,
                &render_cluster_settings_section(
                    &filter_cluster_settings_section(
                        &default_cluster_settings_defaults(),
                        settings_filter,
                    ),
                    flat_settings,
                ),
            );
        }
        cluster_settings_route_registration::build_cluster_settings_response_body(
            &persistent,
            &transient,
        )
    }

    fn handle_cluster_allocation_explain_route(&self, request: &RestRequest) -> RestResponse {
        if request.body.is_empty() {
            let created_index = self
                .created_indices_state
                .lock()
                .expect("created indices state lock poisoned")
                .iter()
                .next()
                .cloned();
            if let Some(index) = created_index {
                let synthesized = RestRequest::new(request.method, request.path.as_str())
                    .with_json_body(serde_json::json!({
                        "index": index,
                        "shard": 0,
                        "primary": false
                    }));
                return RestResponse::json(200, self.cluster_allocation_explain_body(&synthesized));
            }
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "root_cause": [
                            {
                                "type": "illegal_argument_exception",
                                "reason": "unable to find any unassigned shards to explain [ClusterAllocationExplainRequest[useAnyUnassignedShard=true,includeYesDecisions?=false]"
                            }
                        ],
                        "type": "illegal_argument_exception",
                        "reason": "unable to find any unassigned shards to explain [ClusterAllocationExplainRequest[useAnyUnassignedShard=true,includeYesDecisions?=false]"
                    },
                    "status": 400
                }),
            );
        }
        RestResponse::json(200, self.cluster_allocation_explain_body(request))
    }

    fn cluster_allocation_explain_body(&self, request: &RestRequest) -> Value {
        let request_body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let index = request_body
            .get("index")
            .and_then(Value::as_str)
            .unwrap_or("logs-compat");
        let shard = request_body
            .get("shard")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let primary = request_body
            .get("primary")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let view = self.cluster_view.clone().unwrap_or_default();
        let local_node = view.nodes.first().cloned().unwrap_or_default();
        let node_attributes = serde_json::json!({
            "testattr": "test",
            "shard_indexing_pressure_enabled": "true"
        });
        let body = if primary {
            serde_json::json!({
                "index": index,
                "shard": shard,
                "primary": true,
                "current_state": "started",
                "can_remain_on_current_node": "yes",
                "can_rebalance_cluster": "no",
                "can_move_to_other_node": "no",
                "can_rebalance_to_other_node": "no",
                "move_explanation": "shard movement is not required in the bounded development allocation explain",
                "rebalance_explanation": "rebalancing is not allowed",
                "can_rebalance_cluster_decisions": [
                    {
                        "decider": "rebalance_only_when_active",
                        "decision": "NO",
                        "explanation": "rebalancing is not allowed until all replicas in the cluster are active"
                    },
                    {
                        "decider": "cluster_rebalance",
                        "decision": "NO",
                        "explanation": "the cluster has unassigned shards and cluster setting [cluster.routing.allocation.allow_rebalance] is set to [indices_all_active]"
                    }
                ],
                "current_node": {
                    "id": local_node.node_id,
                    "name": local_node.node_name,
                    "transport_address": local_node.transport_address,
                    "weight_ranking": 1,
                    "roles": local_node.roles,
                    "attributes": node_attributes.clone(),
                },
                "cluster_info": {
                    "shard_sizes": {
                        format!("[{index}][{shard}][p]"): 0
                    },
                    "reserved_sizes": [],
                    "nodes": {
                        local_node.node_id.clone(): {
                            "least_available": {
                                "path": "/tmp/steelsearch",
                                "total_in_bytes": 0,
                                "available_in_bytes": 0
                            }
                        }
                    }
                }
            })
        } else {
            serde_json::json!({
                "index": index,
                "shard": shard,
                "primary": false,
                "current_state": "unassigned",
                "can_allocate": "no",
                "allocate_explanation": "cannot allocate because allocation is not permitted to any of the nodes",
                "unassigned_info": {
                    "reason": "INDEX_CREATED",
                    "at": "2026-05-02T00:00:00.000Z",
                    "details": "bounded development allocation explain keeps the replica shard unassigned",
                    "last_allocation_status": "no_attempt",
                    "failed_allocation_attempts": 0
                },
                "node_allocation_decisions": [
                    {
                        "node_name": local_node.node_name,
                        "node_id": local_node.node_id,
                        "transport_address": local_node.transport_address,
                        "node_attributes": node_attributes,
                        "node_decision": "no",
                        "weight_ranking": 1,
                        "deciders": [
                            {
                                "decider": "same_shard",
                                "decision": "NO",
                                "explanation": "bounded development allocation explain keeps the replica shard unassigned"
                            }
                        ]
                    }
                ],
                "configured_delay": "0ms",
                "configured_delay_in_millis": 0,
                "remaining_delay": "0ms",
                "remaining_delay_in_millis": 0
            })
        };
        allocation_explain_route_registration::invoke_cluster_allocation_explain_live_route(&body)
    }

    fn pending_tasks_body(&self) -> Value {
        serde_json::json!({
            "tasks": self.active_task_records()
        })
    }

    fn tasks_body(&self) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let nodes = view
            .nodes
            .iter()
            .map(|node| (node.node_id.clone(), self.task_node_metadata(&node.node_id)))
            .collect::<serde_json::Map<_, _>>();
        let mut tasks = self.task_records();
        if tasks.is_empty() {
            tasks.push(self.synthetic_list_tasks_record(&view.local_node_id));
        }
        serde_json::json!({
            "node": self.task_node_metadata(&view.local_node_id),
            "nodes": nodes,
            "tasks": tasks
        })
    }

