    fn nodes_stats_body(&self) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let mut nodes = serde_json::Map::new();
        let local_search_open_contexts = self.search_open_context_count_for_stats();
        let local_pit_current_contexts = self
            .pit_open_context_counts_by_index()
            .values()
            .copied()
            .sum::<u64>();
        let local_pit_total_contexts = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned")
            .values()
            .copied()
            .sum::<u64>();
        let local_search_cache_telemetry = self
            .native_engine
            .search_cache_telemetry_snapshot()
            .ok()
            .and_then(|snapshot| serde_json::to_value(snapshot).ok())
            .unwrap_or_else(|| serde_json::json!({}));
        for node in &view.nodes {
            let search_cache_telemetry = if node.node_id == view.local_node_id {
                local_search_cache_telemetry.clone()
            } else {
                serde_json::json!({})
            };
            nodes.insert(
                node.node_id.clone(),
                serde_json::json!({
                    "timestamp": 1,
                    "name": node.node_name,
                    "host": "127.0.0.1",
                    "ip": node.transport_address,
                    "roles": node.roles,
                    "attributes": {
                        "testattr": "test",
                        "shard_indexing_pressure_enabled": "true"
                    },
                    "transport_address": node.transport_address,
                    "http": {
                        "current_open": 0,
                        "total_opened": 0,
                        "publish_address": node.http_address
                    },
                    "transport": {
                        "server_open": 1,
                        "rx_count": 0,
                        "tx_count": 0
                    },
                    "indices": {
                        "docs": {
                            "count": 0
                        },
                        "store": {
                            "size_in_bytes": 0
                        },
                        "search": if node.node_id == view.local_node_id {
                            search_stats_body(
                                local_search_open_contexts,
                                local_pit_current_contexts,
                                local_pit_total_contexts
                            )
                        } else {
                            search_stats_body(0, 0, 0)
                        }
                    },
                    "process": {
                        "open_file_descriptors": 0,
                        "cpu": {
                            "percent": 0
                        }
                    },
                    "os": {
                        "cpu": {
                            "percent": 0,
                            "load_average": {
                                "1m": 0.0
                            }
                        },
                        "mem": {
                            "total_in_bytes": 0,
                            "free_in_bytes": 0
                        }
                    },
                    "jvm": {
                        "threads": {
                            "count": 0,
                            "peak_count": 0
                        },
                        "mem": {
                            "heap_used_in_bytes": 0
                        }
                    },
                    "thread_pool": self.thread_pool_stats_body_for_node(
                        &node.node_id,
                        node.node_id == view.local_node_id,
                    ),
                    "fs": {
                        "total": {
                            "total_in_bytes": 0,
                            "available_in_bytes": 0
                        }
                    },
                    "breakers": {
                        "parent": {
                            "limit_size_in_bytes": 0,
                            "estimated_size_in_bytes": 0,
                            "tripped": 0
                        }
                    },
                    "steelsearch": {
                        "search_cache": search_cache_telemetry
                    }
                }),
            );
        }
        serde_json::json!({ "nodes": nodes })
    }

    fn search_open_context_count_for_stats(&self) -> u64 {
        let now_millis = current_epoch_millis();
        let pit_count = {
            let mut contexts = self
                .pit_contexts
                .lock()
                .expect("pit contexts lock poisoned");
            prune_expired_pit_contexts(&mut contexts, now_millis);
            contexts.len()
        };
        let scroll_count = self
            .scroll_contexts
            .lock()
            .expect("scroll contexts lock poisoned")
            .len();
        pit_count.saturating_add(scroll_count) as u64
    }

    fn handle_nodes_usage_route(&self, request: &RestRequest) -> RestResponse {
        let Some((node_selector, requested_metrics)) = parse_nodes_usage_path(&request.path) else {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!("no handler found for uri [{}]", request.path),
            );
        };
        if requested_metrics.contains("_all") && requested_metrics.len() > 1 {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "request [{}] contains _all and individual metrics [{}]",
                    request.path,
                    nodes_usage_raw_metric(&request.path).unwrap_or("_all")
                ),
            );
        }
        RestResponse::json(
            200,
            self.nodes_usage_body_for(&node_selector, &requested_metrics),
        )
    }

    fn nodes_usage_body_for(
        &self,
        node_selector: &str,
        requested_metrics: &BTreeSet<String>,
    ) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let mut nodes = serde_json::Map::new();
        for node in &view.nodes {
            if !node_matches_nodes_info_selector(&view, node, node_selector) {
                continue;
            }
            let include_all = requested_metrics.contains("_all");
            let mut node_body = serde_json::Map::new();
            node_body.insert("timestamp".to_string(), serde_json::json!(1));
            node_body.insert("since".to_string(), serde_json::json!(1));
            if include_all || requested_metrics.contains("rest_actions") {
                node_body.insert(
                    "rest_actions".to_string(),
                    serde_json::json!({
                        "nodes_usage": 1,
                        "cluster_stats": 1
                    }),
                );
            }
            if include_all || requested_metrics.contains("aggregations") {
                node_body.insert(
                    "aggregations".to_string(),
                    serde_json::json!({
                        "terms": 1
                    }),
                );
            }
            nodes.insert(node.node_id.clone(), Value::Object(node_body));
        }
        let total = nodes.len();
        serde_json::json!({
            "_nodes": {
                "total": total,
                "successful": total,
                "failed": 0
            },
            "cluster_name": view.cluster_name,
            "nodes": nodes
        })
    }

    fn handle_nodes_info_route(&self, request: &RestRequest) -> RestResponse {
        let Some((node_selector, requested_metrics)) = parse_nodes_info_path(&request.path) else {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!("no handler found for uri [{}]", request.path),
            );
        };
        RestResponse::json(
            200,
            self.nodes_info_body_for(&node_selector, &requested_metrics),
        )
    }

    fn nodes_info_body(&self) -> Value {
        let all_metrics = nodes_info_all_metrics()
            .iter()
            .map(|metric| (*metric).to_string())
            .collect::<BTreeSet<_>>();
        self.nodes_info_body_for("_all", &all_metrics)
    }

    fn nodes_info_body_for(
        &self,
        node_selector: &str,
        requested_metrics: &BTreeSet<String>,
    ) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let mut nodes = serde_json::Map::new();
        for node in &view.nodes {
            if !node_matches_nodes_info_selector(&view, node, node_selector) {
                continue;
            }
            let mut node_body = serde_json::Map::new();
            node_body.insert("name".to_string(), serde_json::json!(node.node_name));
            node_body.insert("host".to_string(), serde_json::json!("127.0.0.1"));
            node_body.insert("ip".to_string(), serde_json::json!(node.transport_address));
            node_body.insert("roles".to_string(), serde_json::json!(node.roles));
            node_body.insert(
                "attributes".to_string(),
                serde_json::json!({
                    "testattr": "test",
                    "shard_indexing_pressure_enabled": "true"
                }),
            );
            node_body.insert(
                "transport_address".to_string(),
                serde_json::json!(node.transport_address),
            );
            if requested_metrics.contains("http") {
                node_body.insert(
                    "http".to_string(),
                    serde_json::json!({
                        "publish_address": node.http_address,
                        "bound_address": [node.http_address]
                    }),
                );
            }
            if requested_metrics.contains("settings") {
                node_body.insert(
                    "settings".to_string(),
                    serde_json::json!({
                        "cluster": {
                            "name": view.cluster_name
                        }
                    }),
                );
            }
            for metric in requested_metrics {
                if matches!(metric.as_str(), "http" | "settings") {
                    continue;
                }
                node_body
                    .entry(metric.clone())
                    .or_insert_with(|| serde_json::json!({}));
            }
            nodes.insert(node.node_id.clone(), Value::Object(node_body));
        }
        serde_json::json!({ "nodes": nodes })
    }

    fn dangling_indices_body(&self) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let dangling_indices = manifest["cluster_admin_state"]["dangling_indices"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        serde_json::json!({
            "_nodes": {
                "total": view.nodes.len(),
                "successful": view.nodes.len(),
                "failed": 0,
            },
            "cluster_name": view.cluster_name,
            "dangling_indices": dangling_indices
        })
    }

