    fn apply_search_pipeline_rerank(
        &self,
        hits: &mut [Value],
        rerank: &SearchPipelineRerankConfig,
    ) -> Result<(), RestResponse> {
        let models = self
            .ml_models_state
            .lock()
            .expect("ml models state lock poisoned");
        let Some(model) = models.get(&rerank.model_id) else {
            return Err(RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "resource_not_found_exception",
                        "reason": format!("ML model [{}] missing", rerank.model_id)
                    },
                    "status": 404
                }),
            ));
        };
        if !model.deployed {
            return Err(RestResponse::json(
                409,
                serde_json::json!({
                    "error": {
                        "type": "conflict_exception",
                        "reason": format!("ML model [{}] is not deployed", rerank.model_id)
                    },
                    "status": 409
                }),
            ));
        }
        drop(models);

        let query_terms = rerank
            .query_text
            .split_whitespace()
            .map(|term| term.to_ascii_lowercase())
            .collect::<Vec<_>>();
        hits.sort_by(|left, right| {
            let left_text = left["_source"][&rerank.field]
                .as_str()
                .unwrap_or_default()
                .to_ascii_lowercase();
            let right_text = right["_source"][&rerank.field]
                .as_str()
                .unwrap_or_default()
                .to_ascii_lowercase();
            let left_matches = query_terms
                .iter()
                .filter(|term| left_text.contains(term.as_str()))
                .count();
            let right_matches = query_terms
                .iter()
                .filter(|term| right_text.contains(term.as_str()))
                .count();
            right_matches.cmp(&left_matches).then_with(|| {
                let left_score = left["_score"].as_f64().unwrap_or(0.0);
                let right_score = right["_score"].as_f64().unwrap_or(0.0);
                right_score
                    .partial_cmp(&left_score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        Ok(())
    }

    fn handle_cat_indices_route(
        &self,
        request: &RestRequest,
        target: Option<&str>,
    ) -> RestResponse {
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .clone();
        let hidden_indices = {
            let manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            manifest["indices"]
                .as_object()
                .map(|indices| {
                    indices
                        .iter()
                        .filter_map(|(index, body)| {
                            index_metadata_is_hidden(body).then(|| index.clone())
                        })
                        .collect::<BTreeSet<_>>()
                })
                .unwrap_or_default()
        };
        let include_hidden = request
            .query_params
            .get("expand_wildcards")
            .map(|value| {
                value
                    .split(',')
                    .map(str::trim)
                    .any(|token| token == "hidden" || token == "all")
            })
            .unwrap_or(false)
            || target
                .is_some_and(|target| !target.contains('*') && hidden_indices.contains(target));
        let pit_open_contexts_by_index = self.pit_open_context_counts_by_index();
        let pit_total_contexts_by_index = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned")
            .clone();
        let mut rows = Vec::new();
        for index in created_indices {
            if target.is_some_and(|pattern| !wildcard_match(pattern, &index)) {
                continue;
            }
            if !include_hidden && hidden_indices.contains(&index) {
                continue;
            }
            let doc_count = self.index_lucene_document_count(&index);
            let store_size = self.index_store_size_bytes(&index, doc_count);
            let completion_size = self.index_completion_size_bytes(&index, doc_count);
            let segment_count = if doc_count > 0 { 1 } else { 0 };
            let pit_current = pit_open_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            let pit_total = pit_total_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            rows.push(serde_json::json!({
                "health": "yellow",
                "status": "open",
                "index": index,
                "uuid": "_na_",
                "pri": "1",
                "rep": "0",
                "docs.count": doc_count.to_string(),
                "docs.deleted": "0",
                "store.size": format!("{store_size}b"),
                "pri.store.size": format!("{store_size}b"),
                "completion.size": format!("{completion_size}b"),
                "pri.completion.size": format!("{completion_size}b"),
                "flush.total": "0",
                "pri.flush.total": "0",
                "flush.total_time": "0s",
                "pri.flush.total_time": "0s",
                "segments.count": segment_count.to_string(),
                "pri.segments.count": segment_count.to_string(),
                "segments.memory": "0b",
                "pri.segments.memory": "0b",
                "search.open_contexts": pit_current.to_string(),
                "pri.search.open_contexts": pit_current.to_string(),
                "search.point_in_time_current": pit_current.to_string(),
                "pri.search.point_in_time_current": pit_current.to_string(),
                "search.point_in_time_time": "0s",
                "pri.search.point_in_time_time": "0s",
                "search.point_in_time_total": pit_total.to_string(),
                "pri.search.point_in_time_total": pit_total.to_string()
            }));
        }
        if let Err(response) = sort_cat_indices_rows(&mut rows, request.query_params.get("s")) {
            return response;
        }
        let display_columns = cat_indices_display_columns(&request.query_params);
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (name, display) in &display_columns {
                        if row.get(*name).is_some() {
                            object.insert(
                                display.clone(),
                                Value::String(cat_indices_cell_text(row, name, request)),
                            );
                        }
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let widths = cat_indices_text_widths(&display_columns, &rows, request, verbose);
        let mut lines = Vec::new();
        if verbose {
            lines.push(cat_indices_format_text_cells(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str().to_string())
                    .collect(),
                &display_columns,
                &widths,
            ));
        }
        for row in &rows {
            lines.push(cat_indices_format_text_cells(
                display_columns
                    .iter()
                    .map(|(name, _)| cat_indices_cell_text(row, name, request))
                    .collect(),
                &display_columns,
                &widths,
            ));
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

