    fn handle_cat_aliases_route(
        &self,
        request: &RestRequest,
        alias_target: Option<&str>,
    ) -> RestResponse {
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let mut rows = Vec::new();
        if let Some(indices) = manifest["indices"].as_object() {
            for (index_name, body) in indices {
                let Some(aliases) = body.get("aliases").and_then(Value::as_object) else {
                    continue;
                };
                for (alias_name, alias_state) in aliases {
                    if alias_target.is_some_and(|target| !wildcard_match(target, alias_name)) {
                        continue;
                    }
                    rows.push(serde_json::json!({
                        "alias": alias_name,
                        "index": index_name,
                        "filter": alias_state
                            .get("filter")
                            .map_or("-".to_string(), |_| "*".to_string()),
                        "routing.index": alias_state
                            .get("index_routing")
                            .or_else(|| alias_state.get("routing"))
                            .and_then(Value::as_str)
                            .unwrap_or("-"),
                        "routing.search": alias_state
                            .get("search_routing")
                            .or_else(|| alias_state.get("routing"))
                            .and_then(Value::as_str)
                            .unwrap_or("-"),
                        "is_write_index": alias_state
                            .get("is_write_index")
                            .map(|value| if value == &Value::Bool(true) { "true" } else { "false" })
                            .unwrap_or("-"),
                    }));
                }
            }
        }
        rows.sort_by(|left, right| {
            right["index"]
                .as_str()
                .unwrap_or_default()
                .cmp(left["index"].as_str().unwrap_or_default())
                .then_with(|| {
                    left["alias"]
                        .as_str()
                        .unwrap_or_default()
                        .cmp(right["alias"].as_str().unwrap_or_default())
                })
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_aliases_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_aliases_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

    fn handle_cat_count_route(&self, request: &RestRequest, target: Option<&str>) -> RestResponse {
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let docs = self
            .documents_state
            .lock()
            .expect("documents state lock poisoned");
        let count = docs
            .keys()
            .filter(|key| {
                let Some((index, _)) = key.split_once(':') else {
                    return false;
                };
                if index_metadata_is_hidden(&manifest["indices"][index]) {
                    return false;
                }
                target
                    .map(|pattern| wildcard_match(pattern, index))
                    .unwrap_or(true)
            })
            .count()
            .to_string();
        let row = serde_json::json!({
            "epoch": "0",
            "timestamp": "00:00:00",
            "count": count
        });
        if let Err(response) = validate_cat_count_sort(request.query_params.get("s")) {
            return response;
        }
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let selected_row = cat_count_selected_row(&row, request.query_params.get("h"));
            return RestResponse::json(200, Value::Array(vec![selected_row]));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_count_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        lines.push(
            display_columns
                .iter()
                .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                .collect::<Vec<_>>()
                .join(" "),
        );
        RestResponse::text(200, lines.join("\n") + "\n")
    }

    fn handle_cat_allocation_route(
        &self,
        request: &RestRequest,
        target: Option<&str>,
    ) -> RestResponse {
        let nodes = self
            .cluster_view
            .as_ref()
            .map(|view| view.nodes.clone())
            .unwrap_or_else(|| {
                vec![DevelopmentClusterNode {
                    node_id: self.info.name.clone(),
                    node_name: self.info.name.clone(),
                    http_address: Some("127.0.0.1:9200".to_string()),
                    transport_address: "127.0.0.1:9300".to_string(),
                    roles: vec!["cluster_manager".to_string(), "data".to_string()],
                    local: true,
                }]
            });
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        let assigned_primary_shards = created_indices
            .iter()
            .filter(|index| !self.index_is_closed(index))
            .map(|index| self.index_primary_shard_count(index))
            .sum::<usize>();
        let unassigned_replica_shards = if nodes.len() == 1 {
            created_indices
                .iter()
                .filter(|index| !self.index_is_closed(index))
                .map(|index| {
                    self.index_primary_shard_count(index) * self.index_replica_count(index)
                })
                .sum::<usize>()
        } else {
            0
        };
        let shards = assigned_primary_shards.to_string();
        let mut rows = nodes
            .into_iter()
            .filter(|node| {
                target
                    .map(|pattern| {
                        pattern == "_local"
                            || wildcard_match(pattern, &node.node_name)
                            || wildcard_match(pattern, &node.transport_address)
                    })
                    .unwrap_or(true)
            })
            .map(|node| {
                let ip = node
                    .transport_address
                    .rsplit_once(':')
                    .map(|(host, _)| host.to_string())
                    .unwrap_or_else(|| "127.0.0.1".to_string());
                serde_json::json!({
                    "shards": shards,
                    "disk.indices": "0b",
                    "disk.used": "0b",
                    "disk.avail": "0b",
                    "disk.total": "0b",
                    "disk.percent": "0",
                    "host": ip,
                    "ip": ip,
                    "node": node.node_name,
                })
            })
            .collect::<Vec<_>>();
        if unassigned_replica_shards > 0
            && target
                .map(|pattern| wildcard_match(pattern, "UNASSIGNED"))
                .unwrap_or(true)
        {
            rows.push(serde_json::json!({
                "shards": unassigned_replica_shards.to_string(),
                "disk.indices": null,
                "disk.used": null,
                "disk.avail": null,
                "disk.total": null,
                "disk.percent": null,
                "host": null,
                "ip": null,
                "node": "UNASSIGNED",
            }));
        }
        rows.sort_by(|left, right| {
            let left_node = left["node"].as_str().unwrap_or_default();
            let right_node = right["node"].as_str().unwrap_or_default();
            (left_node == "UNASSIGNED")
                .cmp(&(right_node == "UNASSIGNED"))
                .then_with(|| left_node.cmp(right_node))
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_allocation_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_allocation_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

