fn standalone_search_body_allows_native_engine(body: &Value) -> bool {
    let aggregations = body
        .get("aggs")
        .or_else(|| body.get("aggregations"))
        .unwrap_or(&Value::Null);
    !query_contains_nested_knn(body.get("query").unwrap_or(&Value::Null))
        && !value_contains_any_key(
            aggregations,
            &["scripted_metric", "significant_terms", "top_hits"],
        )
        && ![
            "collapse",
            "derived",
            "docvalue_fields",
            "explain",
            "fields",
            "indices_boost",
            "min_score",
            "post_filter",
            "profile",
            "rescore",
            "runtime_mappings",
            "search_after",
            "seq_no_primary_term",
            "script_fields",
            "slice",
            "sort",
            "stored_fields",
            "suggest",
            "terminate_after",
            "track_total_hits",
            "track_scores",
            "version",
            "_source",
            "_source_excludes",
            "_source_includes",
        ]
        .iter()
        .any(|key| body.get(*key).is_some())
}

fn query_contains_nested_knn(query: &Value) -> bool {
    if query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
        .is_some_and(value_contains_knn_query)
    {
        return true;
    }
    query.as_object().is_some_and(|object| {
        object.values().any(|value| match value {
            Value::Array(values) => values.iter().any(query_contains_nested_knn),
            Value::Object(_) => query_contains_nested_knn(value),
            _ => false,
        })
    })
}

fn value_contains_knn_query(value: &Value) -> bool {
    if value.get("knn").is_some() {
        return true;
    }
    value.as_object().is_some_and(|object| {
        object.values().any(|child| match child {
            Value::Array(values) => values.iter().any(value_contains_knn_query),
            Value::Object(_) => value_contains_knn_query(child),
            _ => false,
        })
    })
}

fn standalone_native_search_request(
    resolved_indices: &[String],
    body: &Value,
) -> Result<SearchRequest, String> {
    Ok(SearchRequest {
        indices: resolved_indices.to_vec(),
        query: body
            .get("query")
            .cloned()
            .unwrap_or_else(|| serde_json::json!({ "match_all": {} })),
        stored_fields: body.get("stored_fields").cloned(),
        source_fields: body.get("fields").cloned(),
        source_filter: body.get("_source").cloned(),
        source_includes: body.get("_source_includes").cloned(),
        source_include: body.get("_source_include").cloned(),
        source_excludes: body.get("_source_excludes").cloned(),
        source_exclude: body.get("_source_exclude").cloned(),
        aggregations: body
            .get("aggs")
            .or_else(|| body.get("aggregations"))
            .cloned()
            .unwrap_or_else(|| serde_json::json!({})),
        highlight: body.get("highlight").cloned(),
        sort: parse_native_sort_specs(body.get("sort"))?,
        from: body.get("from").and_then(Value::as_u64).unwrap_or(0) as usize,
        size: body.get("size").and_then(Value::as_u64).unwrap_or(10) as usize,
        explain: body.get("explain") == Some(&Value::Bool(true)),
    })
}

fn parse_native_sort_specs(sort: Option<&Value>) -> Result<Vec<SortSpec>, String> {
    let Some(sort) = sort else {
        return Ok(Vec::new());
    };
    let Some(items) = sort.as_array() else {
        return Err("native sort expects an array".to_string());
    };
    let mut specs = Vec::new();
    for item in items {
        if let Some(field) = item.as_str() {
            specs.push(SortSpec {
                field: field.to_string(),
                order: if field == "_score" {
                    SortOrder::Desc
                } else {
                    SortOrder::Asc
                },
                unmapped_type: None,
                mode: None,
                geo_origin: None,
                script: None,
            });
            continue;
        }
        let Some(object) = item.as_object() else {
            return Err("native sort item expects a field object".to_string());
        };
        for (field, options) in object {
            let order = match options {
                Value::String(value) if value == "desc" => SortOrder::Desc,
                Value::String(_) => SortOrder::Asc,
                Value::Object(options) => {
                    if options
                        .get("order")
                        .and_then(Value::as_str)
                        .is_some_and(|order| order == "desc")
                    {
                        SortOrder::Desc
                    } else {
                        SortOrder::Asc
                    }
                }
                _ => SortOrder::Asc,
            };
            specs.push(SortSpec {
                field: field.to_string(),
                order,
                unmapped_type: None,
                mode: None,
                geo_origin: None,
                script: None,
            });
        }
    }
    Ok(specs)
}

fn msearch_response_with_status(response: RestResponse) -> Value {
    let mut body = response.body;
    if let Some(object) = body.as_object_mut() {
        object.insert("status".to_string(), Value::from(response.status));
    }
    body
}

fn is_msearch_pit_request_validation_response(response: &RestResponse) -> bool {
    if response.status != 400 {
        return false;
    }
    let error_type = response
        .body
        .get("error")
        .and_then(|error| error.get("type"))
        .and_then(Value::as_str);
    matches!(
        error_type,
        Some("action_request_validation_exception" | "illegal_argument_exception")
    )
}

fn native_search_response_to_rest_response(
    mut response: SearchResponse,
    body: &Value,
    total_shards: usize,
    rest_total_hits_as_int: bool,
) -> RestResponse {
    response.shards = SearchShardStats {
        total: total_shards as u64,
        successful: total_shards as u64,
        skipped: response.shards.skipped,
        failed: 0,
        failures: Vec::new(),
    };
    let mut response_body = response.to_opensearch_body(1);
    if let Some(highlight) = body.get("highlight") {
        if let Some(hits) = response_body
            .get_mut("hits")
            .and_then(Value::as_object_mut)
            .and_then(|hits| hits.get_mut("hits"))
            .and_then(Value::as_array_mut)
        {
            for hit in hits {
                let Some(hit_object) = hit.as_object_mut() else {
                    continue;
                };
                let Some(source) = hit_object.get("_source") else {
                    continue;
                };
                if let Some(highlight_body) =
                    build_highlight_response_body(source, &body["query"], highlight)
                {
                    hit_object.insert("highlight".to_string(), highlight_body);
                }
            }
        }
    }
    let track_total_hits_disabled = search_track_total_hits_disabled(body);
    if let Some(threshold) = search_track_total_hits_threshold(body) {
        if response.total_hits > threshold {
            response_body["hits"]["total"] =
                serde_json::json!({ "value": threshold, "relation": "gte" });
        }
    }
    if track_total_hits_disabled {
        if rest_total_hits_as_int {
            response_body["hits"]["total"] = Value::from(-1);
        } else if let Some(hits) = response_body.get_mut("hits").and_then(Value::as_object_mut) {
            hits.remove("total");
        }
    } else if rest_total_hits_as_int {
        response_body["hits"]["total"] = serde_json::json!(response.total_hits);
    }
    RestResponse::json(200, response_body)
}

