fn stored_fields_fetch_disabled(stored_fields: Option<&Value>) -> bool {
    matches!(stored_fields, Some(Value::String(field)) if field == "_none_")
        || matches!(
            stored_fields,
            Some(Value::Array(fields))
                if fields.len() == 1 && fields.first().and_then(Value::as_str) == Some("_none_")
        )
}

fn stored_fields_empty_selection(stored_fields: Option<&Value>) -> bool {
    matches!(stored_fields, Some(Value::Array(fields)) if fields.is_empty())
}

fn stored_fields_should_suppress_default_source(body: &Value) -> bool {
    body.get("_source").is_none()
        && (stored_fields_fetch_disabled(body.get("stored_fields"))
            || (stored_fields_empty_selection(body.get("stored_fields"))
                && !source_fetch_explicitly_requested(body)))
}

fn source_fetch_explicitly_requested(body: &Value) -> bool {
    if matches!(body.get("_source"), Some(Value::Bool(false))) {
        return false;
    }
    body.get("_source").is_some()
        || body.get("_source_includes").is_some()
        || body.get("_source_include").is_some()
        || body.get("_source_excludes").is_some()
        || body.get("_source_exclude").is_some()
}

fn validate_fetch_source_query_filter_overlap(request: &RestRequest) -> Option<RestResponse> {
    let includes = request
        .query_params
        .get("_source_includes")
        .or_else(|| request.query_params.get("_source_include"))
        .map(|value| split_rest_csv_values(value))
        .or_else(|| {
            request.query_params.get("_source").and_then(|value| {
                if value == "true" || value == "false" {
                    None
                } else {
                    Some(split_rest_csv_values(value))
                }
            })
        })
        .unwrap_or_default();
    if includes.is_empty() {
        return None;
    }
    let excludes = request
        .query_params
        .get("_source_excludes")
        .or_else(|| request.query_params.get("_source_exclude"))
        .map(|value| split_rest_csv_values(value))
        .unwrap_or_default();
    for exclude in excludes {
        if includes.iter().any(|include| include == &exclude) {
            return Some(delete_pit_illegal_argument(format!(
                "The same entry [{exclude}] cannot be both included and excluded in _source."
            )));
        }
    }
    None
}

fn stored_field_names(stored_fields: &Value) -> Vec<&str> {
    match stored_fields {
        Value::String(field) if field != "_none_" => vec![field.as_str()],
        Value::Array(fields) => fields
            .iter()
            .filter_map(Value::as_str)
            .filter(|field| *field != "_none_")
            .collect(),
        _ => Vec::new(),
    }
}

fn stored_field_names_owned(stored_fields: &Value) -> Vec<String> {
    stored_field_names(stored_fields)
        .into_iter()
        .map(ToOwned::to_owned)
        .collect()
}

fn validate_docvalue_fields_request_body(docvalue_fields: &Value) -> Option<RestResponse> {
    let Some(fields) = docvalue_fields.as_array() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [docvalue_fields]",
        ));
    };
    for field in fields {
        if let Some(name) = field.as_str() {
            if name.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported search option [docvalue_fields]",
                ));
            }
            continue;
        }
        let Some(spec) = field.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported search option [docvalue_fields]",
            ));
        };
        if spec.keys().any(|key| key != "field" && key != "format") {
            return Some(build_unsupported_search_response(
                "unsupported search option [docvalue_fields]",
            ));
        }
        if spec.get("field").and_then(Value::as_str).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported search option [docvalue_fields]",
            ));
        }
    }
    None
}

fn validate_fetch_fields_request_body(fetch_fields: &Value) -> Option<RestResponse> {
    let Some(fields) = fetch_fields.as_array() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [fields]",
        ));
    };
    if fields.is_empty() {
        return Some(build_unsupported_search_response(
            "unsupported search option [fields]",
        ));
    }
    for field in fields {
        if let Some(name) = field.as_str() {
            if name.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported search option [fields]",
                ));
            }
            continue;
        }
        let Some(spec) = field.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported search option [fields]",
            ));
        };
        if spec.keys().any(|key| key != "field" && key != "format") {
            return Some(build_unsupported_search_response(
                "unsupported search option [fields]",
            ));
        }
        if spec.get("field").and_then(Value::as_str).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported search option [fields]",
            ));
        }
    }
    None
}

fn validate_script_fields_request_body(script_fields: &Value) -> Option<RestResponse> {
    let Some(fields) = script_fields.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [script_fields]",
        ));
    };
    for definition in fields.values() {
        let Some(definition_object) = definition.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported search option [script_fields]",
            ));
        };
        if definition_object
            .keys()
            .any(|key| key != "script" && key != "ignore_failure")
        {
            return Some(build_unsupported_search_response(
                "unsupported search option [script_fields]",
            ));
        }
        if definition_object
            .get("ignore_failure")
            .is_some_and(|value| !value.is_boolean())
        {
            return Some(build_unsupported_search_response(
                "unsupported search option [script_fields]",
            ));
        }
        let Some(script_source) = script_field_script_source(definition_object) else {
            return Some(build_unsupported_search_response(
                "unsupported search option [script_fields]",
            ));
        };
        if parse_script_field_source(script_source).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported search option [script_fields]",
            ));
        }
    }
    None
}

fn validate_source_filter_request_body(source_filter: &Value) -> Option<RestResponse> {
    match source_filter {
        Value::Bool(_) => None,
        Value::String(value) if !value.trim().is_empty() => None,
        Value::Array(values)
            if !values.is_empty()
                && values
                    .iter()
                    .all(|value| value.as_str().is_some_and(|field| !field.trim().is_empty())) =>
        {
            None
        }
        Value::Object(object) => {
            if object.is_empty()
                || object.keys().any(|key| {
                    !matches!(
                        key.as_str(),
                        "includes" | "include" | "excludes" | "exclude" | "fetch"
                    )
                })
            {
                return Some(build_unsupported_search_response(
                    "unsupported search option [_source]",
                ));
            }
            if object.get("fetch").is_some_and(|value| !value.is_boolean()) {
                return Some(build_unsupported_search_response(
                    "unsupported search option [_source]",
                ));
            }
            for key in ["includes", "include", "excludes", "exclude"] {
                let Some(value) = object.get(key) else {
                    continue;
                };
                if source_filter_selector_csv(value).is_none() {
                    return Some(build_unsupported_search_response(
                        "unsupported search option [_source]",
                    ));
                }
            }
            None
        }
        _ => Some(build_unsupported_search_response(
            "unsupported search option [_source]",
        )),
    }
}

fn validate_search_after_request_body(
    sort: Option<&Value>,
    search_after: &Value,
    from: u64,
    scroll: bool,
) -> Option<RestResponse> {
    if scroll {
        return Some(search_after_phase_execution_error(
            "`search_after` cannot be used in a scroll context.",
        ));
    }
    if from != 0 {
        return Some(search_after_phase_execution_error(
            "`from` parameter must be set to 0 when `search_after` is used.",
        ));
    }
    let Some(sort_fields) = sort.and_then(search_sort_fields) else {
        return Some(search_after_validation_error(
            "Sort must contain at least one field.",
        ));
    };
    let Some(after_values) = search_after.as_array() else {
        return Some(build_parsing_search_response_with_root_cause(&format!(
            "Unknown key for a {} in [search_after].",
            opensearch_xcontent_token_name(search_after)
        )));
    };
    if after_values.is_empty() {
        return Some(build_illegal_argument_search_response_with_root_cause(
            "Values must contains at least one value.",
        ));
    }
    if sort_fields.len() != after_values.len() {
        return Some(search_after_validation_error(format!(
            "search_after has {} value(s) but sort has {}.",
            after_values.len(),
            sort_fields.len()
        )));
    }
    None
}

fn validate_search_sort_request_body(sort: &Value) -> Option<RestResponse> {
    match sort {
        Value::String(field) => {
            if field.is_empty() {
                return Some(malformed_sort_response(
                    "malformed sort format, empty sort field is not allowed",
                ));
            }
            None
        }
        Value::Object(object) => validate_search_sort_object(object),
        Value::Array(sort_fields) => {
            for sort_field in sort_fields {
                match sort_field {
                    Value::String(field) => {
                        if field.is_empty() {
                            return Some(malformed_sort_response(
                                "malformed sort format, empty sort field is not allowed",
                            ));
                        }
                    }
                    Value::Object(object) => {
                        if let Some(response) = validate_search_sort_object(object) {
                            return Some(response);
                        }
                    }
                    _ => {
                        return Some(malformed_sort_response(
                            "malformed sort format, within the sort array, an object, or an actual string are allowed",
                        ));
                    }
                }
            }
            None
        }
        _ => Some(malformed_sort_response(
            "malformed sort format, either start with array, object, or an actual string",
        )),
    }
}

fn validate_search_sort_object(object: &serde_json::Map<String, Value>) -> Option<RestResponse> {
    if object.is_empty() {
        return Some(malformed_sort_response(
            "malformed sort format, empty sort object is not allowed",
        ));
    }
    for (field, options) in object {
        if field.is_empty() {
            return Some(malformed_sort_response(
                "malformed sort format, empty sort field is not allowed",
            ));
        }
        match options {
            Value::String(order) if matches!(order.as_str(), "asc" | "desc") => {}
            Value::String(_) => {
                return Some(malformed_sort_response("No enum constant SortOrder"));
            }
            Value::Object(options) => {
                if let Some(order) = options.get("order").and_then(Value::as_str) {
                    if !matches!(order, "asc" | "desc") {
                        return Some(malformed_sort_response("No enum constant SortOrder"));
                    }
                } else if options.get("order").is_some() {
                    return Some(malformed_sort_response("No enum constant SortOrder"));
                }
                if options
                    .get("missing")
                    .is_some_and(|missing| missing.is_array() || missing.is_object())
                {
                    return Some(malformed_sort_response(
                        "malformed sort format, missing value must be a scalar",
                    ));
                }
                if let Some(mode) = options.get("mode").and_then(Value::as_str) {
                    if !sort_mode_is_supported(mode) {
                        return Some(malformed_sort_response(&format!(
                            "Unknown SortMode [{mode}]"
                        )));
                    }
                } else if options.get("mode").is_some() {
                    return Some(malformed_sort_response(
                        "malformed sort format, sort mode must be a string",
                    ));
                }
                if let Some(unmapped_type) = options.get("unmapped_type") {
                    if !unmapped_type
                        .as_str()
                        .is_some_and(|value| !value.is_empty())
                    {
                        return Some(malformed_sort_response(
                            "malformed sort format, unmapped_type must be a non-empty string",
                        ));
                    }
                }
            }
            _ => {
                return Some(malformed_sort_response(
                    "malformed sort format, sort field options must be an object or order string",
                ));
            }
        }
    }
    None
}

fn malformed_sort_response(reason: &str) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason
            },
            "status": 400
        }),
    )
}

fn validate_slice_request_body(
    slice: &Value,
    scroll: bool,
    point_in_time: bool,
) -> Option<RestResponse> {
    const DEFAULT_MAX_SLICES_PER_SCROLL_OR_PIT: i64 = 1024;
    let Some(object) = slice.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [slice]",
        ));
    };
    if object
        .keys()
        .any(|key| !matches!(key.as_str(), "field" | "id" | "max"))
    {
        return Some(build_unsupported_search_response(
            "unsupported search option [slice]",
        ));
    }
    if object
        .get("field")
        .is_some_and(|field| !field.as_str().is_some_and(|value| !value.is_empty()))
    {
        return Some(slice_x_content_parse_error_with_cause(
            "field",
            "field name is null or empty",
        ));
    }
    let Some(id) = object.get("id").and_then(parse_opensearch_int_value) else {
        return Some(build_unsupported_search_response(
            "unsupported search option [slice]",
        ));
    };
    if id < 0 {
        return Some(slice_x_content_parse_error_with_cause(
            "id",
            "id must be greater than or equal to 0",
        ));
    }
    let Some(max) = object.get("max").and_then(parse_opensearch_int_value) else {
        return Some(build_unsupported_search_response(
            "unsupported search option [slice]",
        ));
    };
    if max <= 1 {
        return Some(slice_x_content_parse_error_with_cause(
            "max",
            "max must be greater than 1",
        ));
    }
    if id >= max {
        return Some(slice_x_content_parse_error_with_cause(
            "max",
            "max must be greater than id",
        ));
    }
    if !scroll && !point_in_time {
        return Some(search_after_phase_execution_error(
            "`slice` cannot be used outside of a scroll context or PIT context",
        ));
    }
    if max > DEFAULT_MAX_SLICES_PER_SCROLL_OR_PIT {
        let setting = if point_in_time {
            "index.max_slices_per_pit"
        } else {
            "index.max_slices_per_scroll"
        };
        let reason = format!(
            "The number of slices [{max}] is too large. It must be less than [{DEFAULT_MAX_SLICES_PER_SCROLL_OR_PIT}]. This limit can be set by changing the [{setting}] index level setting."
        );
        return if point_in_time {
            Some(search_phase_rejected_execution_error(reason))
        } else {
            Some(search_after_validation_error(reason))
        };
    }
    None
}

fn slice_x_content_parse_error_with_cause(field: &str, cause: &str) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "x_content_parse_exception",
                "reason": format!("[1:56] [slice] failed to parse field [{field}]"),
                "caused_by": {
                    "type": "illegal_argument_exception",
                    "reason": cause
                }
            },
            "status": 400
        }),
    )
}

fn parse_opensearch_int_value(value: &Value) -> Option<i64> {
    if let Some(value) = value.as_i64() {
        return Some(value);
    }
    let parsed = value.as_str()?.parse::<f64>().ok()?;
    if !parsed.is_finite() || parsed < i32::MIN as f64 || parsed > i32::MAX as f64 {
        return None;
    }
    Some(parsed as i64)
}

fn parse_search_slice(slice: Option<&Value>) -> Option<ParsedSearchSlice> {
    let object = slice?.as_object()?;
    let field = object
        .get("field")
        .and_then(Value::as_str)
        .unwrap_or("_id")
        .to_string();
    let id = object
        .get("id")
        .and_then(parse_opensearch_int_value)
        .and_then(|value| u64::try_from(value).ok())?;
    let max = object
        .get("max")
        .and_then(parse_opensearch_int_value)
        .and_then(|value| u64::try_from(value).ok())?;
    Some(ParsedSearchSlice { field, id, max })
}

fn document_matches_search_slice(doc_id: &str, source: &Value, slice: &ParsedSearchSlice) -> bool {
    if slice.max <= 1 {
        return true;
    }
    let hash = if slice.field == "_id" {
        opensearch_terms_slice_hash(&opensearch_uid_encoded_utf8_id(doc_id))
    } else {
        let key = extract_source_path_value(source, &slice.field)
            .map(|value| search_slice_value_key(&value))
            .unwrap_or_default();
        opensearch_terms_slice_hash(key.as_bytes())
    };
    hash.rem_euclid(slice.max as i64) as u64 == slice.id
}

fn document_matches_requested_routing_shards(
    index: &str,
    doc_id: &str,
    record: &StoredDocument,
    requested_routing_values: &[String],
    shard_count_for_index: impl Fn(&str) -> usize,
) -> bool {
    let shard_count = shard_count_for_index(index).max(1);
    let doc_routing = record.routing.as_deref().unwrap_or(doc_id);
    let doc_shard = opensearch_routing_shard(doc_routing, shard_count);
    requested_routing_values
        .iter()
        .any(|routing| opensearch_routing_shard(routing, shard_count) == doc_shard)
}

fn opensearch_routing_shard(routing: &str, shard_count: usize) -> usize {
    if shard_count <= 1 {
        return 0;
    }
    opensearch_routing_hash(routing).rem_euclid(shard_count as i64) as usize
}

fn opensearch_shard_doc_sort_key(shard_count: usize, routing: &str, seq_no: i64) -> i64 {
    let shard_id = opensearch_routing_shard(routing, shard_count) as i64;
    (shard_id << 32) | (seq_no & 0xffff_ffff)
}

fn opensearch_routing_hash(routing: &str) -> i64 {
    let mut bytes = Vec::with_capacity(routing.len() * 2);
    for code_unit in routing.encode_utf16() {
        bytes.push((code_unit & 0xff) as u8);
        bytes.push((code_unit >> 8) as u8);
    }
    opensearch_murmur3_x86_32(&bytes, 0)
}

fn search_slice_value_key(value: &Value) -> String {
    match value {
        Value::String(value) => format!("s:{value}"),
        Value::Number(value) => format!("n:{value}"),
        Value::Bool(value) => format!("b:{value}"),
        Value::Null => "null".to_string(),
        _ => value.to_string(),
    }
}

fn opensearch_uid_encoded_utf8_id(id: &str) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(id.len() + 1);
    encoded.push(0xff);
    encoded.extend_from_slice(id.as_bytes());
    encoded
}

fn opensearch_terms_slice_hash(value: &[u8]) -> i64 {
    // Mirrors TermsSliceQuery's fixed-seed StringHelper.murmurhash3_x86_32 partitioning.
    opensearch_murmur3_x86_32(value, 7919)
}

fn opensearch_murmur3_x86_32(value: &[u8], seed: u32) -> i64 {
    let mut hash = seed;
    let mut chunks = value.chunks_exact(4);
    for chunk in &mut chunks {
        let mut k = u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        k = k.wrapping_mul(0xcc9e2d51);
        k = k.rotate_left(15);
        k = k.wrapping_mul(0x1b873593);

        hash ^= k;
        hash = hash.rotate_left(13);
        hash = hash.wrapping_mul(5).wrapping_add(0xe6546b64);
    }

    let tail = chunks.remainder();
    let mut k = 0_u32;
    match tail.len() {
        3 => {
            k ^= u32::from(tail[2]) << 16;
            k ^= u32::from(tail[1]) << 8;
            k ^= u32::from(tail[0]);
        }
        2 => {
            k ^= u32::from(tail[1]) << 8;
            k ^= u32::from(tail[0]);
        }
        1 => {
            k ^= u32::from(tail[0]);
        }
        _ => {}
    }
    if !tail.is_empty() {
        k = k.wrapping_mul(0xcc9e2d51);
        k = k.rotate_left(15);
        k = k.wrapping_mul(0x1b873593);
        hash ^= k;
    }

    hash ^= value.len() as u32;
    hash ^= hash >> 16;
    hash = hash.wrapping_mul(0x85ebca6b);
    hash ^= hash >> 13;
    hash = hash.wrapping_mul(0xc2b2ae35);
    hash ^= hash >> 16;
    i32::from_ne_bytes(hash.to_ne_bytes()) as i64
}

fn search_after_validation_error(reason: impl Into<String>) -> RestResponse {
    let reason = reason.into();
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn search_after_phase_execution_error(reason: impl Into<String>) -> RestResponse {
    let reason = reason.into();
    RestResponse::json(
        500,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "search_exception",
                        "reason": reason
                    }
                ],
                "caused_by": {
                    "type": "search_exception",
                    "reason": reason
                }
            },
            "status": 500
        }),
    )
}

fn search_phase_rejected_execution_error(reason: impl Into<String>) -> RestResponse {
    let reason = reason.into();
    RestResponse::json(
        429,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "rejected_execution_exception",
                        "reason": reason
                    }
                ],
                "caused_by": {
                    "type": "rejected_execution_exception",
                    "reason": reason
                }
            },
            "status": 429
        }),
    )
}

fn validate_search_after_sort_values_against_mappings(
    body: &Value,
    index_mappings: &std::collections::HashMap<String, Value>,
) -> Option<RestResponse> {
    let sort_fields = body.get("sort").and_then(search_sort_fields)?;
    let search_after = body.get("search_after").and_then(Value::as_array)?;
    for (sort_field, after_value) in sort_fields.iter().zip(search_after.iter()) {
        let Some(field_name) = sort_field_name(sort_field) else {
            continue;
        };
        if field_name.starts_with('_') {
            continue;
        }
        let Some(field_type) = index_mappings
            .values()
            .find_map(|mappings| lookup_mapping_property(mappings, field_name))
            .and_then(|mapping| mapping.get("type"))
            .and_then(Value::as_str)
        else {
            continue;
        };
        if search_after_value_mismatches_sort_type(after_value, field_type) {
            return Some(search_after_validation_error(format!(
                "Failed to parse search_after value for field [{field_name}]."
            )));
        }
    }
    None
}

fn validate_search_sort_modes_against_mappings(
    body: &Value,
    index_mappings: &std::collections::HashMap<String, Value>,
) -> Option<RestResponse> {
    let sort_fields = body.get("sort").and_then(search_sort_fields)?;
    for sort_field in &sort_fields {
        let Some(mode) = sort_field_mode(sort_field) else {
            continue;
        };
        if sort_mode_numeric_only(mode) {
            let Some(field_name) = sort_field_name(sort_field) else {
                continue;
            };
            if field_name.starts_with('_') {
                continue;
            }
            let Some(field_type) = index_mappings
                .values()
                .find_map(|mappings| lookup_mapping_property(mappings, field_name))
                .and_then(|mapping| mapping.get("type"))
                .and_then(Value::as_str)
            else {
                continue;
            };
            if !sort_field_type_is_numeric(field_type) {
                return Some(search_after_validation_error(
                    "we only support AVG, MEDIAN and SUM on number based fields",
                ));
            }
        }
    }
    None
}

fn collect_search_sort_unmapped_field_failures(
    body: &Value,
    index_mappings: &std::collections::HashMap<String, Value>,
) -> std::collections::BTreeMap<String, String> {
    let Some(sort_fields) = body.get("sort").and_then(search_sort_fields) else {
        return std::collections::BTreeMap::new();
    };
    let mut failures = std::collections::BTreeMap::new();
    for sort_field in &sort_fields {
        let Some(field_name) = sort_field_name(sort_field) else {
            continue;
        };
        if field_name.starts_with('_')
            || sort_field_unmapped_type(sort_field).is_some()
            || request_scoped_sort_field_is_defined(body, field_name)
        {
            continue;
        }
        for (index_name, mappings) in index_mappings {
            if lookup_mapping_property(mappings, field_name).is_none() {
                failures
                    .entry(index_name.clone())
                    .or_insert_with(|| field_name.to_string());
            }
        }
    }
    failures
}

fn search_shard_failure_reason(
    index: &str,
    geo_failed_indices: &std::collections::BTreeSet<String>,
    sort_unmapped_failures: &std::collections::BTreeMap<String, String>,
) -> Value {
    if let Some(field_name) = sort_unmapped_failures.get(index) {
        return serde_json::json!({
            "type": "query_shard_exception",
            "reason": format!("No mapping found for [{field_name}] in order to sort on"),
            "index": index
        });
    }
    if geo_failed_indices.contains(index) {
        return serde_json::json!({
            "type": "query_shard_exception",
            "reason": "failed to execute geo_distance query on field [location]"
        });
    }
    serde_json::json!({
        "type": "query_shard_exception",
        "reason": "failed to execute query"
    })
}

fn request_scoped_sort_field_is_defined(body: &Value, field_name: &str) -> bool {
    ["runtime_mappings", "derived"]
        .iter()
        .any(|field_container| {
            body.get(*field_container)
                .and_then(Value::as_object)
                .is_some_and(|fields| fields.contains_key(field_name))
        })
}

fn search_after_value_mismatches_sort_type(value: &Value, field_type: &str) -> bool {
    if !sort_field_type_is_numeric(field_type) {
        return false;
    }
    match value {
        Value::Number(_) => false,
        Value::String(raw) => raw.parse::<f64>().is_err(),
        _ => true,
    }
}

fn sort_field_type_is_numeric(field_type: &str) -> bool {
    matches!(
        field_type,
        "long" | "integer" | "short" | "byte" | "double" | "float" | "half_float" | "scaled_float"
    )
}

fn validate_highlight_request_body(highlight: &Value) -> Option<RestResponse> {
    let Some(object) = highlight.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported highlight query shape",
        ));
    };
    for key in object.keys() {
        if key != "fields" && key != "pre_tags" && key != "post_tags" && key != "encoder" {
            return Some(build_unsupported_search_response(&format!(
                "unsupported highlight parameter [{key}]"
            )));
        }
    }
    let Some(fields) = object.get("fields").and_then(Value::as_object) else {
        return Some(build_unsupported_search_response(
            "unsupported highlight query shape",
        ));
    };
    if fields.is_empty() {
        return Some(build_unsupported_search_response(
            "unsupported highlight query shape",
        ));
    }
    for config in fields.values() {
        if !config
            .as_object()
            .is_some_and(|field_object| field_object.is_empty())
        {
            return Some(build_unsupported_search_response(
                "unsupported highlight field configuration",
            ));
        }
    }
    for tags_key in ["pre_tags", "post_tags"] {
        if let Some(tags) = object.get(tags_key) {
            if !tags
                .as_array()
                .is_some_and(|items| items.iter().all(|item| item.as_str().is_some()))
            {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported highlight parameter [{tags_key}]"
                )));
            }
        }
    }
    None
}

fn validate_suggest_request_body(suggest: &Value) -> Option<RestResponse> {
    let Some(object) = suggest.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported suggest query shape",
        ));
    };
    if object.is_empty() {
        return Some(build_unsupported_search_response(
            "unsupported suggest query shape",
        ));
    }
    for (name, entry) in object {
        let Some(entry_object) = entry.as_object() else {
            return Some(build_unsupported_search_response(&format!(
                "unsupported suggest entry [{name}]"
            )));
        };
        if let Some(term) = entry_object.get("term").and_then(Value::as_object) {
            let Some(text) = entry_object.get("text").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported suggest entry [{name}]"
                )));
            };
            if text.is_empty() {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported suggest entry [{name}]"
                )));
            }
            if entry_object
                .keys()
                .any(|key| key != "text" && key != "term")
            {
                return Some(build_unsupported_search_response(
                    "unsupported suggest parameter",
                ));
            }
            let Some(field) = term.get("field").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [term]",
                ));
            };
            if field.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [term]",
                ));
            }
            if term.keys().any(|key| key != "field" && key != "size") {
                return Some(build_unsupported_search_response(
                    "unsupported term suggest parameter",
                ));
            }
            continue;
        }
        if let Some(completion) = entry_object.get("completion").and_then(Value::as_object) {
            let Some(prefix) = entry_object.get("prefix").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [completion]",
                ));
            };
            if prefix.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [completion]",
                ));
            }
            if entry_object
                .keys()
                .any(|key| key != "prefix" && key != "completion")
            {
                return Some(build_unsupported_search_response(
                    "unsupported suggest parameter",
                ));
            }
            let Some(field) = completion.get("field").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [completion]",
                ));
            };
            if field.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [completion]",
                ));
            }
            if completion.keys().any(|key| key != "field" && key != "size") {
                return Some(build_unsupported_search_response(
                    "unsupported completion suggest parameter",
                ));
            }
            continue;
        }
        if let Some(phrase) = entry_object.get("phrase").and_then(Value::as_object) {
            let Some(text) = entry_object.get("text").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [phrase]",
                ));
            };
            if text.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [phrase]",
                ));
            }
            if entry_object
                .keys()
                .any(|key| key != "text" && key != "phrase")
            {
                return Some(build_unsupported_search_response(
                    "unsupported suggest parameter",
                ));
            }
            let Some(field) = phrase.get("field").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [phrase]",
                ));
            };
            if field.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported suggest family [phrase]",
                ));
            }
            if phrase.keys().any(|key| key != "field") {
                return Some(build_unsupported_search_response(
                    "unsupported phrase suggest parameter",
                ));
            }
            continue;
        }
        return Some(build_unsupported_search_response(
            "unsupported suggest family",
        ));
    }
    None
}

fn validate_search_query_body(query: &Value) -> Option<RestResponse> {
    let Some(query_object) = query.as_object() else {
        return None;
    };
    let Some((query_kind, _)) = query_object.iter().next() else {
        return None;
    };
    match query_kind.as_str() {
        "match_all"
        | "match_none"
        | "term"
        | "terms"
        | "match"
        | "multi_match"
        | "match_phrase"
        | "match_phrase_prefix"
        | "match_bool_prefix"
        | "combined_fields"
        | "dis_max"
        | "ids"
        | "query_string"
        | "simple_query_string"
        | "wildcard"
        | "prefix"
        | "regexp"
        | "fuzzy"
        | "exists"
        | "terms_set"
        | "wrapper"
        | "nested"
        | "constant_score"
        | "geo_distance"
        | "geo_bounding_box"
        | "geo_polygon"
        | "geo_shape"
        | "function_score"
        | "script_score"
        | "script"
        | "span_term"
        | "span_gap"
        | "span_or"
        | "span_near"
        | "span_multi"
        | "field_masking_span"
        | "more_like_this"
        | "distance_feature"
        | "rank_feature"
        | "intervals"
        | "boosting"
        | "bool"
        | "range"
        | "knn" => validate_supported_query_shape(query),
        "hybrid" => validate_supported_query_shape(query),
        unsupported => Some(build_unsupported_search_response(&format!(
            "unsupported query [{unsupported}]"
        ))),
    }
}

fn validate_function_score_body(spec: &serde_json::Map<String, Value>) -> Option<RestResponse> {
    let Some(inner_query) = spec.get("query") else {
        return Some(build_unsupported_search_response(
            "unsupported function_score query shape",
        ));
    };
    if spec.keys().any(|key| {
        !matches!(
            key.as_str(),
            "query"
                | "weight"
                | "boost_mode"
                | "score_mode"
                | "functions"
                | "field_value_factor"
                | "random_score"
                | "gauss"
                | "linear"
                | "exp"
        )
    }) {
        return Some(build_unsupported_search_response(
            "unsupported function_score parameter",
        ));
    }
    if let Some(response) = validate_positive_number_option(spec.get("weight"), "weight") {
        return Some(response);
    }
    if let Some(boost_mode) = spec.get("boost_mode").and_then(Value::as_str) {
        if boost_mode != "multiply" && boost_mode != "replace" {
            return Some(build_unsupported_search_response(
                "unsupported function_score boost_mode",
            ));
        }
    }
    if let Some(score_mode) = spec.get("score_mode").and_then(Value::as_str) {
        if !matches!(
            score_mode,
            "multiply" | "sum" | "avg" | "max" | "min" | "first"
        ) {
            return Some(build_unsupported_search_response(
                "unsupported function_score score_mode",
            ));
        }
    }
    if let Some(functions) = spec.get("functions") {
        let Some(functions) = functions.as_array() else {
            return Some(build_unsupported_search_response(
                "unsupported function_score functions",
            ));
        };
        for function in functions {
            let Some(function) = function.as_object() else {
                return Some(build_unsupported_search_response(
                    "unsupported function_score function",
                ));
            };
            if let Some(response) = validate_function_score_function(function) {
                return Some(response);
            }
        }
    }
    if let Some(field_value_factor) = spec.get("field_value_factor") {
        if let Some(response) = validate_field_value_factor_function(field_value_factor) {
            return Some(response);
        }
    }
    if let Some(random_score) = spec.get("random_score") {
        if let Some(response) = validate_random_score_function(random_score) {
            return Some(response);
        }
    }
    for decay_kind in ["gauss", "linear", "exp"] {
        if let Some(decay) = spec.get(decay_kind) {
            if let Some(response) = validate_decay_score_function(decay_kind, decay) {
                return Some(response);
            }
        }
    }
    if let Some(response) = validate_search_query_body(inner_query) {
        return Some(response);
    }
    None
}

fn validate_function_score_function(
    function: &serde_json::Map<String, Value>,
) -> Option<RestResponse> {
    if function.keys().any(|key| {
        !matches!(
            key.as_str(),
            "filter"
                | "weight"
                | "field_value_factor"
                | "random_score"
                | "gauss"
                | "linear"
                | "exp"
        )
    }) {
        return Some(build_unsupported_search_response(
            "unsupported function_score function parameter",
        ));
    }
    if let Some(response) = validate_positive_number_option(function.get("weight"), "weight") {
        return Some(response);
    }
    if let Some(filter) = function.get("filter") {
        if let Some(response) = validate_search_query_body(filter) {
            return Some(response);
        }
    }
    if let Some(field_value_factor) = function.get("field_value_factor") {
        if let Some(response) = validate_field_value_factor_function(field_value_factor) {
            return Some(response);
        }
    }
    if let Some(random_score) = function.get("random_score") {
        if let Some(response) = validate_random_score_function(random_score) {
            return Some(response);
        }
    }
    for decay_kind in ["gauss", "linear", "exp"] {
        if let Some(decay) = function.get(decay_kind) {
            if let Some(response) = validate_decay_score_function(decay_kind, decay) {
                return Some(response);
            }
        }
    }
    if !function.contains_key("weight")
        && !function.contains_key("field_value_factor")
        && !function.contains_key("random_score")
        && !function.contains_key("gauss")
        && !function.contains_key("linear")
        && !function.contains_key("exp")
    {
        return Some(build_unsupported_search_response(
            "unsupported function_score function",
        ));
    }
    None
}

fn validate_positive_number_option(value: Option<&Value>, name: &str) -> Option<RestResponse> {
    let Some(value) = value else {
        return None;
    };
    let Some(number) = value.as_f64() else {
        return Some(build_unsupported_search_response(&format!(
            "unsupported function_score {name}"
        )));
    };
    if number <= 0.0 {
        return Some(build_unsupported_search_response(&format!(
            "unsupported function_score {name}"
        )));
    }
    None
}

fn validate_field_value_factor_function(value: &Value) -> Option<RestResponse> {
    let Some(object) = value.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported field_value_factor function",
        ));
    };
    if object
        .keys()
        .any(|key| !matches!(key.as_str(), "field" | "factor" | "missing" | "modifier"))
    {
        return Some(build_unsupported_search_response(
            "unsupported field_value_factor parameter",
        ));
    }
    let Some(field) = object.get("field").and_then(Value::as_str) else {
        return Some(build_unsupported_search_response(
            "unsupported field_value_factor field",
        ));
    };
    if field.is_empty() {
        return Some(build_unsupported_search_response(
            "unsupported field_value_factor field",
        ));
    }
    for option in ["factor", "missing"] {
        if object.get(option).is_some_and(|value| !value.is_number()) {
            return Some(build_unsupported_search_response(&format!(
                "unsupported field_value_factor {option}"
            )));
        }
    }
    if let Some(modifier) = object.get("modifier").and_then(Value::as_str) {
        if modifier != "none" {
            return Some(build_unsupported_search_response(
                "unsupported field_value_factor modifier",
            ));
        }
    }
    None
}

fn validate_random_score_function(value: &Value) -> Option<RestResponse> {
    let Some(object) = value.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported random_score function",
        ));
    };
    if object.keys().any(|key| !matches!(key.as_str(), "seed")) {
        return Some(build_unsupported_search_response(
            "unsupported random_score parameter",
        ));
    }
    if object
        .get("seed")
        .is_some_and(|seed| !(seed.is_string() || seed.is_number()))
    {
        return Some(build_unsupported_search_response(
            "unsupported random_score seed",
        ));
    }
    None
}

fn validate_decay_score_function(decay_kind: &str, value: &Value) -> Option<RestResponse> {
    let Some(object) = value.as_object() else {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} function"
        )));
    };
    if object.is_empty() {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} function"
        )));
    }
    let mut decay_fields = object
        .iter()
        .filter(|(key, _)| key.as_str() != "multi_value_mode");
    let Some((field, spec)) = decay_fields.next() else {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} function"
        )));
    };
    if field.is_empty() || decay_fields.next().is_some() {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} function"
        )));
    }
    if let Some(mode) = object.get("multi_value_mode").and_then(Value::as_str) {
        if !matches!(mode, "min" | "max" | "avg" | "sum") {
            return Some(build_unsupported_search_response(&format!(
                "unsupported {decay_kind} multi_value_mode"
            )));
        }
    }
    let Some(spec) = spec.as_object() else {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} function"
        )));
    };
    if spec
        .keys()
        .any(|key| !matches!(key.as_str(), "origin" | "scale" | "offset" | "decay"))
    {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} parameter"
        )));
    }
    for required in ["origin", "scale"] {
        let Some(value) = spec.get(required).and_then(Value::as_f64) else {
            return Some(build_unsupported_search_response(&format!(
                "unsupported {decay_kind} {required}"
            )));
        };
        if required == "scale" && value <= 0.0 {
            return Some(build_unsupported_search_response(&format!(
                "unsupported {decay_kind} scale"
            )));
        }
    }
    if spec
        .get("offset")
        .is_some_and(|value| match value.as_f64() {
            Some(offset) => offset < 0.0,
            None => true,
        })
    {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} offset"
        )));
    }
    if spec.get("decay").is_some_and(|value| match value.as_f64() {
        Some(decay) => !(0.0..1.0).contains(&decay),
        None => true,
    }) {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {decay_kind} decay"
        )));
    }
    None
}

fn validate_supported_query_shape(query: &Value) -> Option<RestResponse> {
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        let Some((_, spec)) = knn.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported knn query shape",
            ));
        };
        let Some(spec_object) = spec.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported knn query shape",
            ));
        };
        for key in spec_object.keys() {
            if key != "vector"
                && key != "k"
                && key != "filter"
                && key != "ignore_unmapped"
                && key != "expand_nested"
                && key != "max_distance"
                && key != "min_score"
                && key != "method_parameters"
            {
                return Some(build_x_content_parse_search_response(&format!(
                    "unsupported knn parameter [{key}]"
                )));
            }
        }
        if !spec_object
            .get("vector")
            .and_then(Value::as_array)
            .is_some_and(|values| values.iter().all(Value::is_number))
        {
            return Some(build_unsupported_search_response(
                "unsupported knn vector shape",
            ));
        }
        let has_k = spec_object.get("k").and_then(Value::as_u64).unwrap_or(0) > 0;
        let has_max_distance = spec_object
            .get("max_distance")
            .and_then(Value::as_f64)
            .is_some_and(|value| value > 0.0);
        let has_min_score = spec_object
            .get("min_score")
            .and_then(Value::as_f64)
            .is_some_and(|value| value > 0.0);
        if !has_k && !has_max_distance && !has_min_score {
            return Some(build_unsupported_search_response(
                "unsupported knn parameter [k]",
            ));
        }
        if let Some(filter) = spec_object.get("filter") {
            if let Some(response) = validate_search_query_body(filter) {
                return Some(response);
            }
        }
        if spec_object
            .get("ignore_unmapped")
            .is_some_and(|value| !value.is_boolean())
        {
            return Some(build_unsupported_search_response(
                "unsupported knn parameter [ignore_unmapped]",
            ));
        }
        if spec_object
            .get("expand_nested")
            .is_some_and(|value| !value.is_boolean())
        {
            return Some(build_unsupported_search_response(
                "unsupported knn parameter [expand_nested]",
            ));
        }
        if let Some(method_parameters) = spec_object.get("method_parameters") {
            let Some(object) = method_parameters.as_object() else {
                return Some(build_unsupported_search_response(
                    "unsupported knn parameter [method_parameters]",
                ));
            };
            if object.values().any(|value| value.as_u64().is_none()) {
                return Some(build_unsupported_search_response(
                    "unsupported knn parameter [method_parameters]",
                ));
            }
        }
    }
    if let Some(spec) = query.get("hybrid").and_then(Value::as_object) {
        let Some(queries) = spec.get("queries").and_then(Value::as_array) else {
            return Some(build_parsing_search_response(
                "unsupported hybrid query shape",
            ));
        };
        if queries.is_empty() || spec.keys().any(|key| key != "queries") {
            return Some(build_parsing_search_response(
                "unsupported hybrid query shape",
            ));
        }
        let mut knn_count = 0usize;
        for clause in queries {
            if query_uses_pure_knn_candidate_path(clause) {
                knn_count += 1;
            }
            if let Some(response) = validate_search_query_body(clause) {
                return Some(response);
            }
        }
        if knn_count != 1 {
            return Some(build_parsing_search_response(
                "unsupported hybrid query shape",
            ));
        }
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        for clause_name in ["must", "filter", "should", "must_not"] {
            for clause in bool_query_clauses(bool_query, clause_name) {
                if let Some(response) = validate_search_query_body(clause) {
                    return Some(response);
                }
            }
        }
    }
    if let Some(match_bool_prefix) = query.get("match_bool_prefix").and_then(Value::as_object) {
        let Some((_, spec)) = match_bool_prefix.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported match_bool_prefix query shape",
            ));
        };
        let valid = spec.as_str().is_some_and(|value| !value.is_empty())
            || spec
                .as_object()
                .and_then(|object| object.get("query"))
                .and_then(Value::as_str)
                .is_some_and(|value| !value.is_empty());
        if match_bool_prefix.len() != 1 || !valid {
            return Some(build_unsupported_search_response(
                "unsupported match_bool_prefix query shape",
            ));
        }
    }
    if let Some(combined_fields) = query.get("combined_fields").and_then(Value::as_object) {
        let valid_query = combined_fields
            .get("query")
            .and_then(Value::as_str)
            .is_some_and(|value| !value.is_empty());
        let valid_fields = combined_fields
            .get("fields")
            .and_then(Value::as_array)
            .is_some_and(|fields| !fields.is_empty() && fields.iter().all(Value::is_string));
        if !valid_query || !valid_fields {
            return Some(build_unsupported_search_response(
                "unsupported combined_fields query shape",
            ));
        }
        if combined_fields
            .keys()
            .any(|key| key != "query" && key != "fields")
        {
            return Some(build_unsupported_search_response(
                "unsupported combined_fields parameter",
            ));
        }
    }
    if let Some(constant_score) = query.get("constant_score").and_then(Value::as_object) {
        let inner_query = constant_score
            .get("filter")
            .or_else(|| constant_score.get("query"));
        let Some(inner_query) = inner_query else {
            return Some(build_unsupported_search_response(
                "unsupported constant_score query shape",
            ));
        };
        if let Some(response) = validate_search_query_body(inner_query) {
            return Some(response);
        }
    }
    if query.get("wrapper").is_some() {
        let Ok(inner_query) = decode_wrapper_query(query) else {
            return Some(build_unsupported_search_response(
                "unsupported wrapper query shape",
            ));
        };
        if let Some(response) = validate_search_query_body(&inner_query) {
            return Some(response);
        }
    }
    if let Some(boosting) = query.get("boosting").and_then(Value::as_object) {
        let Some(positive) = boosting.get("positive") else {
            return Some(build_unsupported_search_response(
                "unsupported boosting query shape",
            ));
        };
        let Some(negative) = boosting.get("negative") else {
            return Some(build_unsupported_search_response(
                "unsupported boosting query shape",
            ));
        };
        if !boosting
            .get("negative_boost")
            .and_then(Value::as_f64)
            .is_some_and(|value| value >= 0.0)
        {
            return Some(build_unsupported_search_response(
                "unsupported boosting negative_boost",
            ));
        }
        for inner_query in [positive, negative] {
            if let Some(response) = validate_search_query_body(inner_query) {
                return Some(response);
            }
        }
    }
    if let Some(dis_max) = query.get("dis_max").and_then(Value::as_object) {
        let Some(queries) = dis_max.get("queries").and_then(Value::as_array) else {
            return Some(build_unsupported_search_response(
                "unsupported dis_max query shape",
            ));
        };
        for clause in queries {
            if let Some(response) = validate_search_query_body(clause) {
                return Some(response);
            }
        }
    }
    for query_name in ["query_string", "simple_query_string"] {
        if let Some(spec) = query.get(query_name).and_then(Value::as_object) {
            if spec
                .get("query")
                .and_then(Value::as_str)
                .map(str::is_empty)
                .unwrap_or(true)
            {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported {query_name} query shape"
                )));
            }
            if let Some(fields) = spec.get("fields") {
                if !fields
                    .as_array()
                    .is_some_and(|items| items.iter().all(|value| value.as_str().is_some()))
                {
                    return Some(build_unsupported_search_response(&format!(
                        "unsupported {query_name} fields shape"
                    )));
                }
            }
            if let Some(default_operator) = spec.get("default_operator").and_then(Value::as_str) {
                if default_operator != "and" && default_operator != "or" {
                    return Some(build_unsupported_search_response(&format!(
                        "unsupported {query_name} default operator"
                    )));
                }
            }
            for key in spec.keys() {
                if key != "query" && key != "fields" && key != "default_operator" {
                    return Some(build_unsupported_search_response(&format!(
                        "unsupported {query_name} parameter [{key}]"
                    )));
                }
            }
        }
    }
    for query_name in ["wildcard", "prefix"] {
        if let Some(spec) = query.get(query_name).and_then(Value::as_object) {
            let Some((_, value)) = spec.iter().next() else {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported {query_name} query shape"
                )));
            };
            let candidate_value = if let Some(object) = value.as_object() {
                if object
                    .keys()
                    .any(|key| key != "value" && key != "case_insensitive")
                {
                    return Some(build_unsupported_search_response(&format!(
                        "unsupported {query_name} parameter"
                    )));
                }
                if object
                    .get("case_insensitive")
                    .is_some_and(|value| !value.is_boolean())
                {
                    return Some(build_unsupported_search_response(&format!(
                        "unsupported {query_name} parameter"
                    )));
                }
                object.get("value").and_then(Value::as_str)
            } else {
                value.as_str()
            };
            if candidate_value.map(str::is_empty).unwrap_or(true) {
                return Some(build_unsupported_search_response(&format!(
                    "unsupported {query_name} query shape"
                )));
            }
        }
    }
    if let Some(spec) = query.get("regexp").and_then(Value::as_object) {
        let Some((_, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported regexp query shape",
            ));
        };
        let candidate_value = if let Some(object) = value.as_object() {
            if object.keys().any(|key| key != "value") {
                return Some(build_unsupported_search_response(
                    "unsupported regexp parameter",
                ));
            }
            object.get("value").and_then(Value::as_str)
        } else {
            value.as_str()
        };
        if candidate_value.map(str::is_empty).unwrap_or(true) {
            return Some(build_unsupported_search_response(
                "unsupported regexp query shape",
            ));
        }
    }
    if let Some(spec) = query.get("fuzzy").and_then(Value::as_object) {
        let Some((_, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported fuzzy query shape",
            ));
        };
        if let Some(object) = value.as_object() {
            let Some(query_value) = object.get("value").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported fuzzy query shape",
                ));
            };
            if query_value.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported fuzzy query shape",
                ));
            }
            if object
                .keys()
                .any(|key| key != "value" && key != "fuzziness")
            {
                return Some(build_unsupported_search_response(
                    "unsupported fuzzy parameter",
                ));
            }
            if let Some(fuzziness) = object.get("fuzziness") {
                if !(fuzziness.as_u64().is_some()
                    || fuzziness.as_str().is_some_and(|value| value == "AUTO"))
                {
                    return Some(build_unsupported_search_response(
                        "unsupported fuzzy fuzziness",
                    ));
                }
            }
        } else if value.as_str().map(str::is_empty).unwrap_or(true) {
            return Some(build_unsupported_search_response(
                "unsupported fuzzy query shape",
            ));
        }
    }
    if let Some(spec) = query.get("exists").and_then(Value::as_object) {
        if spec.len() != 1 || spec.get("field").and_then(Value::as_str).is_none() {
            return Some(build_parsing_search_response(
                "[exists] must be provided with a [field]",
            ));
        }
    }
    if let Some(spec) = query.get("terms_set").and_then(Value::as_object) {
        let Some((_, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported terms_set query shape",
            ));
        };
        let Some(object) = value.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported terms_set query shape",
            ));
        };
        if !object
            .get("terms")
            .and_then(Value::as_array)
            .is_some_and(|items| {
                items
                    .iter()
                    .all(|item| item.is_string() || item.is_number())
            })
        {
            return Some(build_unsupported_search_response(
                "unsupported terms_set terms",
            ));
        }
        if object
            .get("minimum_should_match")
            .and_then(Value::as_u64)
            .is_none()
            && object
                .get("minimum_should_match_script")
                .and_then(Value::as_object)
                .and_then(|script| script.get("source"))
                .and_then(|source| {
                    source
                        .as_u64()
                        .or_else(|| source.as_str().and_then(|value| value.parse::<u64>().ok()))
                })
                .is_none()
        {
            return Some(build_unsupported_search_response(
                "unsupported terms_set minimum_should_match",
            ));
        }
        if object.keys().any(|key| {
            key != "terms" && key != "minimum_should_match" && key != "minimum_should_match_script"
        }) {
            return Some(build_unsupported_search_response(
                "unsupported terms_set parameter",
            ));
        }
    }
    if let Some(spec) = query.get("distance_feature").and_then(Value::as_object) {
        if spec.get("field").and_then(Value::as_str).is_none()
            || !spec.contains_key("origin")
            || !spec.contains_key("pivot")
        {
            return Some(build_unsupported_search_response(
                "unsupported distance_feature query shape",
            ));
        }
        if spec
            .keys()
            .any(|key| key != "field" && key != "origin" && key != "pivot")
        {
            return Some(build_unsupported_search_response(
                "unsupported distance_feature parameter",
            ));
        }
    }
    if let Some(spec) = query.get("rank_feature").and_then(Value::as_object) {
        if spec.get("field").and_then(Value::as_str).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported rank_feature query shape",
            ));
        }
        if spec.keys().any(|key| key != "field") {
            return Some(build_unsupported_search_response(
                "unsupported rank_feature parameter",
            ));
        }
    }
    if let Some(spec) = query.get("nested").and_then(Value::as_object) {
        let Some(path) = spec.get("path").and_then(Value::as_str) else {
            return Some(build_unsupported_search_response(
                "unsupported nested query shape",
            ));
        };
        if path.is_empty() {
            return Some(build_unsupported_search_response(
                "unsupported nested query shape",
            ));
        }
        let Some(inner_query) = spec.get("query") else {
            return Some(build_unsupported_search_response(
                "unsupported nested query shape",
            ));
        };
        if spec.keys().any(|key| key != "path" && key != "query") {
            return Some(build_unsupported_search_response(
                "unsupported nested parameter",
            ));
        }
        if let Some(response) = validate_search_query_body(inner_query) {
            return Some(response);
        }
    }
    if let Some(spec) = query.get("geo_distance").and_then(Value::as_object) {
        let Some(distance) = spec.get("distance").and_then(Value::as_str) else {
            return Some(build_unsupported_search_response(
                "unsupported geo_distance query shape",
            ));
        };
        if parse_distance_meters(distance).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported geo_distance distance",
            ));
        }
        if spec.keys().filter(|key| key.as_str() != "distance").count() != 1 {
            return Some(build_unsupported_search_response(
                "unsupported geo_distance query shape",
            ));
        }
        let Some((field, point)) = spec.iter().find(|(key, _)| key.as_str() != "distance") else {
            return Some(build_unsupported_search_response(
                "unsupported geo_distance query shape",
            ));
        };
        if field.is_empty() || parse_geo_point_value(point).is_none() {
            return Some(build_unsupported_search_response(
                "unsupported geo_distance query shape",
            ));
        }
    }
    if let Some(spec) = query.get("geo_bounding_box").and_then(Value::as_object) {
        if spec
            .keys()
            .filter(|key| {
                !matches!(
                    key.as_str(),
                    "ignore_unmapped" | "validation_method" | "type" | "_name" | "boost"
                )
            })
            .count()
            != 1
        {
            return Some(build_unsupported_search_response(
                "unsupported geo_bounding_box query shape",
            ));
        }
        let Some((field, box_spec)) = spec.iter().find(|(key, _)| {
            !matches!(
                key.as_str(),
                "ignore_unmapped" | "validation_method" | "type" | "_name" | "boost"
            )
        }) else {
            return Some(build_unsupported_search_response(
                "unsupported geo_bounding_box query shape",
            ));
        };
        let Some(box_object) = box_spec.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported geo_bounding_box query shape",
            ));
        };
        let valid_box = box_object
            .get("top_left")
            .and_then(parse_geo_point_value)
            .zip(
                box_object
                    .get("bottom_right")
                    .and_then(parse_geo_point_value),
            )
            .is_some();
        if field.is_empty() || !valid_box {
            return Some(build_unsupported_search_response(
                "unsupported geo_bounding_box query shape",
            ));
        }
    }
    if let Some(spec) = query.get("geo_polygon").and_then(Value::as_object) {
        if spec
            .keys()
            .filter(|key| {
                !matches!(
                    key.as_str(),
                    "ignore_unmapped" | "validation_method" | "_name" | "boost"
                )
            })
            .count()
            != 1
        {
            return Some(build_unsupported_search_response(
                "unsupported geo_polygon query shape",
            ));
        }
        let Some((field, polygon_spec)) = spec.iter().find(|(key, _)| {
            !matches!(
                key.as_str(),
                "ignore_unmapped" | "validation_method" | "_name" | "boost"
            )
        }) else {
            return Some(build_unsupported_search_response(
                "unsupported geo_polygon query shape",
            ));
        };
        let Some(points) = polygon_spec
            .as_object()
            .and_then(|object| object.get("points"))
            .and_then(Value::as_array)
        else {
            return Some(build_unsupported_search_response(
                "unsupported geo_polygon query shape",
            ));
        };
        let parsed_points = points
            .iter()
            .map(parse_geo_point_value)
            .collect::<Option<Vec<_>>>();
        let Some(parsed_points) = parsed_points else {
            return Some(build_unsupported_search_response(
                "unsupported geo_polygon query shape",
            ));
        };
        if field.is_empty()
            || parsed_points.len() < 3
            || (parsed_points.first() == parsed_points.last() && parsed_points.len() < 4)
        {
            return Some(build_unsupported_search_response(
                "unsupported geo_polygon query shape",
            ));
        }
    }
    if let Some(spec) = query.get("geo_shape").and_then(Value::as_object) {
        if spec
            .keys()
            .filter(|key| !matches!(key.as_str(), "ignore_unmapped" | "_name" | "boost"))
            .count()
            != 1
        {
            return Some(build_unsupported_search_response(
                "unsupported geo_shape query shape",
            ));
        }
        let Some((field, shape_spec)) = spec
            .iter()
            .find(|(key, _)| !matches!(key.as_str(), "ignore_unmapped" | "_name" | "boost"))
        else {
            return Some(build_unsupported_search_response(
                "unsupported geo_shape query shape",
            ));
        };
        let Some(shape_object) = shape_spec.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported geo_shape query shape",
            ));
        };
        for key in shape_object.keys() {
            if !matches!(key.as_str(), "shape" | "relation" | "strategy") {
                return Some(build_unsupported_search_response(
                    "unsupported geo_shape parameter",
                ));
            }
        }
        if let Some(relation) = shape_object.get("relation").and_then(Value::as_str) {
            if !matches!(relation, "intersects" | "within" | "contains") {
                return Some(build_unsupported_search_response(
                    "unsupported geo_shape relation",
                ));
            }
        }
        if field.is_empty()
            || !shape_object
                .get("shape")
                .is_some_and(geo_shape_value_is_supported)
        {
            return Some(build_unsupported_search_response(
                "unsupported geo_shape query shape",
            ));
        }
    }
    if let Some(spec) = query.get("function_score").and_then(Value::as_object) {
        if let Some(response) = validate_function_score_body(spec) {
            return Some(response);
        }
    }
    if let Some(spec) = query.get("script_score").and_then(Value::as_object) {
        let Some(inner_query) = spec.get("query") else {
            return Some(build_unsupported_search_response(
                "unsupported script_score query shape",
            ));
        };
        let Some(script_source) = spec
            .get("script")
            .and_then(Value::as_object)
            .and_then(|script| script.get("source"))
            .and_then(Value::as_str)
        else {
            return Some(build_unsupported_search_response(
                "unsupported script_score query shape",
            ));
        };
        if script_source
            .parse::<f64>()
            .ok()
            .filter(|score| *score > 0.0)
            .is_none()
        {
            return Some(build_unsupported_search_response(
                "unsupported script_score source",
            ));
        }
        if spec.keys().any(|key| key != "query" && key != "script") {
            return Some(build_unsupported_search_response(
                "unsupported script_score parameter",
            ));
        }
        if let Some(response) = validate_search_query_body(inner_query) {
            return Some(response);
        }
    }
    if let Some(spec) = query.get("script").and_then(Value::as_object) {
        let Some(script) = spec.get("script") else {
            return Some(build_parsing_search_response(
                "script must be provided with a [script] filter",
            ));
        };
        if !script_filter_source(script).is_some_and(script_filter_source_is_supported) {
            return Some(build_unsupported_search_response(
                "unsupported script query source",
            ));
        }
        if spec
            .keys()
            .any(|key| key != "script" && key != "_name" && key != "boost")
        {
            return Some(build_x_content_parse_search_response(&format!(
                "[script] query does not support [{}]",
                spec.keys()
                    .find(|key| key.as_str() != "script"
                        && key.as_str() != "_name"
                        && key.as_str() != "boost")
                    .map(String::as_str)
                    .unwrap_or("unknown")
            )));
        }
    }
    if let Some(spec) = query.get("span_term").and_then(Value::as_object) {
        let Some((_, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported span_term query shape",
            ));
        };
        if value.as_str().map(str::is_empty).unwrap_or(true) {
            return Some(build_unsupported_search_response(
                "unsupported span_term query shape",
            ));
        }
    }
    if let Some(spec) = query.get("span_gap").and_then(Value::as_object) {
        let Some((field, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported span_gap query shape",
            ));
        };
        if spec.len() != 1 || field.is_empty() || value.as_u64().is_none() {
            return Some(build_unsupported_search_response(
                "unsupported span_gap query shape",
            ));
        }
    }
    if let Some(spec) = query.get("span_or").and_then(Value::as_object) {
        let Some(clauses) = spec.get("clauses").and_then(Value::as_array) else {
            return Some(build_unsupported_search_response(
                "unsupported span_or query shape",
            ));
        };
        if clauses.is_empty() {
            return Some(build_unsupported_search_response(
                "unsupported span_or query shape",
            ));
        }
        for clause in clauses {
            if let Some(response) = validate_search_query_body(clause) {
                return Some(response);
            }
        }
    }
    if let Some(spec) = query.get("span_near").and_then(Value::as_object) {
        let Some(clauses) = spec.get("clauses").and_then(Value::as_array) else {
            return Some(build_unsupported_search_response(
                "unsupported span_near query shape",
            ));
        };
        if clauses.len() < 2
            || spec.get("slop").and_then(Value::as_u64).is_none()
            || spec.get("in_order").and_then(Value::as_bool).is_none()
        {
            return Some(build_unsupported_search_response(
                "unsupported span_near query shape",
            ));
        }
        if spec
            .keys()
            .any(|key| key != "clauses" && key != "slop" && key != "in_order")
        {
            return Some(build_unsupported_search_response(
                "unsupported span_near parameter",
            ));
        }
        for clause in clauses {
            if let Some(response) = validate_search_query_body(clause) {
                return Some(response);
            }
        }
    }
    if let Some(spec) = query.get("span_multi").and_then(Value::as_object) {
        let Some(inner_match) = spec.get("match") else {
            return Some(build_unsupported_search_response(
                "unsupported span_multi query shape",
            ));
        };
        if let Some(response) = validate_search_query_body(inner_match) {
            return Some(response);
        }
    }
    if let Some(spec) = query.get("field_masking_span").and_then(Value::as_object) {
        let Some(field) = spec.get("field").and_then(Value::as_str) else {
            return Some(build_unsupported_search_response(
                "unsupported field_masking_span query shape",
            ));
        };
        if field.is_empty() {
            return Some(build_unsupported_search_response(
                "unsupported field_masking_span query shape",
            ));
        }
        let Some(inner_query) = spec.get("query") else {
            return Some(build_unsupported_search_response(
                "unsupported field_masking_span query shape",
            ));
        };
        if spec.keys().any(|key| key != "field" && key != "query") {
            return Some(build_unsupported_search_response(
                "unsupported field_masking_span parameter",
            ));
        }
        if let Some(response) = validate_search_query_body(inner_query) {
            return Some(response);
        }
    }
    if let Some(spec) = query.get("more_like_this").and_then(Value::as_object) {
        let fields_ok = !spec.contains_key("fields")
            || spec
                .get("fields")
                .and_then(Value::as_array)
                .is_some_and(|items| items.iter().all(|item| item.as_str().is_some()));
        let like_ok = spec.get("like").is_some_and(|value| match value {
            Value::String(text) => !text.is_empty(),
            Value::Array(items) => items
                .iter()
                .all(|item| item.as_str().is_some_and(|text| !text.is_empty())),
            _ => false,
        });
        if !fields_ok || !like_ok {
            return Some(build_unsupported_search_response(
                "unsupported more_like_this query shape",
            ));
        }
        if spec.keys().any(|key| {
            !matches!(
                key.as_str(),
                "fields" | "like" | "min_term_freq" | "min_doc_freq" | "max_query_terms"
            )
        }) {
            return Some(build_unsupported_search_response(
                "unsupported more_like_this parameter",
            ));
        }
    }
    if let Some(spec) = query.get("intervals").and_then(Value::as_object) {
        let Some((_, value)) = spec.iter().next() else {
            return Some(build_unsupported_search_response(
                "unsupported intervals query shape",
            ));
        };
        let Some(interval_object) = value.as_object() else {
            return Some(build_unsupported_search_response(
                "unsupported intervals query shape",
            ));
        };
        if let Some(match_spec) = interval_object.get("match").and_then(Value::as_object) {
            let Some(query_text) = match_spec.get("query").and_then(Value::as_str) else {
                return Some(build_unsupported_search_response(
                    "unsupported intervals match",
                ));
            };
            if query_text.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported intervals match",
                ));
            }
            if match_spec
                .keys()
                .any(|key| key != "query" && key != "ordered" && key != "max_gaps")
            {
                return Some(build_unsupported_search_response(
                    "unsupported intervals match parameter",
                ));
            }
        } else if let Some(all_of) = interval_object.get("all_of").and_then(Value::as_object) {
            let Some(intervals) = all_of.get("intervals").and_then(Value::as_array) else {
                return Some(build_unsupported_search_response(
                    "unsupported intervals all_of shape",
                ));
            };
            if intervals.is_empty() {
                return Some(build_unsupported_search_response(
                    "unsupported intervals all_of shape",
                ));
            }
            if all_of
                .keys()
                .any(|key| key != "intervals" && key != "ordered" && key != "max_gaps")
            {
                return Some(build_unsupported_search_response(
                    "unsupported intervals all_of parameter",
                ));
            }
            for interval in intervals {
                let Some(match_spec) = interval.get("match").and_then(Value::as_object) else {
                    return Some(build_unsupported_search_response(
                        "unsupported intervals all_of interval",
                    ));
                };
                if match_spec
                    .get("query")
                    .and_then(Value::as_str)
                    .map(str::is_empty)
                    .unwrap_or(true)
                {
                    return Some(build_unsupported_search_response(
                        "unsupported intervals all_of interval",
                    ));
                }
            }
        } else {
            return Some(build_unsupported_search_response(
                "unsupported intervals query shape",
            ));
        }
    }
    None
}

fn split_document_key(key: &str) -> Option<(&str, &str, &str)> {
    let mut parts = key.splitn(3, ':');
    Some((parts.next()?, parts.next()?, parts.next()?))
}

fn next_seq_no_by_index_from_documents(documents: &DocumentMap) -> BTreeMap<String, u64> {
    let mut next_by_index: BTreeMap<String, u64> = BTreeMap::new();
    for (key, document) in documents {
        let Some((index, _, _)) = split_document_key(key) else {
            continue;
        };
        let next = document.seq_no.saturating_add(1).max(0) as u64;
        next_by_index
            .entry(index.to_string())
            .and_modify(|current| *current = (*current).max(next))
            .or_insert(next);
    }
    next_by_index
}

fn current_epoch_millis() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("system time before unix epoch")
        .as_millis()
}

fn parse_time_value_millis(value: &str) -> Option<u64> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    let units = [
        ("micros", 1_u64, 1_000_u64),
        ("nanos", 1_u64, 1_000_000_u64),
        ("ms", 1_u64, 1_u64),
        ("s", 1_000_u64, 1_u64),
        ("m", 60_000_u64, 1_u64),
        ("h", 3_600_000_u64, 1_u64),
        ("d", 86_400_000_u64, 1_u64),
    ];
    let (number, multiplier, divisor) =
        units.iter().find_map(|(suffix, multiplier, divisor)| {
            trimmed
                .strip_suffix(suffix)
                .map(|number| (number, *multiplier, *divisor))
        })?;
    let amount = number.parse::<i128>().ok()?;
    if amount <= 0 {
        return Some(0);
    }
    u64::try_from(amount)
        .ok()
        .and_then(|amount| amount.checked_mul(multiplier))
        .map(|millis| millis / divisor)
}

fn keep_alive_parse_error_reason(value: &str) -> String {
    if time_value_has_fractional_number(value) {
        format!("failed to parse [{value}], fractional time values are not supported")
    } else {
        format!(
            "failed to parse setting [keep_alive] with value [{value}] as a time value: unit is missing or unrecognized"
        )
    }
}

fn time_value_has_fractional_number(value: &str) -> bool {
    let trimmed = value.trim();
    let units = ["micros", "nanos", "ms", "s", "m", "h", "d"];
    units
        .iter()
        .find_map(|suffix| trimmed.strip_suffix(suffix))
        .is_some_and(|number| number.contains('.'))
}

fn validate_pit_keep_alive_limit(keep_alive_millis: u64) -> Option<RestResponse> {
    if keep_alive_millis <= DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS {
        return None;
    }
    let reason = pit_keep_alive_limit_reason(keep_alive_millis);
    Some(RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    ))
}

fn pit_search_keep_alive_limit_response(
    keep_alive_millis: u64,
    index_name: Option<String>,
) -> RestResponse {
    let reason = pit_keep_alive_limit_reason(keep_alive_millis);
    let mut failed_shard = serde_json::json!({
        "shard": 0,
        "reason": {
            "type": "illegal_argument_exception",
            "reason": reason
        }
    });
    if let (Value::Object(object), Some(index_name)) = (&mut failed_shard, index_name) {
        object.insert("index".to_string(), Value::String(index_name));
    }
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ],
                "caused_by": {
                    "type": "illegal_argument_exception",
                    "reason": reason,
                    "caused_by": {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                },
                "failed_shards": [failed_shard]
            },
            "status": 400
        }),
    )
}

fn pit_keep_alive_limit_reason(keep_alive_millis: u64) -> String {
    format!(
        "Keep alive for request ({}) is too large. It must be less than ({}). This limit can be set by changing the [point_in_time.max_keep_alive] cluster level setting.",
        format_time_value_millis(keep_alive_millis),
        format_time_value_millis(DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS)
    )
}

fn normalize_pit_keep_alive_millis(keep_alive_millis: u64) -> u64 {
    if keep_alive_millis == 0 {
        DEFAULT_PIT_NON_POSITIVE_KEEP_ALIVE_MILLIS
    } else {
        keep_alive_millis
    }
}

fn pit_expires_at_millis(now_millis: u128, keep_alive_millis: u64) -> u128 {
    now_millis + u128::from(keep_alive_millis.max(DEFAULT_PIT_EXPIRY_REAPER_GRACE_MILLIS))
}

fn prune_expired_pit_contexts(contexts: &mut BTreeMap<String, PitContext>, now_millis: u128) {
    contexts.retain(|_, context| context.expires_at_millis > now_millis);
}

fn search_stats_body(
    open_contexts: u64,
    pit_current_contexts: u64,
    pit_total_contexts: u64,
) -> Value {
    serde_json::json!({
        "open_contexts": open_contexts,
        "query_total": 0,
        "query_time_in_millis": 0,
        "query_current": 0,
        "fetch_total": 0,
        "fetch_time_in_millis": 0,
        "fetch_current": 0,
        "scroll_total": 0,
        "scroll_time_in_millis": 0,
        "scroll_current": 0,
        "point_in_time_total": pit_total_contexts,
        "point_in_time_time_in_millis": 0,
        "point_in_time_current": pit_current_contexts,
        "suggest_total": 0,
        "suggest_time_in_millis": 0,
        "suggest_current": 0
    })
}

fn format_time_value_millis(value: u64) -> String {
    const DAY: u64 = 86_400_000;
    const HOUR: u64 = 3_600_000;
    const MINUTE: u64 = 60_000;
    const SECOND: u64 = 1_000;
    if value >= DAY {
        format!("{}d", value / DAY)
    } else if value % HOUR == 0 {
        format!("{}h", value / HOUR)
    } else if value % MINUTE == 0 {
        format!("{}m", value / MINUTE)
    } else if value % SECOND == 0 {
        format!("{}s", value / SECOND)
    } else {
        format!("{value}ms")
    }
}

fn bool_query_clauses<'a>(
    bool_query: &'a serde_json::Map<String, Value>,
    clause_name: &str,
) -> Vec<&'a Value> {
    match bool_query.get(clause_name) {
        Some(Value::Array(clauses)) => clauses.iter().collect(),
        Some(Value::Object(_)) => bool_query.get(clause_name).into_iter().collect(),
        _ => Vec::new(),
    }
}

fn extract_knn_field_name(query: &Value) -> Option<&str> {
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        return knn.keys().next().map(String::as_str);
    }
    if let Some(nested_query) = query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
    {
        return extract_knn_field_name(nested_query);
    }
    if let Some(queries) = query
        .get("hybrid")
        .and_then(Value::as_object)
        .and_then(|hybrid| hybrid.get("queries"))
        .and_then(Value::as_array)
    {
        return queries.iter().find_map(extract_knn_field_name);
    }
    let Some(bool_query) = query.get("bool").and_then(Value::as_object) else {
        return None;
    };
    for clause_name in ["must", "should", "filter", "must_not"] {
        if let Some(field_name) = bool_query_clauses(bool_query, clause_name)
            .into_iter()
            .find_map(extract_knn_field_name)
        {
            return Some(field_name);
        }
    }
    None
}

fn extract_knn_query_vector(query: &Value) -> Option<&Vec<Value>> {
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        return knn
            .values()
            .next()
            .and_then(Value::as_object)
            .and_then(|spec| spec.get("vector"))
            .and_then(Value::as_array);
    }
    if let Some(nested_query) = query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
    {
        return extract_knn_query_vector(nested_query);
    }
    if let Some(queries) = query
        .get("hybrid")
        .and_then(Value::as_object)
        .and_then(|hybrid| hybrid.get("queries"))
        .and_then(Value::as_array)
    {
        return queries.iter().find_map(extract_knn_query_vector);
    }
    let bool_query = query.get("bool").and_then(Value::as_object)?;
    for clause_name in ["must", "should", "filter", "must_not"] {
        if let Some(vector) = bool_query_clauses(bool_query, clause_name)
            .into_iter()
            .find_map(extract_knn_query_vector)
        {
            return Some(vector);
        }
    }
    None
}

fn lookup_mapping_property<'a>(mappings: &'a Value, field: &str) -> Option<&'a Value> {
    let mut properties = mappings.get("properties")?;
    let mut segments = field.split('.').peekable();
    while let Some(segment) = segments.next() {
        let Some(field_mapping) = properties.get(segment) else {
            return find_mapping_property_by_leaf(
                mappings.get("properties")?,
                field.rsplit('.').next()?,
            );
        };
        if segments.peek().is_none() {
            return Some(field_mapping);
        }
        let Some(next_properties) = field_mapping.get("properties") else {
            return find_mapping_property_by_leaf(
                mappings.get("properties")?,
                field.rsplit('.').next()?,
            );
        };
        properties = next_properties;
    }
    find_mapping_property_by_leaf(mappings.get("properties")?, field.rsplit('.').next()?)
}

fn find_mapping_property_by_leaf<'a>(properties: &'a Value, field: &str) -> Option<&'a Value> {
    let object = properties.as_object()?;
    if let Some(field_mapping) = object.get(field) {
        return Some(field_mapping);
    }
    object
        .values()
        .filter_map(|field_mapping| field_mapping.get("properties"))
        .find_map(|nested_properties| find_mapping_property_by_leaf(nested_properties, field))
}

fn search_sort_fields(sort: &Value) -> Option<Vec<Value>> {
    match sort {
        Value::Array(sort_fields) => {
            let mut expanded_fields = Vec::new();
            for sort_field in sort_fields {
                expand_search_sort_field(sort_field, &mut expanded_fields)?;
            }
            Some(expanded_fields)
        }
        Value::String(_) => Some(vec![sort.clone()]),
        Value::Object(_) => {
            let mut expanded_fields = Vec::new();
            expand_search_sort_field(sort, &mut expanded_fields)?;
            Some(expanded_fields)
        }
        _ => None,
    }
}

fn expand_search_sort_field(sort_field: &Value, expanded_fields: &mut Vec<Value>) -> Option<()> {
    match sort_field {
        Value::String(_) => {
            expanded_fields.push(sort_field.clone());
            Some(())
        }
        Value::Object(object) => {
            for (field_name, options) in object {
                let mut field_spec = serde_json::Map::new();
                field_spec.insert(field_name.clone(), options.clone());
                expanded_fields.push(Value::Object(field_spec));
            }
            Some(())
        }
        _ => None,
    }
}

fn apply_search_sort(hits: &mut [Value], sort: &Value) {
    let Some(sort_fields) = search_sort_fields(sort) else {
        return;
    };
    if sort_fields.is_empty() {
        return;
    }
    hits.sort_by(|left, right| {
        for field_spec in &sort_fields {
            let Some(field_name) = sort_field_name(field_spec) else {
                continue;
            };
            let ordering = compare_sort_field_values(
                left,
                right,
                field_spec,
                field_name,
                sort_field_descending(field_spec),
            );
            if ordering != std::cmp::Ordering::Equal {
                return ordering;
            }
        }
        left["_seq_no"]
            .as_i64()
            .unwrap_or_default()
            .cmp(&right["_seq_no"].as_i64().unwrap_or_default())
    });
}

fn apply_search_after(hits: Vec<Value>, sort: &Value, search_after: &[Value]) -> Vec<Value> {
    let Some(sort_fields) = search_sort_fields(sort) else {
        return hits;
    };
    if sort_fields.is_empty() || sort_fields.len() != search_after.len() {
        return hits;
    }
    hits.into_iter()
        .filter(|hit| {
            for (sort_field, after_value) in sort_fields.iter().zip(search_after.iter()) {
                let Some(field_name) = sort_field_name(sort_field) else {
                    continue;
                };
                let ordering = compare_sort_field_value_to_after(
                    hit,
                    sort_field,
                    field_name,
                    after_value,
                    sort_field_descending(sort_field),
                );
                if ordering == std::cmp::Ordering::Equal {
                    continue;
                }
                return ordering == std::cmp::Ordering::Greater;
            }
            false
        })
        .collect()
}

fn append_search_hit_sort_values(hits: &mut [Value], sort: Option<&Value>) {
    let Some(sort_fields) = sort.and_then(search_sort_fields) else {
        return;
    };
    if sort_fields.is_empty() {
        return;
    }
    for hit in hits {
        let sort_values = sort_fields
            .iter()
            .filter_map(|sort_field| {
                let field_name = sort_field_name(sort_field)?;
                Some(extract_rendered_sort_value(hit, sort_field, field_name))
            })
            .collect::<Vec<_>>();
        if let Some(hit_object) = hit.as_object_mut() {
            hit_object.insert("sort".to_string(), Value::Array(sort_values));
        }
    }
}

fn search_response_should_render_scores(body: &Value) -> bool {
    let Some(sort_fields) = body.get("sort").and_then(search_sort_fields) else {
        return true;
    };
    if sort_fields.is_empty() || body.get("track_scores") == Some(&Value::Bool(true)) {
        return true;
    }
    sort_fields
        .iter()
        .filter_map(sort_field_name)
        .any(|field_name| field_name == "_score")
}

fn sort_field_name(sort_field: &Value) -> Option<&str> {
    if let Some(field_name) = sort_field.as_str() {
        return Some(field_name);
    }
    sort_field
        .as_object()
        .and_then(|object| object.keys().next().map(String::as_str))
}

fn sort_field_descending(sort_field: &Value) -> bool {
    if sort_field.as_str() == Some("_score") {
        return true;
    }
    sort_field
        .as_object()
        .and_then(|object| object.values().next())
        .and_then(|options| {
            options
                .as_str()
                .or_else(|| options.get("order").and_then(Value::as_str))
        })
        .is_some_and(|order| order == "desc")
}

fn sort_field_missing(sort_field: &Value) -> Option<&Value> {
    sort_field
        .as_object()
        .and_then(|object| object.values().next())
        .and_then(|options| options.as_object())
        .and_then(|options| options.get("missing"))
}

fn sort_field_missing_marker(sort_field: &Value) -> Option<&str> {
    sort_field_missing(sort_field)
        .and_then(Value::as_str)
        .filter(|marker| matches!(*marker, "_first" | "_last"))
}

fn sort_field_custom_missing_value(sort_field: &Value) -> Option<&Value> {
    sort_field_missing(sort_field)
        .filter(|value| sort_field_missing_marker(sort_field).is_none() && !value.is_null())
}

fn compare_sort_field_values(
    left: &Value,
    right: &Value,
    sort_field: &Value,
    field_name: &str,
    descending: bool,
) -> std::cmp::Ordering {
    let left_value = extract_mode_sort_value(left, sort_field, field_name, descending);
    let right_value = extract_mode_sort_value(right, sort_field, field_name, descending);
    let left_missing = left_value.is_null();
    let right_missing = right_value.is_null();
    if left_missing || right_missing {
        if let Some(marker) = sort_field_missing_marker(sort_field).or_else(|| {
            sort_field_custom_missing_value(sort_field)
                .is_none()
                .then_some("_last")
        }) {
            return match (left_missing, right_missing, marker) {
                (true, true, _) => std::cmp::Ordering::Equal,
                (true, false, "_first") | (false, true, "_last") => std::cmp::Ordering::Less,
                (true, false, "_last") | (false, true, "_first") => std::cmp::Ordering::Greater,
                _ => std::cmp::Ordering::Equal,
            };
        }
    }
    let left_value = if left_missing {
        sort_field_custom_missing_value(sort_field).unwrap_or(&left_value)
    } else {
        &left_value
    };
    let right_value = if right_missing {
        sort_field_custom_missing_value(sort_field).unwrap_or(&right_value)
    } else {
        &right_value
    };
    let ordering = compare_json_scalars(left_value, right_value);
    if descending {
        ordering.reverse()
    } else {
        ordering
    }
}

fn compare_sort_field_value_to_after(
    hit: &Value,
    sort_field: &Value,
    field_name: &str,
    after_value: &Value,
    descending: bool,
) -> std::cmp::Ordering {
    let sort_value = extract_mode_sort_value(hit, sort_field, field_name, descending);
    let sort_missing = sort_value.is_null();
    if let Some(marker) = sort_field_missing_marker(sort_field).or_else(|| {
        sort_field_custom_missing_value(sort_field)
            .is_none()
            .then_some("_last")
    }) {
        if sort_missing && after_value.is_null() {
            return std::cmp::Ordering::Equal;
        }
        if sort_missing {
            return if marker == "_first" {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Greater
            };
        }
        if after_value.is_null() {
            return if marker == "_first" {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Less
            };
        }
    }
    let sort_value = if sort_missing {
        sort_field_custom_missing_value(sort_field).unwrap_or(&sort_value)
    } else {
        &sort_value
    };
    let ordering = compare_json_scalars(sort_value, after_value);
    if descending {
        ordering.reverse()
    } else {
        ordering
    }
}

fn extract_rendered_sort_value(hit: &Value, sort_field: &Value, field_name: &str) -> Value {
    let value = extract_mode_sort_value(
        hit,
        sort_field,
        field_name,
        sort_field_descending(sort_field),
    );
    if value.is_null() {
        if let Some(custom_missing) = sort_field_custom_missing_value(sort_field) {
            return custom_missing.clone();
        }
    }
    value
}

fn extract_mode_sort_value(
    hit: &Value,
    sort_field: &Value,
    field_name: &str,
    descending: bool,
) -> Value {
    let value = extract_sort_value(hit, field_name);
    let Some(values) = value.as_array() else {
        return value;
    };
    if values.is_empty() {
        return Value::Null;
    }
    let mode = sort_field_mode(sort_field).unwrap_or(if descending { "max" } else { "min" });
    reduce_sort_values_by_mode(values, mode).unwrap_or(Value::Null)
}

fn sort_field_mode(sort_field: &Value) -> Option<&str> {
    sort_field
        .as_object()
        .and_then(|object| object.values().next())
        .and_then(|options| options.as_object())
        .and_then(|options| options.get("mode"))
        .and_then(Value::as_str)
}

fn sort_field_unmapped_type(sort_field: &Value) -> Option<&str> {
    sort_field
        .as_object()
        .and_then(|object| object.values().next())
        .and_then(|options| options.as_object())
        .and_then(|options| options.get("unmapped_type"))
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
}

fn sort_mode_is_supported(mode: &str) -> bool {
    matches!(
        mode.to_ascii_lowercase().as_str(),
        "min" | "max" | "sum" | "avg" | "median"
    )
}

fn sort_mode_numeric_only(mode: &str) -> bool {
    matches!(mode.to_ascii_lowercase().as_str(), "sum" | "avg" | "median")
}

fn reduce_sort_values_by_mode(values: &[Value], mode: &str) -> Option<Value> {
    match mode.to_ascii_lowercase().as_str() {
        "min" => values
            .iter()
            .min_by(|left, right| compare_json_scalars(left, right))
            .cloned(),
        "max" => values
            .iter()
            .max_by(|left, right| compare_json_scalars(left, right))
            .cloned(),
        "sum" => Some(Value::from(
            values.iter().filter_map(Value::as_f64).sum::<f64>(),
        )),
        "avg" => {
            let numbers = values.iter().filter_map(Value::as_f64).collect::<Vec<_>>();
            if numbers.is_empty() {
                return None;
            }
            Some(Value::from(
                numbers.iter().sum::<f64>() / numbers.len() as f64,
            ))
        }
        "median" => {
            let mut numbers = values.iter().filter_map(Value::as_f64).collect::<Vec<_>>();
            if numbers.is_empty() {
                return None;
            }
            numbers.sort_by(|left, right| {
                left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal)
            });
            let middle = numbers.len() / 2;
            if numbers.len() % 2 == 0 {
                Some(Value::from((numbers[middle - 1] + numbers[middle]) / 2.0))
            } else {
                Some(Value::from(numbers[middle]))
            }
        }
        _ => None,
    }
}

fn parse_runtime_mapping_script_source(source: &str) -> Option<String> {
    for (prefix, suffix_marker) in [
        ("emit(doc['", "'].value)"),
        ("emit(doc[\"", "\"].value)"),
        ("emit(params._source['", "'])"),
        ("emit(params._source[\"", "\"])"),
    ] {
        if let Some(field_expr) = source.trim().strip_prefix(prefix) {
            let (field_name, suffix) = field_expr.split_once(suffix_marker)?;
            if suffix.is_empty() && !field_name.is_empty() {
                return Some(field_name.to_string());
            }
        }
    }
    None
}

fn parse_script_field_source(source: &str) -> Option<String> {
    let source = source.trim();
    let expression = source
        .strip_prefix("emit(")
        .and_then(|remaining| remaining.strip_suffix(')'))
        .unwrap_or(source)
        .trim();
    for (prefix, suffix_marker) in [
        ("doc['", "'].value"),
        ("doc[\"", "\"].value"),
        ("params._source['", "']"),
        ("params._source[\"", "\"]"),
    ] {
        if let Some(field_expr) = expression.strip_prefix(prefix) {
            let (field_name, suffix) = field_expr.split_once(suffix_marker)?;
            if suffix.is_empty() && !field_name.is_empty() {
                return Some(field_name.to_string());
            }
        }
    }
    None
}

fn apply_request_scoped_fields_to_source(source: &Value, body: &Value) -> Value {
    let effective =
        apply_request_scoped_field_definitions_to_source(source, body.get("runtime_mappings"));
    apply_request_scoped_field_definitions_to_source(&effective, body.get("derived"))
}

fn apply_request_scoped_field_definitions_to_source(
    source: &Value,
    definitions: Option<&Value>,
) -> Value {
    let Some(source_object) = source.as_object() else {
        return source.clone();
    };
    let mut effective = source_object.clone();
    let Some(mappings) = definitions.and_then(Value::as_object) else {
        return Value::Object(effective);
    };
    for (runtime_field, definition) in mappings {
        let Some(definition_object) = definition.as_object() else {
            continue;
        };
        let Some(script_source) = request_scoped_field_script_source(definition_object) else {
            continue;
        };
        let Some(source_field) = parse_runtime_mapping_script_source(script_source) else {
            continue;
        };
        if let Some(value) = source_object.get(&source_field) {
            effective.insert(runtime_field.clone(), value.clone());
        }
    }
    Value::Object(effective)
}

fn request_scoped_field_script_source(
    definition_object: &serde_json::Map<String, Value>,
) -> Option<&str> {
    match definition_object.get("script")? {
        Value::String(source) => Some(source.as_str()),
        Value::Object(script) => {
            if script.keys().any(|key| key != "source") {
                return None;
            }
            script.get("source").and_then(Value::as_str)
        }
        _ => None,
    }
}

fn script_field_script_source(definition_object: &serde_json::Map<String, Value>) -> Option<&str> {
    match definition_object.get("script")? {
        Value::String(source) => Some(source.as_str()),
        Value::Object(script) => {
            if script.keys().any(|key| key != "source") {
                return None;
            }
            script.get("source").and_then(Value::as_str)
        }
        _ => None,
    }
}

fn normalize_docvalue_field_value(
    mapping: &serde_json::Map<String, Value>,
    value: &Value,
    format: Option<&str>,
) -> Value {
    match mapping.get("type").and_then(Value::as_str) {
        Some("date") => normalize_docvalue_date_field_value(value, format),
        Some("long") | Some("integer") | Some("short") | Some("byte") | Some("double")
        | Some("float") => value.clone(),
        Some("keyword") | Some("boolean") => value.clone(),
        _ => value.clone(),
    }
}

fn normalize_docvalue_date_field_value(value: &Value, format: Option<&str>) -> Value {
    let Some(raw) = value.as_str() else {
        return Value::String(String::new());
    };
    if format == Some("epoch_millis") {
        return parse_iso_utc_millis(raw)
            .map(|millis| Value::String(millis.to_string()))
            .unwrap_or_else(|| Value::String(raw.to_string()));
    }
    Value::String(if raw.ends_with('Z') && !raw.contains('.') {
        raw.trim_end_matches('Z').to_string() + ".000Z"
    } else {
        raw.to_string()
    })
}

fn parse_iso_utc_millis(raw: &str) -> Option<i64> {
    let trimmed = raw.strip_suffix('Z')?;
    let (date, time) = trimmed.split_once('T')?;
    let mut date_parts = date.split('-');
    let year = date_parts.next()?.parse::<i32>().ok()?;
    let month = date_parts.next()?.parse::<u32>().ok()?;
    let day = date_parts.next()?.parse::<u32>().ok()?;
    if date_parts.next().is_some() {
        return None;
    }
    let mut time_parts = time.split(':');
    let hour = time_parts.next()?.parse::<i64>().ok()?;
    let minute = time_parts.next()?.parse::<i64>().ok()?;
    let second_fraction = time_parts.next()?;
    if time_parts.next().is_some() {
        return None;
    }
    let (second_raw, fraction_raw) = second_fraction
        .split_once('.')
        .map(|(second, fraction)| (second, Some(fraction)))
        .unwrap_or((second_fraction, None));
    let second = second_raw.parse::<i64>().ok()?;
    let millis = fraction_raw
        .map(|fraction| {
            let digits = fraction.chars().take(3).collect::<String>();
            format!("{digits:0<3}").parse::<i64>().ok()
        })
        .unwrap_or(Some(0))?;
    if !(0..=23).contains(&hour) || !(0..=59).contains(&minute) || !(0..=59).contains(&second) {
        return None;
    }
    let days = days_from_civil(year, month, day)?;
    Some((((days * 24 + hour) * 60 + minute) * 60 + second) * 1000 + millis)
}

fn search_hit_source_string<'a>(hit: &'a Value, field: &str) -> &'a str {
    hit.get("_source")
        .and_then(|source| lookup_query_field_value(source, field))
        .and_then(Value::as_str)
        .unwrap_or_default()
}

fn apply_search_rescore(hits: &mut [Value], rescore: &Value) {
    let Some(rescore_object) = rescore.as_object() else {
        return;
    };
    let window_size = rescore_object
        .get("window_size")
        .and_then(Value::as_u64)
        .unwrap_or(0) as usize;
    let Some(query_object) = rescore_object.get("query").and_then(Value::as_object) else {
        return;
    };
    let Some(rescore_query) = query_object.get("rescore_query") else {
        return;
    };
    let query_weight = query_object
        .get("query_weight")
        .and_then(Value::as_f64)
        .unwrap_or(1.0);
    let rescore_weight = query_object
        .get("rescore_query_weight")
        .and_then(Value::as_f64)
        .unwrap_or(1.0);
    let window = window_size.min(hits.len());
    for hit in &mut hits[..window] {
        let Some(hit_object) = hit.as_object_mut() else {
            continue;
        };
        let base_score = hit_object
            .get("_score")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);
        let Some(source) = hit_object.get("_source") else {
            continue;
        };
        let doc_id = hit_object
            .get("_id")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let rescore_score = evaluate_search_query_source(source, doc_id, rescore_query)
            .map(|(matched, score)| if matched { score } else { 0.0 })
            .unwrap_or(0.0);
        hit_object.insert(
            "_score".to_string(),
            Value::from(base_score * query_weight + rescore_score * rescore_weight),
        );
    }
    hits[..window].sort_by(|left, right| {
        let left_score = left["_score"].as_f64().unwrap_or(0.0);
        let right_score = right["_score"].as_f64().unwrap_or(0.0);
        right_score
            .partial_cmp(&left_score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    hits[window..].sort_by(|left, right| {
        search_hit_source_string(left, "ts")
            .cmp(&search_hit_source_string(right, "ts"))
            .then_with(|| {
                left["_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right["_id"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                left["_seq_no"]
                    .as_i64()
                    .unwrap_or(i64::MAX)
                    .cmp(&right["_seq_no"].as_i64().unwrap_or(i64::MAX))
            })
    });
}

fn apply_search_collapse(hits: Vec<Value>, collapse: &Value) -> Vec<Value> {
    let Some(field) = collapse
        .as_object()
        .and_then(|object| object.get("field"))
        .and_then(Value::as_str)
    else {
        return hits;
    };
    let mut seen = BTreeSet::new();
    let mut collapsed = Vec::new();
    for hit in hits {
        let key = extract_sort_value(&hit, field).to_string();
        if seen.insert(key) {
            collapsed.push(hit);
        }
    }
    collapsed
}

fn extract_sort_value(hit: &Value, field_name: &str) -> Value {
    if field_name == "_score" {
        return hit.get("_score").cloned().unwrap_or(Value::Null);
    }
    if field_name == "_shard_doc" {
        return hit
            .get("_shard_doc")
            .or_else(|| hit.get("_seq_no"))
            .cloned()
            .unwrap_or(Value::Null);
    }
    hit.get("_source")
        .and_then(|source| source.get(field_name))
        .cloned()
        .unwrap_or(Value::Null)
}

fn compare_json_scalars(left: &Value, right: &Value) -> std::cmp::Ordering {
    match (left.as_f64(), right.as_f64()) {
        (Some(left), Some(right)) => left
            .partial_cmp(&right)
            .unwrap_or(std::cmp::Ordering::Equal),
        _ => left
            .as_str()
            .unwrap_or_default()
            .cmp(right.as_str().unwrap_or_default()),
    }
}

fn parse_search_timeout_millis(timeout: &str) -> Option<u64> {
    if let Some(value) = timeout.strip_suffix("ms") {
        return value.parse::<u64>().ok();
    }
    if let Some(value) = timeout.strip_suffix('s') {
        return value.parse::<u64>().ok().map(|seconds| seconds * 1_000);
    }
    None
}

fn extract_geo_query_field(query: &Value) -> Option<String> {
    if let Some(field) = query
        .get("geo_distance")
        .and_then(Value::as_object)
        .and_then(|spec| {
            spec.iter()
                .find(|(key, _)| key.as_str() != "distance")
                .map(|(key, _)| key.clone())
        })
    {
        return Some(field);
    }
    if let Some(field) = query
        .get("geo_bounding_box")
        .and_then(Value::as_object)
        .and_then(|spec| {
            spec.iter()
                .find(|(key, _)| {
                    !matches!(
                        key.as_str(),
                        "ignore_unmapped" | "validation_method" | "type" | "_name" | "boost"
                    )
                })
                .map(|(key, _)| key.clone())
        })
    {
        return Some(field);
    }
    if let Some(field) = query
        .get("geo_polygon")
        .and_then(Value::as_object)
        .and_then(|spec| {
            spec.iter()
                .find(|(key, _)| {
                    !matches!(
                        key.as_str(),
                        "ignore_unmapped" | "validation_method" | "_name" | "boost"
                    )
                })
                .map(|(key, _)| key.clone())
        })
    {
        return Some(field);
    }
    query
        .get("geo_shape")
        .and_then(Value::as_object)
        .and_then(|spec| {
            spec.iter()
                .find(|(key, _)| !matches!(key.as_str(), "ignore_unmapped" | "_name" | "boost"))
                .map(|(key, _)| key.clone())
        })
}

fn compute_can_match_skipped_shards(
    query: &Value,
    pre_filter_shard_size: Option<&String>,
    total_shards: usize,
) -> usize {
    if pre_filter_shard_size.is_none() || total_shards <= 1 {
        return 0;
    }
    if query.get("match_none").is_some() || query.get("range").is_some() {
        return total_shards.saturating_sub(1);
    }
    0
}

fn extract_knn_limit(query: &Value) -> Option<usize> {
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        let (_, spec) = knn.iter().next()?;
        return spec
            .get("k")
            .and_then(Value::as_u64)
            .map(|value| value as usize);
    }
    if let Some(nested_query) = query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
    {
        return extract_knn_limit(nested_query);
    }
    if let Some(queries) = query
        .get("hybrid")
        .and_then(Value::as_object)
        .and_then(|hybrid| hybrid.get("queries"))
        .and_then(Value::as_array)
    {
        for clause in queries {
            if let Some(limit) = extract_knn_limit(clause) {
                return Some(limit);
            }
        }
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        let shoulds = bool_query_clauses(bool_query, "should");
        if !shoulds.is_empty() {
            if bool_query.get("must").is_some() || bool_query.get("filter").is_some() {
                return None;
            }
            let required = bool_query
                .get("minimum_should_match")
                .and_then(Value::as_u64)
                .map(|value| value as usize)
                .unwrap_or(1);
            if required == 0 {
                return None;
            }
            let mut limits = Vec::new();
            for clause in shoulds {
                let Some(limit) = extract_knn_limit(clause) else {
                    return None;
                };
                limits.push(limit);
            }
            return if limits.len() == 1 && limits.len() >= required {
                limits.into_iter().next()
            } else {
                None
            };
        }
        let mut limits = Vec::new();
        for clause_name in ["must", "should", "filter"] {
            for clause in bool_query_clauses(bool_query, clause_name) {
                let Some(limit) = extract_knn_limit(clause) else {
                    return None;
                };
                limits.push(limit);
            }
        }
        return if limits.len() == 1 {
            limits.into_iter().next()
        } else {
            None
        };
    }
    None
}

fn query_uses_pure_knn_candidate_path(query: &Value) -> bool {
    if query.get("knn").and_then(Value::as_object).is_some() {
        return true;
    }
    if let Some(nested_query) = query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
    {
        return query_uses_pure_knn_candidate_path(nested_query);
    }
    let Some(bool_query) = query.get("bool").and_then(Value::as_object) else {
        return false;
    };
    let shoulds = bool_query_clauses(bool_query, "should");
    if !shoulds.is_empty() {
        if bool_query.get("must").is_some() || bool_query.get("filter").is_some() {
            return false;
        }
        let required = bool_query
            .get("minimum_should_match")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(1)
            .max(1);
        let pure_should_candidates = shoulds
            .iter()
            .filter(|clause| query_uses_pure_knn_candidate_path(clause))
            .count();
        return pure_should_candidates == 1
            && pure_should_candidates == shoulds.len()
            && pure_should_candidates >= required;
    }
    let mut positive_candidate_clauses = 0usize;
    for clause_name in ["must", "filter"] {
        for clause in bool_query_clauses(bool_query, clause_name) {
            if query_uses_pure_knn_candidate_path(clause) {
                positive_candidate_clauses += 1;
            } else {
                return false;
            }
        }
    }
    positive_candidate_clauses == 1
}

fn extract_knn_ignore_unmapped(query: &Value) -> bool {
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        if let Some((_, spec)) = knn.iter().next() {
            return spec
                .get("ignore_unmapped")
                .and_then(Value::as_bool)
                .unwrap_or(false);
        }
    }
    if let Some(nested_query) = query
        .get("nested")
        .and_then(Value::as_object)
        .and_then(|nested| nested.get("query"))
    {
        return extract_knn_ignore_unmapped(nested_query);
    }
    if let Some(queries) = query
        .get("hybrid")
        .and_then(Value::as_object)
        .and_then(|hybrid| hybrid.get("queries"))
        .and_then(Value::as_array)
    {
        for clause in queries {
            if extract_knn_ignore_unmapped(clause) {
                return true;
            }
        }
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        for clause_name in ["must", "should", "filter", "must_not"] {
            if let Some(clauses) = bool_query.get(clause_name).and_then(Value::as_array) {
                for clause in clauses {
                    if extract_knn_ignore_unmapped(clause) {
                        return true;
                    }
                }
            }
        }
    }
    false
}

fn build_missing_snapshot_repository_response(repository: &str) -> RestResponse {
    RestResponse::json(
        404,
        serde_json::json!({
            "error": {
                "type": "repository_missing_exception",
                "reason": format!("[{repository}] missing"),
                "root_cause": [
                    {
                        "type": "repository_missing_exception",
                        "reason": format!("[{repository}] missing"),
                    }
                ]
            },
            "status": 404
        }),
    )
}

fn validate_fs_snapshot_repository_location(
    repository: &str,
    settings: &Value,
) -> Result<(), RestResponse> {
    let Some(allowed_base) = env::var_os("SNAPSHOT_REPOSITORY_BASE_DIR") else {
        return Ok(());
    };
    let Some(location) = settings.get("location").and_then(Value::as_str) else {
        return Ok(());
    };
    let allowed_base = PathBuf::from(allowed_base);
    let location_path = Path::new(location);
    let candidate = if location_path.is_absolute() {
        location_path.to_path_buf()
    } else {
        allowed_base.join(location_path)
    };
    if candidate.starts_with(&allowed_base) {
        return Ok(());
    }
    Err(RestResponse::opensearch_error(
        500,
        "repository_exception",
        format!(
            "[{repository}] location [{location}] doesn't match any of the locations specified by path.repo because this node is configured with [{}]",
            allowed_base.display()
        ),
    ))
}

