fn parse_search_indices_boosts(indices_boost: Option<&Value>) -> Vec<(String, f64)> {
    match indices_boost {
        Some(Value::Object(boosts)) => boosts
            .iter()
            .filter_map(|(index, boost)| Some((index.clone(), boost.as_f64()?)))
            .collect(),
        Some(Value::Array(boosts)) => boosts
            .iter()
            .filter_map(|boost| {
                let object = boost.as_object()?;
                let (index, value) = object.iter().next()?;
                Some((index.clone(), value.as_f64()?))
            })
            .collect(),
        _ => Vec::new(),
    }
}

fn search_index_boost_for(index: &str, boosts: &[(String, f64)]) -> f64 {
    boosts
        .iter()
        .find_map(|(pattern, boost)| {
            if pattern == index || wildcard_match(pattern, index) {
                Some(*boost)
            } else {
                None
            }
        })
        .unwrap_or(1.0)
}

fn stringify_leaf_scalars(value: &Value) -> Value {
    match value {
        Value::Object(object) => Value::Object(
            object
                .iter()
                .map(|(key, value)| (key.clone(), stringify_leaf_scalars(value)))
                .collect(),
        ),
        Value::Array(values) => Value::Array(values.iter().map(stringify_leaf_scalars).collect()),
        Value::Number(number) => Value::String(number.to_string()),
        Value::Bool(boolean) => Value::String(boolean.to_string()),
        _ => value.clone(),
    }
}

fn merge_object_with_null_reset(base: &mut Value, update: &Value) {
    let Some(base_object) = base.as_object_mut() else {
        *base = update.clone();
        return;
    };
    let Some(update_object) = update.as_object() else {
        *base = update.clone();
        return;
    };
    for (key, value) in update_object {
        if value.is_null() {
            base_object.remove(key);
            continue;
        }
        match base_object.get_mut(key) {
            Some(existing) if existing.is_object() && value.is_object() => {
                merge_object_with_null_reset(existing, value);
            }
            _ => {
                base_object.insert(key.clone(), value.clone());
            }
        }
    }
}

fn build_search_aggregations(
    aggregations: Option<&Value>,
    hits: &[Value],
    global_hits: &[Value],
) -> Result<Option<Value>, RestResponse> {
    let Some(aggregations) = aggregations.and_then(Value::as_object) else {
        return Ok(None);
    };
    let mut result = serde_json::Map::new();
    let mut terms_doc_counts: std::collections::BTreeMap<String, Vec<(String, u64)>> =
        std::collections::BTreeMap::new();
    for (name, aggregation) in aggregations {
        let Some(aggregation_object) = aggregation.as_object() else {
            continue;
        };
        if aggregation_object
            .get("global")
            .and_then(Value::as_object)
            .is_some()
        {
            let mut global_value = serde_json::Map::new();
            global_value.insert(
                "doc_count".to_string(),
                Value::from(global_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) = build_search_aggregations(nested_aggs, global_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        global_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(global_value));
            continue;
        }
        if let Some(nested) = aggregation_object.get("nested").and_then(Value::as_object) {
            let path = nested
                .get("path")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if path.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [nested.path]",
                ));
            }
            let nested_hits = collect_nested_child_hits(hits, path);
            let mut nested_value = serde_json::Map::new();
            nested_value.insert(
                "doc_count".to_string(),
                Value::from(nested_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested_aggregations) =
                build_search_aggregations(nested_aggs, &nested_hits, &nested_hits)?
            {
                if let Some(nested_object) = nested_aggregations.as_object() {
                    for (nested_name, nested_value_inner) in nested_object {
                        nested_value.insert(nested_name.clone(), nested_value_inner.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(nested_value));
            continue;
        }
        if let Some(reverse_nested) = aggregation_object
            .get("reverse_nested")
            .and_then(Value::as_object)
        {
            if reverse_nested
                .get("path")
                .and_then(Value::as_str)
                .is_some_and(|path| !path.is_empty())
            {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [reverse_nested.path]",
                ));
            }
            let parent_hits = collect_reverse_nested_parent_hits(hits);
            let mut reverse_nested_value = serde_json::Map::new();
            reverse_nested_value.insert(
                "doc_count".to_string(),
                Value::from(parent_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) = build_search_aggregations(nested_aggs, &parent_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        reverse_nested_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(reverse_nested_value));
            continue;
        }
        if let Some(sampler) = aggregation_object.get("sampler").and_then(Value::as_object) {
            let shard_size = sampler
                .get("shard_size")
                .and_then(Value::as_u64)
                .unwrap_or(100) as usize;
            let sampled_hits = hits.iter().take(shard_size).cloned().collect::<Vec<_>>();
            let mut sampled_value = serde_json::Map::new();
            sampled_value.insert(
                "doc_count".to_string(),
                Value::from(sampled_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) =
                build_search_aggregations(nested_aggs, &sampled_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        sampled_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(sampled_value));
            continue;
        }
        if let Some(diversified_sampler) = aggregation_object
            .get("diversified_sampler")
            .and_then(Value::as_object)
        {
            let field = diversified_sampler
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if field.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [diversified_sampler.field]",
                ));
            }
            let shard_size = diversified_sampler
                .get("shard_size")
                .and_then(Value::as_u64)
                .unwrap_or(100) as usize;
            let max_docs_per_value = diversified_sampler
                .get("max_docs_per_value")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            let mut value_counts = std::collections::BTreeMap::<String, u64>::new();
            let mut sampled_hits = Vec::new();
            for hit in hits {
                if sampled_hits.len() >= shard_size {
                    break;
                }
                let Some(value) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .filter(|value| !value.is_null())
                else {
                    continue;
                };
                let value_key = aggregation_bucket_sort_key(value);
                let current_count = value_counts.get(&value_key).copied().unwrap_or(0);
                if current_count >= max_docs_per_value {
                    continue;
                }
                value_counts.insert(value_key, current_count + 1);
                sampled_hits.push(hit.clone());
            }
            let mut sampled_value = serde_json::Map::new();
            sampled_value.insert(
                "doc_count".to_string(),
                Value::from(sampled_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) =
                build_search_aggregations(nested_aggs, &sampled_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        sampled_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(sampled_value));
            continue;
        }
        if let Some(terms) = aggregation_object.get("terms").and_then(Value::as_object) {
            let field = terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut counts = std::collections::BTreeMap::new();
            for hit in hits {
                if let Some(key) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .and_then(Value::as_str)
                {
                    *counts.entry(key.to_string()).or_insert(0_u64) += 1;
                }
            }
            let mut buckets: Vec<(String, u64)> = counts.into_iter().collect();
            let order = terms.get("order").and_then(Value::as_object);
            let order_key = order
                .and_then(|value| value.iter().next())
                .map(|(key, direction)| (key.as_str(), direction.as_str().unwrap_or("desc")));
            match order_key {
                Some(("_count", "asc")) => buckets
                    .sort_by(|left, right| left.1.cmp(&right.1).then_with(|| left.0.cmp(&right.0))),
                Some(("_count", _)) | None => buckets
                    .sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0))),
                Some(("_key", "desc")) => buckets.sort_by(|left, right| right.0.cmp(&left.0)),
                Some(("_key", _)) => buckets.sort_by(|left, right| left.0.cmp(&right.0)),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [terms.order]",
                    ))
                }
            }
            terms_doc_counts.insert(name.clone(), buckets.clone());
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets
                        .into_iter()
                        .map(|(key, doc_count)| serde_json::json!({"key": key, "doc_count": doc_count}))
                        .collect::<Vec<_>>()
                }),
            );
            continue;
        }
        if let Some(rare_terms) = aggregation_object
            .get("rare_terms")
            .and_then(Value::as_object)
        {
            let field = rare_terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let max_doc_count = rare_terms
                .get("max_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            if max_doc_count == 0 || max_doc_count > 100 {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [rare_terms.max_doc_count]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<String, (Value, u64)>::new();
            for hit in hits {
                let Some(key) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .filter(|value| !value.is_null())
                else {
                    continue;
                };
                let sort_key = aggregation_bucket_sort_key(key);
                let entry = counts.entry(sort_key).or_insert_with(|| (key.clone(), 0));
                entry.1 += 1;
            }
            let mut buckets = counts
                .into_iter()
                .filter_map(|(_, (key, doc_count))| {
                    (doc_count <= max_doc_count).then_some((key, doc_count))
                })
                .collect::<Vec<_>>();
            buckets.sort_by(|left, right| {
                left.1.cmp(&right.1).then_with(|| {
                    aggregation_bucket_sort_key(&left.0).cmp(&aggregation_bucket_sort_key(&right.0))
                })
            });
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets
                        .into_iter()
                        .map(|(key, doc_count)| serde_json::json!({"key": key, "doc_count": doc_count}))
                        .collect::<Vec<_>>()
                }),
            );
            continue;
        }
        if let Some(multi_terms) = aggregation_object
            .get("multi_terms")
            .and_then(Value::as_object)
        {
            let fields = multi_terms
                .get("terms")
                .and_then(Value::as_array)
                .map(|terms| {
                    terms
                        .iter()
                        .filter_map(|term| {
                            term.get("field")
                                .and_then(Value::as_str)
                                .map(str::to_string)
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if fields.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [multi_terms.terms]",
                ));
            }
            let min_doc_count = multi_terms
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            let size = multi_terms
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let mut counts = std::collections::BTreeMap::<String, (Vec<Value>, u64)>::new();
            for hit in hits {
                let Some(source) = hit.get("_source") else {
                    continue;
                };
                let mut key_values = Vec::new();
                let mut sort_parts = Vec::new();
                for field in &fields {
                    let Some(value) =
                        lookup_query_field_value(source, field).filter(|value| !value.is_null())
                    else {
                        key_values.clear();
                        break;
                    };
                    key_values.push(value.clone());
                    sort_parts.push(aggregation_bucket_sort_key(value));
                }
                if key_values.is_empty() {
                    continue;
                }
                let sort_key = sort_parts.join("\u{1f}");
                let entry = counts.entry(sort_key).or_insert_with(|| (key_values, 0));
                entry.1 += 1;
            }
            let mut buckets = counts
                .into_iter()
                .filter_map(|(_, (key, doc_count))| {
                    (doc_count >= min_doc_count).then_some((key, doc_count))
                })
                .collect::<Vec<_>>();
            let order = multi_terms.get("order").and_then(Value::as_object);
            let order_key = order
                .and_then(|value| value.iter().next())
                .map(|(key, direction)| (key.as_str(), direction.as_str().unwrap_or("desc")));
            match order_key {
                Some(("_count", "asc")) => buckets.sort_by(|left, right| {
                    left.1.cmp(&right.1).then_with(|| {
                        aggregation_multi_terms_sort_key(&left.0)
                            .cmp(&aggregation_multi_terms_sort_key(&right.0))
                    })
                }),
                Some(("_count", _)) | None => buckets.sort_by(|left, right| {
                    right.1.cmp(&left.1).then_with(|| {
                        aggregation_multi_terms_sort_key(&left.0)
                            .cmp(&aggregation_multi_terms_sort_key(&right.0))
                    })
                }),
                Some(("_key", "desc")) => buckets.sort_by(|left, right| {
                    aggregation_multi_terms_sort_key(&right.0)
                        .cmp(&aggregation_multi_terms_sort_key(&left.0))
                }),
                Some(("_key", _)) => buckets.sort_by(|left, right| {
                    aggregation_multi_terms_sort_key(&left.0)
                        .cmp(&aggregation_multi_terms_sort_key(&right.0))
                }),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [multi_terms.order]",
                    ))
                }
            }
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets
                        .into_iter()
                        .take(size)
                        .map(|(key, doc_count)| serde_json::json!({"key": key, "doc_count": doc_count}))
                        .collect::<Vec<_>>()
                }),
            );
            continue;
        }
        if let Some((metric_name, metric_body)) =
            first_supported_metric_aggregation(aggregation_object)
        {
            let field = metric_body
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let values: Vec<f64> = hits
                .iter()
                .filter_map(|hit| {
                    hit.get("_source")
                        .and_then(|source| source.get(field))
                        .and_then(Value::as_f64)
                })
                .collect();
            let value = match metric_name {
                "min" => values.iter().copied().reduce(f64::min).unwrap_or(0.0),
                "max" => values.iter().copied().reduce(f64::max).unwrap_or(0.0),
                "sum" => values.iter().sum(),
                "avg" => {
                    if values.is_empty() {
                        0.0
                    } else {
                        values.iter().sum::<f64>() / values.len() as f64
                    }
                }
                "value_count" => values.len() as f64,
                "stats" => {
                    result.insert(
                        name.clone(),
                        serde_json::json!({
                            "count": values.len(),
                            "min": values.iter().copied().reduce(f64::min).unwrap_or(0.0),
                            "max": values.iter().copied().reduce(f64::max).unwrap_or(0.0),
                            "avg": if values.is_empty() { 0.0 } else { values.iter().sum::<f64>() / values.len() as f64 },
                            "sum": values.iter().sum::<f64>(),
                        }),
                    );
                    continue;
                }
                _ => 0.0,
            };
            result.insert(name.clone(), serde_json::json!({ "value": value }));
            continue;
        }
        if let Some(filter) = aggregation_object.get("filter") {
            let doc_count = hits
                .iter()
                .filter(|hit| hit_matches_query(hit, filter))
                .count() as u64;
            result.insert(name.clone(), serde_json::json!({ "doc_count": doc_count }));
            continue;
        }
        if let Some(adjacency_matrix) = aggregation_object
            .get("adjacency_matrix")
            .and_then(Value::as_object)
        {
            let filters = adjacency_matrix
                .get("filters")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_default();
            if filters.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [adjacency_matrix.filters]",
                ));
            }
            let separator = adjacency_matrix
                .get("separator")
                .and_then(Value::as_str)
                .unwrap_or("&");
            let show_only_intersecting = adjacency_matrix
                .get("show_only_intersecting")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let mut filter_entries = filters.into_iter().collect::<Vec<_>>();
            filter_entries.sort_by(|left, right| left.0.cmp(&right.0));
            let mut buckets = Vec::new();
            if !show_only_intersecting {
                for (bucket_name, filter) in &filter_entries {
                    let doc_count = hits
                        .iter()
                        .filter(|hit| hit_matches_query(hit, filter))
                        .count() as u64;
                    if doc_count > 0 {
                        buckets.push(serde_json::json!({
                            "key": bucket_name,
                            "doc_count": doc_count,
                        }));
                    }
                }
            }
            for left_index in 0..filter_entries.len() {
                for right_index in (left_index + 1)..filter_entries.len() {
                    let (left_name, left_filter) = &filter_entries[left_index];
                    let (right_name, right_filter) = &filter_entries[right_index];
                    let doc_count = hits
                        .iter()
                        .filter(|hit| {
                            hit_matches_query(hit, left_filter)
                                && hit_matches_query(hit, right_filter)
                        })
                        .count() as u64;
                    if doc_count > 0 {
                        buckets.push(serde_json::json!({
                            "key": format!("{left_name}{separator}{right_name}"),
                            "doc_count": doc_count,
                        }));
                    }
                }
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(filters) = aggregation_object
            .get("filters")
            .and_then(|value| value.get("filters"))
            .and_then(Value::as_object)
        {
            let mut buckets = serde_json::Map::new();
            for (bucket_name, filter) in filters {
                let doc_count = hits
                    .iter()
                    .filter(|hit| hit_matches_query(hit, filter))
                    .count() as u64;
                buckets.insert(
                    bucket_name.clone(),
                    serde_json::json!({ "doc_count": doc_count }),
                );
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(top_hits) = aggregation_object
            .get("top_hits")
            .and_then(Value::as_object)
        {
            let mut top_rows = hits.to_vec();
            apply_search_sort(&mut top_rows, top_hits.get("sort").unwrap_or(&Value::Null));
            let size = top_hits.get("size").and_then(Value::as_u64).unwrap_or(3) as usize;
            let selected: Vec<Value> = top_rows.into_iter().take(size).collect();
            result.insert(
                name.clone(),
                serde_json::json!({
                    "hits": {
                        "total": { "value": hits.len() },
                        "hits": selected
                    }
                }),
            );
            continue;
        }
        if let Some(composite) = aggregation_object
            .get("composite")
            .and_then(Value::as_object)
        {
            let sources = composite
                .get("sources")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut counts = std::collections::BTreeMap::<String, (Value, u64)>::new();
            for hit in hits {
                let mut key_object = serde_json::Map::new();
                for source in &sources {
                    if let Some(source_object) = source.as_object() {
                        for (name, spec) in source_object {
                            let field = spec
                                .get("terms")
                                .and_then(|terms| terms.get("field"))
                                .and_then(Value::as_str)
                                .unwrap_or_default();
                            key_object.insert(
                                name.clone(),
                                hit.get("_source")
                                    .and_then(|source| source.get(field))
                                    .cloned()
                                    .unwrap_or(Value::Null),
                            );
                        }
                    }
                }
                let key_value = Value::Object(key_object.clone());
                let encoded = serde_json::to_string(&key_value).unwrap_or_default();
                let entry = counts.entry(encoded).or_insert((key_value, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_values()
                .map(|(key, doc_count)| serde_json::json!({ "key": key, "doc_count": doc_count }))
                .collect::<Vec<_>>();
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(date_histogram) = aggregation_object
            .get("date_histogram")
            .and_then(Value::as_object)
        {
            let field = date_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let interval = date_histogram
                .get("calendar_interval")
                .or_else(|| date_histogram.get("fixed_interval"))
                .and_then(Value::as_str)
                .unwrap_or_default();
            if interval != "day" {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation [date_histogram]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
            for hit in hits {
                let Some(raw) = hit
                    .get("_source")
                    .and_then(|source| source.get(field))
                    .and_then(Value::as_str)
                else {
                    continue;
                };
                let Some((bucket_key, bucket_string)) = date_histogram_bucket_day(raw) else {
                    continue;
                };
                let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_iter()
                .map(|(key, (key_as_string, doc_count))| {
                    serde_json::json!({
                        "key": key,
                        "key_as_string": key_as_string,
                        "doc_count": doc_count,
                    })
                })
                .collect::<Vec<_>>();
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(auto_date_histogram) = aggregation_object
            .get("auto_date_histogram")
            .and_then(Value::as_object)
        {
            let field = auto_date_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let minimum_interval = auto_date_histogram
                .get("minimum_interval")
                .and_then(Value::as_str)
                .unwrap_or("day");
            if !matches!(minimum_interval, "day" | "1d") {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [auto_date_histogram.minimum_interval]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
            for hit in hits {
                let Some(raw) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .and_then(Value::as_str)
                else {
                    continue;
                };
                let Some((bucket_key, bucket_string)) = date_histogram_bucket_day(raw) else {
                    continue;
                };
                let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_iter()
                .map(|(key, (key_as_string, doc_count))| {
                    serde_json::json!({
                        "key": key,
                        "key_as_string": key_as_string,
                        "doc_count": doc_count,
                    })
                })
                .collect::<Vec<_>>();
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets,
                    "interval": "1d"
                }),
            );
            continue;
        }
        if let Some(histogram) = aggregation_object
            .get("histogram")
            .and_then(Value::as_object)
        {
            let field = histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let interval = histogram
                .get("interval")
                .and_then(Value::as_f64)
                .unwrap_or(0.0);
            if interval <= 0.0 {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation [histogram]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<i64, u64>::new();
            for hit in hits {
                let Some(value) = hit
                    .get("_source")
                    .and_then(|source| source.get(field))
                    .and_then(Value::as_f64)
                else {
                    continue;
                };
                let bucket = (value / interval).floor() as i64;
                *counts.entry(bucket).or_insert(0) += 1;
            }
            let buckets = if counts.is_empty() {
                Vec::new()
            } else {
                let min_bucket = *counts.keys().next().unwrap_or(&0);
                let max_bucket = *counts.keys().next_back().unwrap_or(&0);
                (min_bucket..=max_bucket)
                    .map(|bucket| {
                        serde_json::json!({
                            "key": (bucket as f64) * interval,
                            "doc_count": counts.get(&bucket).copied().unwrap_or(0),
                        })
                    })
                    .collect::<Vec<_>>()
            };
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(variable_width_histogram) = aggregation_object
            .get("variable_width_histogram")
            .and_then(Value::as_object)
        {
            let field = variable_width_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let target_buckets = variable_width_histogram
                .get("buckets")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            if target_buckets == 0 {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [variable_width_histogram.buckets]",
                ));
            }
            let values = hits
                .iter()
                .filter_map(|hit| {
                    hit.get("_source")
                        .and_then(|source| lookup_query_field_value(source, field))
                        .and_then(Value::as_f64)
                })
                .collect::<Vec<_>>();
            let interval =
                choose_fallback_variable_width_histogram_interval(&values, target_buckets);
            let mut counts = std::collections::BTreeMap::<u64, (f64, u64)>::new();
            for value in values {
                let Some(bucket_key) = fallback_histogram_bucket_key(value, interval) else {
                    continue;
                };
                let entry = counts
                    .entry(bucket_key.to_bits())
                    .or_insert((bucket_key, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_values()
                .map(|(key, doc_count)| {
                    serde_json::json!({
                        "key": key,
                        "doc_count": doc_count,
                    })
                })
                .collect::<Vec<_>>();
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets,
                    "interval": interval,
                }),
            );
            continue;
        }
        if let Some(geo_distance) = aggregation_object
            .get("geo_distance")
            .and_then(Value::as_object)
        {
            let field = geo_distance
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let Some(origin) = geo_distance
                .get("origin")
                .or_else(|| geo_distance.get("center"))
                .or_else(|| geo_distance.get("point"))
                .and_then(parse_geo_point_value)
            else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [geo_distance.origin]",
                ));
            };
            let unit_multiplier = geo_distance
                .get("unit")
                .and_then(Value::as_str)
                .and_then(geo_distance_unit_meters)
                .unwrap_or(1.0);
            let ranges = geo_distance
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let from = bucket_object.get("from").and_then(Value::as_f64);
                let to = bucket_object.get("to").and_then(Value::as_f64);
                let from_meters = from.unwrap_or(0.0) * unit_multiplier;
                let to_meters = to.unwrap_or(f64::INFINITY) * unit_multiplier;
                let key = bucket_object.get("key").cloned().unwrap_or_else(|| {
                    Value::String(default_geo_distance_range_bucket_key(from, to))
                });
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let Some(point) = hit
                            .get("_source")
                            .and_then(|source| lookup_query_field_value(source, field))
                            .and_then(parse_geo_point_value)
                        else {
                            return false;
                        };
                        let distance = haversine_distance_meters(point, origin);
                        distance >= from_meters && distance < to_meters
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert("from".to_string(), Value::from(from));
                }
                if let Some(to) = to {
                    rendered.insert("to".to_string(), Value::from(to));
                }
                buckets.push(Value::Object(rendered));
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(date_range) = aggregation_object
            .get("date_range")
            .and_then(Value::as_object)
        {
            let field = date_range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = date_range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let from = bucket_object.get("from").and_then(Value::as_str);
                let to = bucket_object.get("to").and_then(Value::as_str);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_date_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let Some(value) = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_str)
                        else {
                            return false;
                        };
                        from.map_or(true, |bound| value >= bound)
                            && to.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert(
                        "from_as_string".to_string(),
                        Value::String(from.to_string()),
                    );
                }
                if let Some(to) = to {
                    rendered.insert("to_as_string".to_string(), Value::String(to.to_string()));
                }
                buckets.push(Value::Object(rendered));
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(ip_range) = aggregation_object
            .get("ip_range")
            .and_then(Value::as_object)
        {
            let field = ip_range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = ip_range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let from = bucket_object.get("from").and_then(Value::as_str);
                let to = bucket_object.get("to").and_then(Value::as_str);
                let from_bound = from.and_then(parse_ip_address_to_u128);
                let to_bound = to.and_then(parse_ip_address_to_u128);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_ip_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let Some(value) = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_str)
                            .and_then(parse_ip_address_to_u128)
                        else {
                            return false;
                        };
                        from_bound.map_or(true, |bound| value >= bound)
                            && to_bound.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert("from".to_string(), Value::String(from.to_string()));
                }
                if let Some(to) = to {
                    rendered.insert("to".to_string(), Value::String(to.to_string()));
                }
                buckets.push(Value::Object(rendered));
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(range) = aggregation_object.get("range").and_then(Value::as_object) {
            let field = range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut buckets = Vec::new();
            for bucket in ranges {
                let bucket_object = match bucket.as_object() {
                    Some(v) => v,
                    None => continue,
                };
                let from = bucket_object.get("from").and_then(Value::as_f64);
                let to = bucket_object.get("to").and_then(Value::as_f64);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let Some(value) = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_f64)
                        else {
                            return false;
                        };
                        from.map_or(true, |bound| value >= bound)
                            && to.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                buckets.push(serde_json::json!({ "key": key, "doc_count": doc_count }));
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(cardinality) = aggregation_object
            .get("cardinality")
            .and_then(Value::as_object)
        {
            let field = cardinality
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut seen = std::collections::BTreeSet::new();
            for hit in hits {
                if let Some(value) = hit.get("_source").and_then(|source| source.get(field)) {
                    seen.insert(value.to_string());
                }
            }
            result.insert(name.clone(), serde_json::json!({ "value": seen.len() }));
            continue;
        }
        if let Some(significant_terms) = aggregation_object
            .get("significant_terms")
            .and_then(Value::as_object)
        {
            let field = significant_terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = significant_terms
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let min_doc_count = significant_terms
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(3);
            let background_filter = significant_terms.get("background_filter");
            let background_hits = if background_filter.is_some() {
                hits.iter()
                    .filter(|hit| {
                        background_filter.is_some_and(|filter| hit_matches_query(hit, filter))
                    })
                    .collect::<Vec<_>>()
            } else {
                hits.iter().collect::<Vec<_>>()
            };
            result.insert(
                name.clone(),
                build_fallback_significant_terms_aggregation(
                    field,
                    size,
                    min_doc_count,
                    hits,
                    &background_hits,
                ),
            );
            continue;
        }
        if let Some(significant_text) = aggregation_object
            .get("significant_text")
            .and_then(Value::as_object)
        {
            let field = significant_text
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = significant_text
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let min_doc_count = significant_text
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(3);
            let background_filter = significant_text.get("background_filter");
            let background_hits = if background_filter.is_some() {
                hits.iter()
                    .filter(|hit| {
                        background_filter.is_some_and(|filter| hit_matches_query(hit, filter))
                    })
                    .collect::<Vec<_>>()
            } else {
                hits.iter().collect::<Vec<_>>()
            };
            result.insert(
                name.clone(),
                build_fallback_significant_text_aggregation(
                    field,
                    size,
                    min_doc_count,
                    hits,
                    &background_hits,
                ),
            );
            continue;
        }
        if let Some(geo_bounds) = aggregation_object
            .get("geo_bounds")
            .and_then(Value::as_object)
        {
            let field = geo_bounds
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut min_lat = f64::INFINITY;
            let mut max_lat = f64::NEG_INFINITY;
            let mut min_lon = f64::INFINITY;
            let mut max_lon = f64::NEG_INFINITY;
            for hit in hits {
                let Some(point) = hit.get("_source").and_then(|source| source.get(field)) else {
                    continue;
                };
                let Some(lat) = point.get("lat").and_then(Value::as_f64) else {
                    continue;
                };
                let Some(lon) = point.get("lon").and_then(Value::as_f64) else {
                    continue;
                };
                min_lat = min_lat.min(lat);
                max_lat = max_lat.max(lat);
                min_lon = min_lon.min(lon);
                max_lon = max_lon.max(lon);
            }
            result.insert(
                name.clone(),
                serde_json::json!({
                    "bounds": {
                        "top_left": { "lat": max_lat, "lon": min_lon },
                        "bottom_right": { "lat": min_lat, "lon": max_lon }
                    }
                }),
            );
            continue;
        }
        if let Some(sum_bucket) = aggregation_object
            .get("sum_bucket")
            .and_then(Value::as_object)
        {
            let buckets_path = sum_bucket
                .get("buckets_path")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let prefix = buckets_path.split('>').next().unwrap_or_default();
            let sum = terms_doc_counts
                .get(prefix)
                .map(|buckets| buckets.iter().map(|(_, count)| *count as f64).sum::<f64>())
                .unwrap_or(0.0);
            result.insert(name.clone(), serde_json::json!({ "value": sum }));
            continue;
        }
        if let Some(scripted_metric) = aggregation_object
            .get("scripted_metric")
            .and_then(Value::as_object)
        {
            let init_ok = scripted_metric
                .get("init_script")
                .and_then(Value::as_str)
                .map(|script| script == "state.count = 0")
                .unwrap_or(false);
            let map_ok = scripted_metric
                .get("map_script")
                .and_then(Value::as_str)
                .map(|script| script == "state.count += params.inc")
                .unwrap_or(false);
            let combine_ok = scripted_metric
                .get("combine_script")
                .and_then(Value::as_str)
                .map(|script| script == "return state.count")
                .unwrap_or(false);
            let reduce_ok = scripted_metric
                .get("reduce_script")
                .and_then(Value::as_str)
                .map(|script| script == "double sum = 0; for (s in states) { sum += s } return sum")
                .unwrap_or(false);
            if init_ok && map_ok && combine_ok && reduce_ok {
                let increment = scripted_metric
                    .get("params")
                    .and_then(|params| params.get("inc"))
                    .and_then(Value::as_f64)
                    .unwrap_or(1.0);
                result.insert(
                    name.clone(),
                    serde_json::json!({
                        "value": (hits.len() as f64) * increment
                    }),
                );
                continue;
            }
            return Err(build_unsupported_search_response(
                "unsupported aggregation [scripted_metric]",
            ));
        }
    }
    Ok(Some(Value::Object(result)))
}

fn default_range_bucket_key(from: Option<f64>, to: Option<f64>) -> String {
    match (from, to) {
        (Some(from), Some(to)) => format!("{from}-{to}"),
        (Some(from), None) => format!("{from}-*"),
        (None, Some(to)) => format!("*-{to}"),
        (None, None) => "*".to_string(),
    }
}

