fn geo_distance_unit_meters(unit: &str) -> Option<f64> {
    match unit.to_ascii_lowercase().as_str() {
        "m" | "meter" | "meters" => Some(1.0),
        "km" | "kilometer" | "kilometers" => Some(1000.0),
        "mi" | "mile" | "miles" => Some(1609.344),
        _ => None,
    }
}

fn parse_ip_address_to_u128(value: &str) -> Option<u128> {
    match value.parse::<std::net::IpAddr>().ok()? {
        std::net::IpAddr::V4(ip) => Some(u32::from(ip) as u128),
        std::net::IpAddr::V6(ip) => Some(u128::from(ip)),
    }
}

fn aggregation_bucket_sort_key(value: &Value) -> String {
    match value {
        Value::String(value) => value.clone(),
        other => other.to_string(),
    }
}

fn aggregation_multi_terms_sort_key(values: &[Value]) -> String {
    values
        .iter()
        .map(aggregation_bucket_sort_key)
        .collect::<Vec<_>>()
        .join("\u{1f}")
}

fn choose_fallback_variable_width_histogram_interval(values: &[f64], target_buckets: usize) -> f64 {
    if values.len() <= 1 {
        return 1.0;
    }
    let target_buckets = target_buckets.max(1);
    let min = values.iter().copied().reduce(f64::min).unwrap_or(0.0);
    let max = values.iter().copied().reduce(f64::max).unwrap_or(min);
    let span = (max - min).abs();
    if !span.is_finite() || span == 0.0 {
        return 1.0;
    }
    let interval = span / (target_buckets as f64);
    if interval.is_finite() && interval > 0.0 {
        interval
    } else {
        1.0
    }
}

fn fallback_histogram_bucket_key(value: f64, interval: f64) -> Option<f64> {
    if !interval.is_finite() || interval <= 0.0 || !value.is_finite() {
        return None;
    }
    Some((value / interval).floor() * interval)
}

fn collect_nested_child_hits(hits: &[Value], path: &str) -> Vec<Value> {
    let mut nested_hits = Vec::new();
    for hit in hits {
        let Some(source) = hit.get("_source") else {
            continue;
        };
        let Some(value) = lookup_query_field_value(source, path) else {
            continue;
        };
        match value {
            Value::Array(children) => {
                for (index, child) in children.iter().enumerate() {
                    if !child.is_object() {
                        continue;
                    }
                    let parent_id = hit.get("_id").and_then(Value::as_str).unwrap_or_default();
                    nested_hits.push(serde_json::json!({
                        "_id": format!("{parent_id}#{path}#{index}"),
                        "_source": child,
                        "_nested_parent": hit
                    }));
                }
            }
            Value::Object(_) => {
                let parent_id = hit.get("_id").and_then(Value::as_str).unwrap_or_default();
                nested_hits.push(serde_json::json!({
                    "_id": format!("{parent_id}#{path}#0"),
                    "_source": value,
                    "_nested_parent": hit
                }));
            }
            _ => {}
        }
    }
    nested_hits
}

fn collect_reverse_nested_parent_hits(hits: &[Value]) -> Vec<Value> {
    let mut seen = std::collections::BTreeSet::new();
    let mut parents = Vec::new();
    for hit in hits {
        let Some(parent) = hit.get("_nested_parent") else {
            continue;
        };
        let parent_id = parent
            .get("_id")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if seen.insert(parent_id.to_string()) {
            parents.push(parent.clone());
        }
    }
    parents
}

fn date_histogram_bucket_day(timestamp: &str) -> Option<(i64, String)> {
    let date = timestamp.get(0..10)?;
    let year: i32 = date.get(0..4)?.parse().ok()?;
    let month: u32 = date.get(5..7)?.parse().ok()?;
    let day: u32 = date.get(8..10)?.parse().ok()?;
    let days = days_from_civil(year, month, day)?;
    let millis = days.checked_mul(86_400_000)?;
    Some((millis, format!("{date}T00:00:00.000Z")))
}

fn days_from_civil(year: i32, month: u32, day: u32) -> Option<i64> {
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let year = year - ((month <= 2) as i32);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let month = month as i32;
    let day = day as i32;
    let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    Some((era * 146097 + doe - 719468) as i64)
}

fn first_supported_metric_aggregation<'a>(
    aggregation_object: &'a serde_json::Map<String, Value>,
) -> Option<(&'a str, &'a Value)> {
    for key in ["min", "max", "sum", "avg", "value_count", "stats"] {
        if let Some(value) = aggregation_object.get(key) {
            return Some((key, value));
        }
    }
    None
}

fn hit_matches_query(hit: &Value, query: &Value) -> bool {
    let record = StoredDocument {
        source: hit.get("_source").cloned().unwrap_or(Value::Null),
        version: 1,
        seq_no: hit
            .get("_seq_no")
            .and_then(Value::as_i64)
            .unwrap_or_default(),
        primary_term: 1,
        routing: None,
        refreshed: true,
    };
    evaluate_search_query(
        &record,
        hit.get("_id").and_then(Value::as_str).unwrap_or_default(),
        query,
    )
    .map(|(matched, _)| matched)
    .unwrap_or(false)
}

fn build_fallback_significant_terms_aggregation(
    field: &str,
    size: usize,
    min_doc_count: u64,
    hits: &[Value],
    background_hits: &[&Value],
) -> Value {
    let mut buckets = std::collections::BTreeMap::<String, (Value, u64)>::new();
    let mut background_counts = std::collections::BTreeMap::<String, u64>::new();
    for hit in background_hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for value in fallback_scalar_bucket_values(value) {
                *background_counts
                    .entry(fallback_bucket_sort_key(&value))
                    .or_insert(0) += 1;
            }
        }
    }
    for hit in hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for value in fallback_scalar_bucket_values(value) {
                let bucket_key = fallback_bucket_sort_key(&value);
                let (_, count) = buckets.entry(bucket_key).or_insert((value, 0));
                *count += 1;
            }
        }
    }
    let total_doc_count = hits.len() as u64;
    let total_bg_count = background_hits.len() as u64;
    let mut buckets = buckets
        .into_values()
        .filter(|(_, doc_count)| *doc_count >= min_doc_count)
        .map(|(key, doc_count)| {
            let bg_count = background_counts
                .get(&fallback_bucket_sort_key(&key))
                .copied()
                .unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": doc_count as f64
            })
        })
        .collect::<Vec<_>>();
    buckets.sort_by(|left, right| {
        let left_count = left.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let right_count = right.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        right_count.cmp(&left_count).then_with(|| {
            fallback_bucket_sort_key(left.get("key").unwrap_or(&Value::Null)).cmp(
                &fallback_bucket_sort_key(right.get("key").unwrap_or(&Value::Null)),
            )
        })
    });
    buckets.truncate(size);
    serde_json::json!({
        "doc_count": total_doc_count,
        "bg_count": total_bg_count,
        "buckets": buckets
    })
}

fn build_fallback_significant_text_aggregation(
    field: &str,
    size: usize,
    min_doc_count: u64,
    hits: &[Value],
    background_hits: &[&Value],
) -> Value {
    let mut buckets = std::collections::BTreeMap::<String, u64>::new();
    let mut background_counts = std::collections::BTreeMap::<String, u64>::new();
    for hit in background_hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for token in fallback_text_bucket_tokens(value) {
                *background_counts.entry(token).or_insert(0) += 1;
            }
        }
    }
    for hit in hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for token in fallback_text_bucket_tokens(value) {
                *buckets.entry(token).or_insert(0) += 1;
            }
        }
    }
    let total_doc_count = hits.len() as u64;
    let total_bg_count = background_hits.len() as u64;
    let mut buckets = buckets
        .into_iter()
        .filter(|(_, doc_count)| *doc_count >= min_doc_count)
        .map(|(key, doc_count)| {
            let bg_count = background_counts.get(&key).copied().unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": doc_count as f64
            })
        })
        .collect::<Vec<_>>();
    buckets.sort_by(|left, right| {
        let left_count = left.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let right_count = right.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        right_count.cmp(&left_count).then_with(|| {
            left.get("key")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .cmp(right.get("key").and_then(Value::as_str).unwrap_or_default())
        })
    });
    buckets.truncate(size);
    serde_json::json!({
        "doc_count": total_doc_count,
        "bg_count": total_bg_count,
        "buckets": buckets
    })
}

fn fallback_text_bucket_tokens(value: &Value) -> Vec<String> {
    fn visit(value: &Value, values: &mut std::collections::BTreeMap<String, ()>) {
        match value {
            Value::Array(items) => {
                for item in items {
                    visit(item, values);
                }
            }
            Value::String(text) => {
                for token in text
                    .split(|ch: char| !ch.is_ascii_alphanumeric())
                    .filter(|token| !token.is_empty())
                {
                    values.insert(token.to_ascii_lowercase(), ());
                }
            }
            _ => {}
        }
    }
    let mut values = std::collections::BTreeMap::new();
    visit(value, &mut values);
    values.into_keys().collect()
}

fn fallback_scalar_bucket_values(value: &Value) -> Vec<Value> {
    fn visit(value: &Value, values: &mut std::collections::BTreeMap<String, Value>) {
        match value {
            Value::Array(items) => {
                for item in items {
                    visit(item, values);
                }
            }
            Value::String(_) | Value::Bool(_) | Value::Number(_) => {
                values
                    .entry(fallback_bucket_sort_key(value))
                    .or_insert_with(|| value.clone());
            }
            _ => {}
        }
    }
    let mut values = std::collections::BTreeMap::new();
    visit(value, &mut values);
    values.into_values().collect()
}

fn fallback_bucket_sort_key(value: &Value) -> String {
    match value {
        Value::String(value) => format!("s:{value}"),
        Value::Bool(value) => format!("b:{value}"),
        Value::Number(value) => format!("n:{value}"),
        _ => String::new(),
    }
}

fn normalize_alias_metadata_for_readback(metadata: Value) -> Value {
    let mut metadata = metadata;
    if let Some(object) = metadata.as_object_mut() {
        if let Some(routing) = object.remove("routing") {
            object
                .entry("index_routing".to_string())
                .or_insert_with(|| routing.clone());
            object
                .entry("search_routing".to_string())
                .or_insert(routing);
        }
    }
    metadata
}

fn validate_single_alias_mutation_body(body: &Value) -> Option<RestResponse> {
    let Some(object) = body.as_object() else {
        return None;
    };
    for (field, value) in object {
        match field.as_str() {
            "index" | "alias" | "routing" | "indexRouting" | "index-routing" | "index_routing"
            | "searchRouting" | "search-routing" | "search_routing" | "is_write_index"
            | "is_hidden" => {}
            "filter" if value.is_object() => {}
            _ => {
                return Some(RestResponse::opensearch_error(
                    400,
                    "illegal_argument_exception",
                    format!("unknown field [{field}]"),
                ));
            }
        }
    }
    None
}

fn normalize_single_alias_mutation_body(body: Value) -> Value {
    let Value::Object(mut object) = body else {
        return body;
    };
    for (source, target) in [
        ("indexRouting", "index_routing"),
        ("index-routing", "index_routing"),
        ("searchRouting", "search_routing"),
        ("search-routing", "search_routing"),
    ] {
        if let Some(value) = object.remove(source) {
            object.entry(target.to_string()).or_insert(value);
        }
    }
    Value::Object(object)
}

fn extract_alias_named_mutation_targets(body: &Value) -> Vec<String> {
    let mut targets = Vec::new();
    if let Some(index) = body.get("index").and_then(Value::as_str) {
        targets.push(index.to_string());
    }
    if let Some(indices) = body.get("indices") {
        if let Some(index) = indices.as_str() {
            targets.push(index.to_string());
        } else if let Some(array) = indices.as_array() {
            for value in array {
                if let Some(index) = value.as_str() {
                    targets.push(index.to_string());
                }
            }
        }
    }
    targets
}

fn extract_alias_names_from_body(body: &Value) -> Vec<String> {
    let mut aliases = Vec::new();
    if let Some(alias) = body.get("alias").and_then(Value::as_str) {
        aliases.push(alias.to_string());
    }
    if let Some(values) = body.get("aliases") {
        if let Some(alias) = values.as_str() {
            aliases.push(alias.to_string());
        } else if let Some(array) = values.as_array() {
            for value in array {
                if let Some(alias) = value.as_str() {
                    aliases.push(alias.to_string());
                }
            }
        }
    }
    aliases
}

fn parse_index_expand_wildcards(
    expand_wildcards: &str,
) -> Result<(bool, bool, bool), RestResponse> {
    if expand_wildcards.is_empty() {
        return Ok((true, false, false));
    }
    let tokens = expand_wildcards
        .split(',')
        .map(str::trim)
        .collect::<Vec<_>>();
    if tokens.is_empty() {
        return Ok((true, false, false));
    }

    let mut include_open = false;
    let mut include_hidden = false;
    let mut include_closed = false;
    for token in tokens {
        match token {
            "open" => {
                include_open = true;
            }
            "all" => {
                include_open = true;
                include_hidden = true;
                include_closed = true;
            }
            "hidden" => {
                include_hidden = true;
            }
            "closed" => {
                include_closed = true;
            }
            "none" => {
                include_open = false;
                include_hidden = false;
                include_closed = false;
            }
            _ => {
                return Err(RestResponse::opensearch_error_kind(
                    os_rest::RestErrorKind::IllegalArgument,
                    format!("No valid expand wildcard value [{token}]"),
                ));
            }
        }
    }
    Ok((include_open, include_hidden, include_closed))
}

