fn ingest_simulate_docs(payload: &Value) -> Vec<Value> {
    if let Some(docs) = payload.get("docs").and_then(Value::as_array) {
        return docs
            .iter()
            .map(|doc| {
                let source = doc
                    .get("_source")
                    .cloned()
                    .or_else(|| {
                        doc.get("doc")
                            .and_then(|inner| inner.get("_source"))
                            .cloned()
                    })
                    .unwrap_or_else(|| Value::Object(serde_json::Map::new()));
                serde_json::json!({
                    "doc": {
                        "_source": source
                    }
                })
            })
            .collect();
    }
    vec![serde_json::json!({
        "doc": {
            "_source": payload
                .get("doc")
                .and_then(|doc| doc.get("_source"))
                .cloned()
                .unwrap_or_else(|| Value::Object(serde_json::Map::new()))
        }
    })]
}

fn infer_field_caps_type(value: &Value) -> &'static str {
    match value {
        Value::Bool(_) => "boolean",
        Value::Number(number) if number.is_f64() => "float",
        Value::Number(_) => "long",
        Value::Array(_) => "keyword",
        Value::Object(_) => "object",
        _ => "text",
    }
}

fn infer_dynamic_mapping_for_value(value: &Value) -> Value {
    match value {
        Value::Bool(_) => serde_json::json!({ "type": "boolean" }),
        Value::Number(number) if number.is_f64() => serde_json::json!({ "type": "float" }),
        Value::Number(_) => serde_json::json!({ "type": "long" }),
        Value::Object(_) => serde_json::json!({ "type": "object" }),
        Value::Array(values) => values
            .iter()
            .find(|candidate| !candidate.is_null())
            .map(infer_dynamic_mapping_for_value)
            .unwrap_or_else(|| serde_json::json!({ "type": "keyword" })),
        _ => serde_json::json!({
            "type": "text",
            "fields": {
                "keyword": {
                    "type": "keyword",
                    "ignore_above": 256
                }
            }
        }),
    }
}

fn filter_source_fields(source: &Value, includes: &str) -> Value {
    let selectors = source_filter_selectors(includes);
    source_include_value(source, "", &selectors)
        .unwrap_or_else(|| Value::Object(serde_json::Map::new()))
}

fn apply_search_source_projection_to_hits(hits: &mut [Value], body: &Value) {
    for hit in hits {
        let Some(hit_object) = hit.as_object_mut() else {
            continue;
        };
        let Some(source) = hit_object.get("_source").cloned() else {
            continue;
        };
        match search_source_projection(&source, body) {
            Some(projected) => {
                hit_object.insert("_source".to_string(), projected);
            }
            None => {
                hit_object.remove("_source");
            }
        }
    }
}

fn search_source_projection(source: &Value, body: &Value) -> Option<Value> {
    let mut projected = match body.get("_source") {
        Some(Value::Bool(false)) => return None,
        Some(Value::Bool(true)) | None => source.clone(),
        Some(Value::String(includes)) => filter_source_fields(source, includes),
        Some(Value::Array(_)) => {
            let includes = source_filter_selector_csv(body.get("_source")?)?;
            filter_source_fields(source, &includes)
        }
        Some(Value::Object(object)) => {
            if object.get("fetch") == Some(&Value::Bool(false)) {
                return None;
            }
            let mut current = source.clone();
            if let Some(includes) = object
                .get("includes")
                .or_else(|| object.get("include"))
                .and_then(source_filter_selector_csv)
            {
                current = filter_source_fields(&current, &includes);
            }
            if let Some(excludes) = object
                .get("excludes")
                .or_else(|| object.get("exclude"))
                .and_then(source_filter_selector_csv)
            {
                current = exclude_source_fields(&current, &excludes);
            }
            current
        }
        Some(_) => source.clone(),
    };
    if stored_fields_should_suppress_default_source(body) {
        return None;
    }
    if let Some(includes) = body
        .get("_source_includes")
        .or_else(|| body.get("_source_include"))
        .and_then(source_filter_selector_csv)
    {
        projected = filter_source_fields(&projected, &includes);
    }
    if let Some(excludes) = body
        .get("_source_excludes")
        .or_else(|| body.get("_source_exclude"))
        .and_then(source_filter_selector_csv)
    {
        projected = exclude_source_fields(&projected, &excludes);
    }
    Some(projected)
}

fn source_filter_selector_csv(value: &Value) -> Option<String> {
    match value {
        Value::String(raw) if !raw.trim().is_empty() => Some(raw.clone()),
        Value::Array(values) if !values.is_empty() => {
            let mut fields = Vec::new();
            for value in values {
                let field = value.as_str()?.trim();
                if field.is_empty() {
                    return None;
                }
                fields.push(field.to_string());
            }
            Some(fields.join(","))
        }
        _ => None,
    }
}

fn exclude_source_fields(source: &Value, excludes: &str) -> Value {
    let selectors = source_filter_selectors(excludes);
    source_exclude_value(source, "", &selectors)
        .unwrap_or_else(|| Value::Object(serde_json::Map::new()))
}

fn source_filter_selectors(selectors: &str) -> Vec<String> {
    selectors
        .split(',')
        .map(str::trim)
        .filter(|selector| !selector.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn source_selector_matches(selector: &str, path: &str) -> bool {
    if path.is_empty() {
        return false;
    }
    if wildcard_match(selector, path) {
        return true;
    }
    if !selector.contains('*') {
        return path
            .strip_prefix(selector)
            .is_some_and(|suffix| suffix.starts_with('.'));
    }
    false
}

fn source_path_selected(path: &str, selectors: &[String]) -> bool {
    selectors
        .iter()
        .any(|selector| source_selector_matches(selector, path))
}

fn source_include_value(value: &Value, path: &str, selectors: &[String]) -> Option<Value> {
    if source_path_selected(path, selectors) {
        return Some(value.clone());
    }
    match value {
        Value::Object(object) => {
            let mut filtered = serde_json::Map::new();
            for (key, child) in object {
                let child_path = if path.is_empty() {
                    key.clone()
                } else {
                    format!("{path}.{key}")
                };
                if let Some(filtered_child) = source_include_value(child, &child_path, selectors) {
                    filtered.insert(key.clone(), filtered_child);
                }
            }
            (!filtered.is_empty()).then_some(Value::Object(filtered))
        }
        Value::Array(items) => {
            let filtered_items = items
                .iter()
                .filter_map(|item| source_include_value(item, path, selectors))
                .collect::<Vec<_>>();
            (!filtered_items.is_empty()).then_some(Value::Array(filtered_items))
        }
        _ => None,
    }
}

fn source_exclude_value(value: &Value, path: &str, selectors: &[String]) -> Option<Value> {
    if source_path_selected(path, selectors) {
        return None;
    }
    match value {
        Value::Object(object) => {
            let mut filtered = serde_json::Map::new();
            for (key, child) in object {
                let child_path = if path.is_empty() {
                    key.clone()
                } else {
                    format!("{path}.{key}")
                };
                if let Some(filtered_child) = source_exclude_value(child, &child_path, selectors) {
                    filtered.insert(key.clone(), filtered_child);
                }
            }
            (!filtered.is_empty()).then_some(Value::Object(filtered))
        }
        Value::Array(items) => {
            let filtered_items = items
                .iter()
                .filter_map(|item| source_exclude_value(item, path, selectors))
                .collect::<Vec<_>>();
            Some(Value::Array(filtered_items))
        }
        _ => Some(value.clone()),
    }
}

fn extract_source_path_value(source: &Value, field: &str) -> Option<Value> {
    if let Some(value) = source.get(field) {
        return Some(value.clone());
    }
    let path = field.split('.').collect::<Vec<_>>();
    extract_source_path_segments(source, &path)
}

fn extract_source_path_segments(value: &Value, path: &[&str]) -> Option<Value> {
    if path.is_empty() {
        return Some(value.clone());
    }
    match value {
        Value::Object(object) => {
            let mut joined = path[0].to_string();
            for next_index in 0..path.len() {
                if next_index > 0 {
                    joined.push('.');
                    joined.push_str(path[next_index]);
                }
                if let Some(child) = object.get(&joined) {
                    return extract_source_path_segments(child, &path[next_index + 1..]);
                }
            }
            None
        }
        Value::Array(items) => {
            let values = items
                .iter()
                .filter_map(|item| extract_source_path_segments(item, path))
                .flat_map(|value| match value {
                    Value::Array(values) => values,
                    value => vec![value],
                })
                .collect::<Vec<_>>();
            (!values.is_empty()).then_some(Value::Array(values))
        }
        _ => None,
    }
}

fn search_field_values(value: Value) -> Value {
    match value {
        Value::Array(values) => Value::Array(values),
        value => Value::Array(vec![value]),
    }
}

fn apply_supported_update_script(source: &mut Value, script: &Value) -> Result<(), RestResponse> {
    let Some(script_object) = script.as_object() else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "update script must be an object"
                },
                "status": 400
            }),
        ));
    };
    let Some(script_source) = script_object.get("source").and_then(Value::as_str) else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "update script source is required"
                },
                "status": 400
            }),
        ));
    };
    let params = script_object
        .get("params")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let Some(field_expr) = script_source.strip_prefix("ctx._source.") else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "unsupported update script"
                },
                "status": 400
            }),
        ));
    };
    let Some((field, param)) = field_expr.split_once(" = params.") else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "unsupported update script"
                },
                "status": 400
            }),
        ));
    };
    let Some(value) = params.get(param).cloned() else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": format!("missing script param [{param}]")
                },
                "status": 400
            }),
        ));
    };
    let Some(object) = source.as_object_mut() else {
        *source = serde_json::json!({});
        let object = source.as_object_mut().expect("source converted to object");
        object.insert(field.to_string(), value);
        return Ok(());
    };
    object.insert(field.to_string(), value);
    Ok(())
}

fn merge_json_object(target: &mut Value, patch: &Value) {
    let Some(target_object) = target.as_object_mut() else {
        *target = patch.clone();
        return;
    };
    let Some(patch_object) = patch.as_object() else {
        *target = patch.clone();
        return;
    };
    for (key, value) in patch_object {
        target_object.insert(key.clone(), value.clone());
    }
}

fn parse_wait_for_nodes(raw: &str) -> Option<u64> {
    let digits = raw.chars().filter(char::is_ascii_digit).collect::<String>();
    if digits.is_empty() {
        None
    } else {
        digits.parse::<u64>().ok()
    }
}

fn cluster_health_status_rank(status: &str) -> u8 {
    match status {
        "green" => 3,
        "yellow" => 2,
        "red" => 1,
        _ => 0,
    }
}

fn matches_query_body(source: &Value, query: Option<&Value>) -> bool {
    let Some(query) = query else {
        return true;
    };
    if query.get("match_all").is_some() {
        return true;
    }
    if let Some(term) = query.get("term").and_then(Value::as_object) {
        for (field, expected) in term {
            if source.get(field) != Some(expected) {
                return false;
            }
        }
        return true;
    }
    if let Some(range) = query.get("range").and_then(Value::as_object) {
        let Some((field, bounds)) = range.iter().next() else {
            return false;
        };
        return value_matches_range(source.get(field), bounds);
    }
    if let Some(query_string) = query.get("query_string").and_then(Value::as_object) {
        return evaluate_text_query_spec(source, query_string, false).0;
    }
    if let Some(simple_query_string) = query.get("simple_query_string").and_then(Value::as_object) {
        return evaluate_text_query_spec(source, simple_query_string, true).0;
    }
    false
}

fn validate_query_payload(query: Option<&Value>) -> (bool, String) {
    validate_query_payload_with_options(query, false)
}

fn validate_query_payload_for_validate_route(query: Option<&Value>) -> (bool, String) {
    validate_query_payload_with_options(query, true)
}

fn validate_query_payload_with_options(query: Option<&Value>, allow_range: bool) -> (bool, String) {
    let Some(query) = query else {
        return (true, "no query provided".to_string());
    };
    if query.get("match_all").is_some() {
        return (true, "match_all query".to_string());
    }
    if let Some(term) = query.get("term") {
        if term.as_object().is_some_and(|object| !object.is_empty()) {
            return (
                true,
                opensearch_like_term_explanation(term).unwrap_or_else(|| {
                    format!(
                        "term query fields: {}",
                        term.as_object().map(|object| object.len()).unwrap_or(0)
                    )
                }),
            );
        }
        return (false, "term query requires at least one field".to_string());
    }
    if let Some(match_query) = query.get("match") {
        if match_query
            .as_object()
            .is_some_and(|object| !object.is_empty())
        {
            return (
                true,
                format!(
                    "match query fields: {}",
                    match_query
                        .as_object()
                        .map(|object| object.len())
                        .unwrap_or(0)
                ),
            );
        }
        return (false, "match query requires at least one field".to_string());
    }
    if allow_range {
        if let Some(range) = query.get("range") {
            if range.as_object().is_some_and(|object| !object.is_empty()) {
                return (
                    true,
                    opensearch_like_range_explanation(range)
                        .unwrap_or_else(|| "range query".to_string()),
                );
            }
            return (false, "range query requires at least one field".to_string());
        }
    }
    for query_name in ["query_string", "simple_query_string"] {
        if let Some(spec) = query.get(query_name) {
            let Some(object) = spec.as_object() else {
                return (false, format!("{query_name} query requires an object"));
            };
            if object
                .get("query")
                .and_then(Value::as_str)
                .is_some_and(|query| !query.is_empty())
            {
                return (true, format!("{query_name} query"));
            }
            return (false, format!("{query_name} query requires query text"));
        }
    }
    if query.as_object().is_some_and(|object| object.is_empty()) {
        return (false, "query object must not be empty".to_string());
    }
    (false, "unsupported query type".to_string())
}

fn opensearch_like_query_explanation(query: &Value) -> Option<String> {
    if query.get("match_all").is_some() {
        return Some("*:*".to_string());
    }
    if let Some(term) = query.get("term") {
        return opensearch_like_term_explanation(term);
    }
    if let Some(range) = query.get("range") {
        return opensearch_like_range_explanation(range);
    }
    None
}

fn opensearch_like_term_explanation(term: &Value) -> Option<String> {
    let object = term.as_object()?;
    let (field, value) = object.iter().next()?;
    let rendered_value = match value {
        Value::String(value) => value.clone(),
        Value::Object(spec) => spec
            .get("value")
            .or_else(|| spec.get("term"))
            .and_then(Value::as_str)
            .map(str::to_string)
            .unwrap_or_else(|| value.to_string()),
        _ => value.to_string(),
    };
    Some(format!("ConstantScore({field}:{rendered_value})"))
}

fn opensearch_like_range_explanation(range: &Value) -> Option<String> {
    let object = range.as_object()?;
    let (field, bounds) = object.iter().next()?;
    let bounds = bounds.as_object()?;
    let lower = bounds
        .get("gte")
        .or_else(|| bounds.get("gt"))
        .and_then(Value::as_str)
        .unwrap_or("*");
    let upper = bounds
        .get("lte")
        .or_else(|| bounds.get("lt"))
        .and_then(Value::as_str)
        .unwrap_or("*");
    Some(format!("ConstantScore({field}:[{lower} TO {upper}])"))
}

fn substitute_template_params(
    value: &Value,
    params: Option<&serde_json::Map<String, Value>>,
) -> Value {
    let Some(params) = params else {
        return value.clone();
    };
    match value {
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(key, value)| (key.clone(), substitute_template_params(value, Some(params))))
                .collect(),
        ),
        Value::Array(values) => Value::Array(
            values
                .iter()
                .map(|value| substitute_template_params(value, Some(params)))
                .collect(),
        ),
        Value::String(text) => {
            if let Some(key) = text
                .strip_prefix("{{")
                .and_then(|value| value.strip_suffix("}}"))
                .map(str::trim)
            {
                if let Some(replacement) = params.get(key) {
                    return replacement.clone();
                }
            }
            let mut rendered = text.clone();
            for (key, replacement) in params {
                let placeholder = format!("{{{{{key}}}}}");
                let replacement_text = replacement
                    .as_str()
                    .map(ToOwned::to_owned)
                    .unwrap_or_else(|| replacement.to_string());
                rendered = rendered.replace(&placeholder, &replacement_text);
            }
            Value::String(rendered)
        }
        _ => value.clone(),
    }
}

fn apply_update_by_query_script(source: &mut Value, script: &Value) {
    let _ = apply_source_assignment_script(source, script);
}

fn apply_source_assignment_script(source: &mut Value, script: &Value) -> Result<(), RestResponse> {
    let Some(script_source) = script.get("source").and_then(Value::as_str) else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "script source is required"
                },
                "status": 400
            }),
        ));
    };
    let Some((field, value_literal)) = script_source
        .strip_prefix("ctx._source.")
        .and_then(|rest| rest.split_once('='))
        .map(|(field, value)| (field.trim(), value.trim()))
    else {
        return Err(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": "unsupported source assignment script"
                },
                "status": 400
            }),
        ));
    };
    let value = parse_source_assignment_value(script, value_literal)?;
    let Some(source_obj) = source.as_object_mut() else {
        *source = serde_json::json!({});
        let source_obj = source.as_object_mut().expect("source converted to object");
        source_obj.insert(field.to_string(), value);
        return Ok(());
    };
    source_obj.insert(field.to_string(), value);
    Ok(())
}

fn parse_source_assignment_value(
    script: &Value,
    value_literal: &str,
) -> Result<Value, RestResponse> {
    if let Some(param_name) = value_literal.strip_prefix("params.") {
        return script
            .get("params")
            .and_then(Value::as_object)
            .and_then(|params| params.get(param_name))
            .cloned()
            .ok_or_else(|| {
                RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!("missing script param [{param_name}]")
                        },
                        "status": 400
                    }),
                )
            });
    }
    if value_literal.eq_ignore_ascii_case("true") {
        return Ok(Value::Bool(true));
    }
    if value_literal.eq_ignore_ascii_case("false") {
        return Ok(Value::Bool(false));
    }
    if value_literal.eq_ignore_ascii_case("null") {
        return Ok(Value::Null);
    }
    if let Some(value) = value_literal
        .strip_prefix('\'')
        .and_then(|value| value.strip_suffix('\''))
    {
        return Ok(Value::String(value.to_string()));
    }
    if let Ok(parsed) = serde_json::from_str::<Value>(value_literal) {
        return Ok(parsed);
    }
    Ok(Value::String(value_literal.trim_matches('"').to_string()))
}

fn matches_index_selector(selector: &str, index: &str) -> bool {
    if selector == "_all" || selector == "*" {
        return true;
    }
    selector
        .split(',')
        .any(|pattern| wildcard_match(pattern, index))
}

fn index_metadata_is_hidden(index_body: &Value) -> bool {
    index_body["settings"]["index"]["hidden"]
        .as_str()
        .map(|value| value == "true")
        .or_else(|| index_body["settings"]["index"]["hidden"].as_bool())
        .unwrap_or(false)
}

fn index_metadata_is_knn_enabled(index_body: &serde_json::Map<String, Value>) -> bool {
    let settings = index_body.get("settings").unwrap_or(&Value::Null);
    settings["index"]["knn"]
        .as_str()
        .map(|value| value == "true")
        .or_else(|| settings["index"]["knn"].as_bool())
        .or_else(|| {
            settings["index.knn"]
                .as_str()
                .map(|value| value == "true")
                .or_else(|| settings["index.knn"].as_bool())
        })
        .unwrap_or(false)
}

