fn nested_mapping_paths_for_index(index_body: &Value) -> Vec<String> {
    let mut paths = Vec::new();
    collect_nested_mapping_paths(
        index_body
            .get("mappings")
            .and_then(|mappings| mappings.get("properties")),
        "",
        &mut paths,
    );
    paths
}

fn completion_mapping_field_count_for_index(index_body: &Value) -> usize {
    count_completion_mapping_fields(
        index_body
            .get("mappings")
            .and_then(|mappings| mappings.get("properties")),
    )
}

fn count_completion_mapping_fields(properties: Option<&Value>) -> usize {
    let Some(properties) = properties.and_then(Value::as_object) else {
        return 0;
    };
    properties
        .values()
        .map(|mapping| {
            let current = mapping
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|field_type| field_type == "completion")
                as usize;
            current + count_completion_mapping_fields(mapping.get("properties"))
        })
        .sum()
}

fn collect_nested_mapping_paths(properties: Option<&Value>, prefix: &str, paths: &mut Vec<String>) {
    let Some(properties) = properties.and_then(Value::as_object) else {
        return;
    };
    for (field, mapping) in properties {
        let path = if prefix.is_empty() {
            field.clone()
        } else {
            format!("{prefix}.{field}")
        };
        if mapping
            .get("type")
            .and_then(Value::as_str)
            .is_some_and(|field_type| field_type == "nested")
        {
            paths.push(path.clone());
        }
        collect_nested_mapping_paths(mapping.get("properties"), &path, paths);
    }
}

fn nested_document_count_for_source(source: &Value, nested_paths: &[String]) -> usize {
    nested_paths
        .iter()
        .map(|path| nested_value_count_at_path(source, path))
        .sum()
}

fn nested_value_count_at_path(source: &Value, path: &str) -> usize {
    let mut values = vec![source];
    for segment in path.split('.') {
        let mut next = Vec::new();
        for value in values {
            match value {
                Value::Object(object) => {
                    if let Some(child) = object.get(segment) {
                        next.push(child);
                    }
                }
                Value::Array(items) => {
                    for item in items {
                        if let Some(child) = item.get(segment) {
                            next.push(child);
                        }
                    }
                }
                _ => {}
            }
        }
        values = next;
    }
    values
        .into_iter()
        .map(|value| match value {
            Value::Array(items) => items.len(),
            Value::Object(_) => 1,
            _ => 0,
        })
        .sum()
}

fn decode_url_component(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut decoded = String::with_capacity(value.len());
    let mut index = 0usize;
    while index < bytes.len() {
        match bytes[index] {
            b'+' => {
                decoded.push(' ');
                index += 1;
            }
            b'%' if index + 2 < bytes.len() => {
                let hex = &value[index + 1..index + 3];
                if let Ok(byte) = u8::from_str_radix(hex, 16) {
                    decoded.push(byte as char);
                    index += 3;
                } else {
                    decoded.push('%');
                    index += 1;
                }
            }
            _ => {
                decoded.push(bytes[index] as char);
                index += 1;
            }
        }
    }
    decoded
}

