    #[test]
    fn index_resize_routes_create_target_indices_for_clone_shrink_split_and_scale() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-resize-probe")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        for (method, path, expected_target) in [
            (
                RestMethod::Put,
                "/logs-resize-probe/_clone/logs-clone-probe",
                "logs-clone-probe",
            ),
            (
                RestMethod::Post,
                "/logs-resize-probe/_shrink/logs-shrink-probe",
                "logs-shrink-probe",
            ),
            (
                RestMethod::Put,
                "/logs-resize-probe/_split/logs-split-probe",
                "logs-split-probe",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(method, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(
                response.body["acknowledged"],
                Value::Bool(true),
                "path {path}"
            );
            assert_eq!(
                response.body["shards_acknowledged"],
                Value::Bool(true),
                "path {path}"
            );
            assert_eq!(response.body["index"], expected_target, "path {path}");
        }

        let scale_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-resize-probe/_scale").with_json_body(
                serde_json::json!({
                    "target": "logs-scale-probe"
                }),
            ),
        );
        assert_eq!(scale_response.status, 200);
        assert_eq!(scale_response.body["index"], "logs-scale-probe");

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for (target, operation) in [
            ("logs-clone-probe", "clone"),
            ("logs-shrink-probe", "shrink"),
            ("logs-split-probe", "split"),
            ("logs-scale-probe", "scale"),
        ] {
            assert_eq!(
                manifest["indices"][target]["resize_source"],
                "logs-resize-probe"
            );
            assert_eq!(manifest["indices"][target]["resize_operation"], operation);
        }
    }

    #[test]
    fn rollover_routes_support_unnamed_and_named_target_contracts() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-rollover-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-rollover-000001/_alias/logs-rollover-write",
            )
            .with_json_body(serde_json::json!({
                "is_write_index": true
            })),
        );
        assert_eq!(alias.status, 200);

        let unnamed = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover",
        ));
        assert_eq!(unnamed.status, 200);
        assert_eq!(unnamed.body["old_index"], "logs-rollover-000001");
        assert_eq!(unnamed.body["new_index"], "logs-rollover-000002");
        assert_eq!(unnamed.body["rolled_over"], Value::Bool(true));

        let named = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover/logs-rollover-000123",
        ));
        assert_eq!(named.status, 200);
        assert_eq!(named.body["old_index"], "logs-rollover-000002");
        assert_eq!(named.body["new_index"], "logs-rollover-000123");
        assert_eq!(named.body["rolled_over"], Value::Bool(true));

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-rollover-000001"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(false)
        );
        assert_eq!(
            manifest["indices"]["logs-rollover-000002"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(false)
        );
        assert_eq!(
            manifest["indices"]["logs-rollover-000123"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(true)
        );
    }

    #[test]
    fn rollover_named_target_resolves_create_index_body_write_alias_after_cleanup() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let initial_create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/rollover-logs-000001").with_json_body(
                serde_json::json!({
                    "aliases": {
                        "rollover-write": {
                            "is_write_index": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(initial_create.status, 200);

        let initial_readback =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/rollover-write"));
        assert_eq!(initial_readback.status, 200);

        let cleanup = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/rollover-logs-000001,rollover-logs-000002?ignore_unavailable=true",
        ));
        assert_eq!(cleanup.status, 200);

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/rollover-logs-000001").with_json_body(
                serde_json::json!({
                    "aliases": {
                        "rollover-write": {
                            "is_write_index": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);

        let readback =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/rollover-write"));
        assert_eq!(readback.status, 200);
        assert_eq!(
            readback.body["rollover-logs-000001"]["aliases"]["rollover-write"]["is_write_index"],
            Value::Bool(true)
        );

        let rollover = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/rollover-write/_rollover/rollover-logs-000002",
        ));
        assert_eq!(rollover.status, 200, "{rollover:?}");
        assert_eq!(rollover.body["old_index"], "rollover-logs-000001");
        assert_eq!(rollover.body["new_index"], "rollover-logs-000002");
        assert_eq!(rollover.body["rolled_over"], Value::Bool(true));
    }

