    #[test]
    fn secure_authentication_users_file_drives_runtime_basic_auth_and_service_accounts() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
        env::remove_var("SECURITY_ADMIN_USERNAME");
        env::remove_var("SECURITY_ADMIN_PASSWORD");
        env::remove_var("SECURITY_READER_USERNAME");
        env::remove_var("SECURITY_READER_PASSWORD");
        env::remove_var("SECURITY_WRITER_USERNAME");
        env::remove_var("SECURITY_WRITER_PASSWORD");
        env::remove_var("SECURITY_SERVICE_ACCOUNT_USERNAME");
        env::remove_var("SECURITY_SERVICE_ACCOUNT_TOKEN");
        env::remove_var("SECURITY_SERVICE_ACCOUNT_ROLE");
        env::remove_var("SECURITY_SERVICE_ACCOUNT_TENANTS");

        let root = std::env::temp_dir().join(format!(
            "steelsearch-authentication-users-runtime-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time before unix epoch")
                .as_nanos()
        ));
        std::fs::create_dir_all(&root).expect("create temp root");
        let users_path = root.join("authentication-users.json");
        std::fs::write(
            &users_path,
            r#"{
                "users": [
                    {"username": "file-admin", "password": "file-admin-password", "roles": ["admin"]},
                    {"username": "file-reader", "password": "file-reader-password", "roles": ["reader"]}
                ],
                "service_accounts": [
                    {"name": "file-indexer", "token": "file-indexer-token", "roles": ["writer"]}
                ]
            }"#,
        )
        .expect("write authentication users file");
        env::set_var("SECURITY_AUTHENTICATION_USERS_FILE", &users_path);

        let users_file = security_authentication_users_file().expect("users file should parse");
        assert_eq!(users_file.users.len(), 2);
        assert_eq!(users_file.service_accounts.len(), 1);
        assert_eq!(
            security_basic_credentials_with_roles().expect("file credentials with roles"),
            vec![
                (
                    "file-admin".to_string(),
                    "file-admin-password".to_string(),
                    SecuritySubject {
                        username: "file-admin".to_string(),
                        role: "admin",
                        tenants: Vec::new(),
                    },
                ),
                (
                    "file-reader".to_string(),
                    "file-reader-password".to_string(),
                    SecuritySubject {
                        username: "file-reader".to_string(),
                        role: "reader",
                        tenants: Vec::new(),
                    },
                ),
                (
                    "file-indexer".to_string(),
                    "file-indexer-token".to_string(),
                    SecuritySubject {
                        username: "file-indexer".to_string(),
                        role: "writer",
                        tenants: Vec::new(),
                    },
                ),
            ]
        );

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let admin_root =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/").with_header(
                "Authorization",
                "Basic ZmlsZS1hZG1pbjpmaWxlLWFkbWluLXBhc3N3b3Jk",
            ));
        assert_eq!(admin_root.status, 200);

        let service_account_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_bulk")
                .with_header("Authorization", "Basic ZmlsZS1pbmRleGVyOmZpbGUtaW5kZXhlci10b2tlbg==")
                .with_header("content-type", "application/x-ndjson")
                .with_body(
                    concat!(
                        "{\"index\":{\"_index\":\"runtime-users-file-000001\",\"_id\":\"doc-1\"}}\n",
                        "{\"message\":\"indexed by service account\"}\n"
                    )
                    .as_bytes()
                    .to_vec(),
                ),
        );
        assert_eq!(service_account_write.status, 200);

        env::set_var(
            "SECURITY_AUTHENTICATION_USERS_FILE",
            root.join("missing-users.json"),
        );
        let missing_file =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/").with_header(
                "Authorization",
                "Basic ZmlsZS1hZG1pbjpmaWxlLWFkbWluLXBhc3N3b3Jk",
            ));
        assert_eq!(missing_file.status, 401);
        assert_eq!(missing_file.body["error"]["type"], "security_exception");
        assert!(missing_file.body["error"]["reason"]
            .as_str()
            .expect("security reason")
            .contains("unable to read authentication users file"));

        env::remove_var("STEELSEARCH_SECURITY_ENABLED");
        env::remove_var("SECURITY_AUTHENTICATION_USERS_FILE");
        let _ = std::fs::remove_file(users_path);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn secure_role_permission_evaluator_enforces_admin_reader_writer_matrix() {
        assert!(security_role_has_permission(
            None,
            SecurityPermission::ClusterAdmin
        ));
        assert!(security_role_has_permission(
            Some("admin"),
            SecurityPermission::ClusterAdmin
        ));
        assert!(security_role_has_permission(
            Some("admin"),
            SecurityPermission::IndexRead
        ));
        assert!(security_role_has_permission(
            Some("admin"),
            SecurityPermission::IndexWrite
        ));
        assert!(security_role_has_permission(
            Some("reader"),
            SecurityPermission::IndexRead
        ));
        assert!(!security_role_has_permission(
            Some("reader"),
            SecurityPermission::IndexWrite
        ));
        assert!(!security_role_has_permission(
            Some("reader"),
            SecurityPermission::ClusterAdmin
        ));
        assert!(security_role_has_permission(
            Some("writer"),
            SecurityPermission::IndexWrite
        ));
        assert!(!security_role_has_permission(
            Some("writer"),
            SecurityPermission::IndexRead
        ));
        assert!(!security_role_has_permission(
            Some("writer"),
            SecurityPermission::ClusterAdmin
        ));
        assert!(!security_role_has_permission(
            Some("unknown"),
            SecurityPermission::IndexRead
        ));
        let tenant_writer = SecuritySubject {
            username: "writer-a".to_string(),
            role: "writer",
            tenants: vec!["tenant-a".to_string()],
        };
        assert!(security_role_can_write_target(
            None,
            None,
            "logs-tenant-b",
            true
        ));
        assert!(security_role_can_write_target(
            Some("admin"),
            None,
            ".opensearch-security",
            true
        ));
        assert!(security_role_can_write_target(
            Some("writer"),
            None,
            "logs-tenant-b",
            false
        ));
        assert!(!security_role_can_write_target(
            Some("writer"),
            None,
            ".opensearch-security",
            true
        ));
        assert!(security_role_can_write_target(
            Some("writer"),
            Some(&tenant_writer),
            "logs-tenant-a-000001",
            false
        ));
        assert!(!security_role_can_write_target(
            Some("writer"),
            Some(&tenant_writer),
            "logs-tenant-b-000001",
            false
        ));
        assert!(!security_role_can_write_target(
            Some("reader"),
            None,
            "logs-tenant-b",
            false
        ));
    }

    #[test]
    fn secure_tenant_scoped_subjects_cannot_cross_index_tenant_boundaries() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
        env::set_var("SECURITY_ADMIN_USERNAME", "admin");
        env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
        env::remove_var("SECURITY_ADMIN_TENANTS");
        env::set_var("SECURITY_READER_USERNAME", "reader");
        env::set_var("SECURITY_READER_PASSWORD", "reader");
        env::set_var("SECURITY_READER_TENANTS", "tenant-a");
        env::set_var("SECURITY_WRITER_USERNAME", "writer");
        env::set_var("SECURITY_WRITER_PASSWORD", "writer");
        env::set_var("SECURITY_WRITER_TENANTS", "tenant-a");
        env::remove_var("SECURITY_AUTHENTICATION_USERS_FILE");

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let admin = "Basic YWRtaW46YWRtaW4=";
        let reader = "Basic cmVhZGVyOnJlYWRlcg==";
        let writer = "Basic d3JpdGVyOndyaXRlcg==";

        for index in ["logs-tenant-a-000001", "logs-tenant-b-000001"] {
            let create = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, &format!("/{index}"))
                    .with_header("Authorization", admin),
            );
            assert_eq!(create.status, 200, "create {index}");
            let seed = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, &format!("/{index}/_doc/admin-seed"))
                    .with_header("Authorization", admin)
                    .with_json_body(serde_json::json!({"message": index})),
            );
            assert_eq!(seed.status, 201, "seed {index}");
        }

        let same_tenant_read = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-tenant-a-000001/_search")
                .with_header("Authorization", reader)
                .with_json_body(serde_json::json!({"query": {"match_all": {}}})),
        );
        assert_eq!(same_tenant_read.status, 200);

        let cross_tenant_read = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-tenant-b-000001/_search")
                .with_header("Authorization", reader)
                .with_json_body(serde_json::json!({"query": {"match_all": {}}})),
        );
        assert_eq!(cross_tenant_read.status, 403);

        let same_tenant_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-tenant-a-000001/_doc/writer-doc")
                .with_header("Authorization", writer)
                .with_json_body(serde_json::json!({"message": "same tenant"})),
        );
        assert_eq!(same_tenant_write.status, 201);

        let cross_tenant_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-tenant-b-000001/_doc/writer-doc")
                .with_header("Authorization", writer)
                .with_json_body(serde_json::json!({"message": "cross tenant"})),
        );
        assert_eq!(cross_tenant_write.status, 403);

        let cross_tenant_bulk = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_bulk")
                .with_header("Authorization", writer)
                .with_header("content-type", "application/x-ndjson")
                .with_body(
                    concat!(
                        "{\"index\":{\"_index\":\"logs-tenant-b-000001\",\"_id\":\"bulk-cross\"}}\n",
                        "{\"message\":\"cross tenant bulk\"}\n"
                    )
                    .as_bytes()
                    .to_vec(),
                ),
        );
        assert_eq!(cross_tenant_bulk.status, 200);
        assert_eq!(cross_tenant_bulk.body["errors"], Value::Bool(true));
        assert_eq!(cross_tenant_bulk.body["items"][0]["index"]["status"], 403);

        env::remove_var("STEELSEARCH_SECURITY_ENABLED");
        env::remove_var("SECURITY_ADMIN_USERNAME");
        env::remove_var("SECURITY_ADMIN_PASSWORD");
        env::remove_var("SECURITY_READER_USERNAME");
        env::remove_var("SECURITY_READER_PASSWORD");
        env::remove_var("SECURITY_READER_TENANTS");
        env::remove_var("SECURITY_WRITER_USERNAME");
        env::remove_var("SECURITY_WRITER_PASSWORD");
        env::remove_var("SECURITY_WRITER_TENANTS");
    }

    #[test]
    fn secure_root_route_requires_valid_basic_auth_credentials() {
        let _lock = security_env_lock();
        unsafe {
            env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
            env::set_var("SECURITY_ADMIN_USERNAME", "admin");
            env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
            env::remove_var("SECURITY_READER_USERNAME");
            env::remove_var("SECURITY_READER_PASSWORD");
            env::remove_var("SECURITY_WRITER_USERNAME");
            env::remove_var("SECURITY_WRITER_PASSWORD");
        }

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let missing = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/"));
        assert_eq!(missing.status, 401);
        assert_eq!(
            missing.headers.get("www-authenticate").map(String::as_str),
            Some("Basic realm=\"security\" charset=\"UTF-8\"")
        );
        assert_eq!(missing.body["error"]["type"], "security_exception");
        assert_eq!(
            missing.body["error"]["reason"],
            "missing authentication credentials for REST request [/]"
        );

        let wrong = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/")
                .with_header("Authorization", "Basic YmFkOmNyZWRz"),
        );
        assert_eq!(wrong.status, 401);
        assert_eq!(wrong.body["error"]["type"], "security_exception");
        assert_eq!(
            wrong.body["error"]["reason"],
            "unable to authenticate user for REST request [/]"
        );

        let malformed = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/")
                .with_header("Authorization", "Bearer malformed-token-authz"),
        );
        assert_eq!(malformed.status, 401);
        assert_eq!(malformed.body["error"]["type"], "security_exception");
        assert_eq!(
            malformed.body["error"]["reason"],
            "unable to authenticate user for REST request [/]"
        );

        let success = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/")
                .with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
        );
        assert_eq!(success.status, 200);
        assert_eq!(success.body["name"], "steel-node");

        unsafe {
            env::remove_var("STEELSEARCH_SECURITY_ENABLED");
            env::remove_var("SECURITY_ADMIN_USERNAME");
            env::remove_var("SECURITY_ADMIN_PASSWORD");
        }
    }

    #[test]
    fn opensearch_security_plugin_apis_fail_closed_with_documented_error() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for request in [
            RestRequest::new(RestMethod::Get, "/_plugins/_security/api/account"),
            RestRequest::new(
                RestMethod::Put,
                "/_plugins/_security/api/internalusers/alice",
            )
            .with_json_body(serde_json::json!({"password": "secret"})),
            RestRequest::new(
                RestMethod::Post,
                "/_plugins/_security/api/ssl/transport/reloadcerts",
            ),
        ] {
            let response = node.handle_rest_request(request);
            assert_eq!(response.status, 501);
            assert_eq!(response.body["error"]["type"], "security_exception");
            let reason = response.body["error"]["reason"]
                .as_str()
                .expect("security error reason");
            assert!(reason.contains("OpenSearch Security plugin API"));
            assert!(reason.contains("request fails closed"));
        }
    }

    #[test]
    fn cluster_health_route_honors_wait_timeout_and_index_scope() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        {
            let mut created = node
                .created_indices_state
                .lock()
                .expect("created indices state lock poisoned");
            created.insert("logs-health-000001".to_string());
            created.insert("metrics-health-000001".to_string());
        }

        let wait_for_green = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health?wait_for_status=green&timeout=1s",
        ));
        assert_eq!(wait_for_green.status, 408);
        assert_eq!(wait_for_green.body["status"], "yellow");
        assert_eq!(wait_for_green.body["timed_out"], true);

        let wait_for_nodes = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health?wait_for_nodes=2&timeout=1s",
        ));
        assert_eq!(wait_for_nodes.status, 408);
        assert_eq!(wait_for_nodes.body["number_of_nodes"], 1);
        assert_eq!(wait_for_nodes.body["timed_out"], true);

        let targeted = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health/logs-health-*",
        ));
        assert_eq!(targeted.status, 200);
        assert_eq!(targeted.body["status"], "yellow");
        assert_eq!(targeted.body["active_primary_shards"], 1);
        assert_eq!(targeted.body["unassigned_shards"], 1);
        assert_eq!(targeted.body["timed_out"], false);
    }

    #[test]
    fn cluster_health_route_validates_request_params_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for (path, expected_reason) in [
            (
                "/_cluster/health?local=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_cluster/health?ensure_node_weighed_in=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_cluster/health?wait_for_no_relocating_shards=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_cluster/health?timeout=soon",
                "failed to parse setting [timeout] with value [soon] as a time value",
            ),
            (
                "/_cluster/health?cluster_manager_timeout=soon",
                "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value",
            ),
            (
                "/_cluster/health?wait_for_relocating_shards=0",
                "wait_for_relocating_shards has been removed, use wait_for_no_relocating_shards [true/false] instead",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "{path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
            assert_eq!(response.body["error"]["reason"], expected_reason, "{path}");
        }

        for path in [
            "/_cluster/health?wait_for_status=blue",
            "/_cluster/health?wait_for_events=soon",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "{path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
        }
    }

    #[test]
    fn cluster_health_route_distinguishes_missing_closed_and_partial_allocation_targets() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-health-open-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-health-closed-000001")
                .with_json_body(serde_json::json!({})),
        );
        let close_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-health-closed-000001/_close",
        ));
        assert_eq!(close_response.status, 200);

        let missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health/missing-health-000001",
        ));
        assert_eq!(missing.status, 404);
        assert_eq!(missing.body["error"]["type"], "index_not_found_exception");

        let closed = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health/logs-health-closed-000001",
        ));
        assert_eq!(closed.status, 200);
        assert_eq!(closed.body["status"], "red");
        assert_eq!(closed.body["active_primary_shards"], 0);
        assert_eq!(closed.body["active_shards_percent_as_number"], 0.0);

        let partial = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/health/logs-health-open-000001",
        ));
        assert_eq!(partial.status, 200);
        assert_eq!(partial.body["status"], "yellow");
        assert_eq!(partial.body["active_primary_shards"], 1);
        assert_eq!(partial.body["unassigned_shards"], 1);
    }

