        let mut indices_text_request = RestRequest::new(RestMethod::Get, "/_cat/indices/logs-*");
        indices_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        let indices_text_response = node.handle_rest_request(indices_text_request);
        let indices_text = indices_text_response
            .body
            .as_str()
            .expect("cat indices text body");
        assert!(indices_text.contains("uuid"));
        assert!(indices_text.contains("docs.deleted"));
        assert!(!indices_text.contains("dataset.size"));
        assert!(!indices_text.contains("creation.date.string"));
        assert!(indices_text.contains("logs-000001"));
        assert!(!indices_text.contains("metrics-000001"));

        let mut indices_selected_text_request =
            RestRequest::new(RestMethod::Get, "/_cat/indices/logs-*");
        indices_selected_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        indices_selected_text_request
