    #[test]
    fn cat_pit_segments_routes_serve_json_and_text_views() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let mut pit_json_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments");
        pit_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let pit_json_response = node.handle_rest_request(pit_json_request);
        assert_eq!(pit_json_response.status, 400);
        assert_eq!(
            pit_json_response.body["error"]["type"],
            "action_request_validation_exception"
        );

        let post_pit_all = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_cat/pit_segments/_all?v=true",
        ));
        assert_eq!(post_pit_all.status, 405);
        assert_eq!(
            post_pit_all.headers.get("allow").map(String::as_str),
            Some("GET")
        );
        assert_eq!(
            post_pit_all.body["error"],
            "Incorrect HTTP method for uri [/_cat/pit_segments/_all?v=true] and method [POST], allowed: [GET]"
        );

        let pit_lonely_source_type = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cat/pit_segments?source_content_type=json",
        ));
        assert_eq!(pit_lonely_source_type.status, 400);
        assert_eq!(
            pit_lonely_source_type.body["error"]["root_cause"][0]["reason"],
            "request [/_cat/pit_segments] contains unrecognized parameter: [source_content_type]"
        );

        let pit_all_lonely_source_type = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cat/pit_segments/_all?source_content_type=json",
        ));
        assert_eq!(pit_all_lonely_source_type.status, 400);
        assert_eq!(
            pit_all_lonely_source_type.body["error"]["root_cause"][0]["reason"],
            "request [/_cat/pit_segments/_all] contains unrecognized parameter: [source_content_type]"
        );

        let pit_all_source = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cat/pit_segments/_all?source=%7B%22pit_id%22%3A%22pit-missing%22%7D&source_content_type=json",
        ));
        assert_eq!(pit_all_source.status, 400);
        assert_eq!(
            pit_all_source.body["error"]["root_cause"][0]["reason"],
            "request [/_cat/pit_segments/_all] contains unrecognized parameters: [source], [source_content_type]"
        );

        let mut invalid_pit_id_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
            .with_json_body(serde_json::json!({ "pit_id": "pit-missing" }));
        invalid_pit_id_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let invalid_pit_id_response = node.handle_rest_request(invalid_pit_id_request);
        assert_eq!(invalid_pit_id_response.status, 400);
        assert_eq!(
            invalid_pit_id_response.body["error"]["reason"],
            "invalid id: [pit-missing]"
        );

        let missing_local_pit_id = build_local_pit_id(999);
        let mut missing_local_pit_id_request =
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
                .with_json_body(serde_json::json!({ "pit_id": missing_local_pit_id }));
        missing_local_pit_id_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let missing_local_pit_id_response = node.handle_rest_request(missing_local_pit_id_request);
        assert_eq!(missing_local_pit_id_response.status, 404);
        assert_eq!(
            missing_local_pit_id_response.body["error"]["root_cause"][0]["type"],
            "search_context_missing_exception"
        );

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-pit-segments-000001"
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-pit-segments-000001/_mappings")
                    .with_json_body(serde_json::json!({
                        "properties": {
                            "events": {
                                "type": "nested",
                                "properties": {
                                    "kind": { "type": "keyword" }
                                }
                            }
                        }
                    })),
            )
            .status,
            200
        );
        for (id, events) in [
            (
                "doc-1",
                serde_json::json!([{ "kind": "payment" }, { "kind": "cache" }]),
            ),
            ("doc-2", serde_json::json!([{ "kind": "shipping" }])),
        ] {
            assert_eq!(
                node.handle_rest_request(
                    RestRequest::new(
                        RestMethod::Put,
                        &format!("/logs-pit-segments-000001/_doc/{id}"),
                    )
                    .with_json_body(serde_json::json!({ "message": id, "events": events })),
                )
                .status,
                201
            );
        }
        let open_pit = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-pit-segments-000001/_search/point_in_time?keep_alive=1m",
        ));
        assert_eq!(open_pit.status, 200);
        let pit_id = open_pit.body["pit_id"].as_str().unwrap();

        let mut pit_body_json_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
            .with_json_body(serde_json::json!({ "pit_id": pit_id }));
        pit_body_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let pit_body_json_response = node.handle_rest_request(pit_body_json_request);
        assert_eq!(pit_body_json_response.status, 200);
        assert_eq!(
            pit_body_json_response.body[0]["index"],
            "logs-pit-segments-000001"
        );
        assert_eq!(pit_body_json_response.body[0]["docs.count"], "5");
        assert!(pit_body_json_response.body[0].get("id").is_none());

        let mut selected_pit_body_json_request =
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
                .with_json_body(serde_json::json!({ "pit_id": pit_id }));
        selected_pit_body_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        selected_pit_body_json_request
            .query_params
            .insert("h".to_string(), "i,seg,dc,sm,id".to_string());
        let selected_pit_body_json_response =
            node.handle_rest_request(selected_pit_body_json_request);
        assert_eq!(selected_pit_body_json_response.status, 200);
        assert_eq!(
            selected_pit_body_json_response.body[0]["i"],
            "logs-pit-segments-000001"
        );
        assert_eq!(selected_pit_body_json_response.body[0]["seg"], "_0");
        assert_eq!(selected_pit_body_json_response.body[0]["dc"], "5");
        assert_eq!(selected_pit_body_json_response.body[0]["sm"], "0");
        assert_eq!(selected_pit_body_json_response.body[0]["id"], "steel-node");
        assert!(selected_pit_body_json_response.body[0]
            .get("index")
            .is_none());

        let mut pit_short_source_content_type_request =
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments");
        pit_short_source_content_type_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        pit_short_source_content_type_request.query_params.insert(
            "source".to_string(),
            serde_json::json!({ "pit_id": pit_id }).to_string(),
        );
        pit_short_source_content_type_request
            .query_params
            .insert("source_content_type".to_string(), "json".to_string());
        let pit_short_source_content_type_response =
            node.handle_rest_request(pit_short_source_content_type_request);
        assert_eq!(pit_short_source_content_type_response.status, 400);
        assert_eq!(
            pit_short_source_content_type_response.body["error"]["root_cause"][0]["reason"],
            "invalid Content-Type header [json]"
        );

        let mut pit_source_json_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments");
        pit_source_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        pit_source_json_request.query_params.insert(
            "source".to_string(),
            serde_json::json!({ "pit_id": pit_id }).to_string(),
        );
        pit_source_json_request.query_params.insert(
            "source_content_type".to_string(),
            "application/json".to_string(),
        );
        let pit_source_json_response = node.handle_rest_request(pit_source_json_request);
        assert_eq!(pit_source_json_response.status, 200);
        assert_eq!(
            pit_source_json_response.body[0]["index"],
            "logs-pit-segments-000001"
        );
        assert_eq!(pit_source_json_response.body[0]["docs.count"], "5");

        let mut duplicate_pit_ids_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
            .with_json_body(serde_json::json!({ "pit_id": [pit_id, pit_id] }));
        duplicate_pit_ids_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let duplicate_pit_ids_response = node.handle_rest_request(duplicate_pit_ids_request);
        assert_eq!(duplicate_pit_ids_response.status, 200);
        assert_eq!(
            duplicate_pit_ids_response
                .body
                .as_array()
                .expect("cat pit segments duplicate response")
                .len(),
            1
        );

        let object_pit_segments_id = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments")
                .with_json_body(serde_json::json!({ "pit_id": { "id": pit_id } })),
        );
        assert_eq!(object_pit_segments_id.status, 400);
        assert_eq!(
            object_pit_segments_id.body["error"]["reason"],
            "pit_id element should only contain PIT identifier"
        );

        let mut pit_text_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments/_all");
        pit_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        let pit_text_response = node.handle_rest_request(pit_text_request);
        let pit_text = pit_text_response
            .body
            .as_str()
            .expect("cat pit_segments text body");
        assert!(pit_text.contains(
            "index shard prirep ip segment generation docs.count docs.deleted size size.memory committed searchable version compound"
        ));
        assert!(pit_text.contains("logs-pit-segments-000001"));
        assert!(pit_text.contains(" 5 0 0b "));

        let mut selected_pit_text_request =
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments/_all");
        selected_pit_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        selected_pit_text_request
            .query_params
            .insert("h".to_string(), "i,seg,dc,sm,id".to_string());
        let selected_pit_text_response = node.handle_rest_request(selected_pit_text_request);
        let selected_pit_text = selected_pit_text_response
            .body
            .as_str()
            .expect("selected cat pit_segments text body");
        assert_eq!(
            selected_pit_text.lines().collect::<Vec<_>>(),
            vec![
                "i seg dc sm id",
                "logs-pit-segments-000001 _0 5 0 steel-node"
            ]
        );

        let mut pit_all_request = RestRequest::new(RestMethod::Get, "/_cat/pit_segments/_all");
        pit_all_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let pit_all_response = node.handle_rest_request(pit_all_request);
        assert_eq!(pit_all_response.status, 200);
        assert_eq!(
            pit_all_response.body[0]["index"],
            "logs-pit-segments-000001"
        );
        assert_eq!(pit_all_response.body[0]["docs.count"], "5");
    }

    #[test]
    fn cat_pit_segments_prunes_expired_contexts_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let now_millis = current_epoch_millis();
        let expired_pit_id = build_local_pit_id(101);
        let active_pit_id = build_local_pit_id(102);
        {
            let mut contexts = node
                .pit_contexts
                .lock()
                .expect("pit contexts lock poisoned");
            contexts.insert(
                expired_pit_id.clone(),
                PitContext {
                    indices: vec!["logs-expired-pit-segments".to_string()],
                    documents: Arc::new(BTreeMap::new()),
                    keep_alive_millis: 1,
                    expires_at_millis: now_millis.saturating_sub(1),
                    creation_time_millis: now_millis.saturating_sub(2),
                },
            );
            contexts.insert(
                active_pit_id.clone(),
                PitContext {
                    indices: vec!["logs-active-pit-segments".to_string()],
                    documents: Arc::new(BTreeMap::new()),
                    keep_alive_millis: 60_000,
                    expires_at_millis: now_millis + 60_000,
                    creation_time_millis: now_millis,
                },
            );
        }

        let pit_all_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cat/pit_segments/_all?format=json",
        ));
        assert_eq!(pit_all_response.status, 200);
        assert_eq!(
            pit_all_response.body,
            serde_json::json!([
                {
                    "index": "logs-active-pit-segments",
                    "shard": "0",
                    "prirep": "p",
                    "ip": "127.0.0.1",
                    "id": "steel-node",
                    "segment": "_0",
                    "generation": "0",
                    "docs.count": "0",
                    "docs.deleted": "0",
                    "size": "0b",
                    "size.memory": "0",
                    "committed": "true",
                    "searchable": "true",
                    "version": "0",
                    "compound": "false"
                }
            ])
        );
        assert!(!node
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned")
            .contains_key(&expired_pit_id));

        let expired_explicit_pit_id = build_local_pit_id(103);
        {
            node.pit_contexts
                .lock()
                .expect("pit contexts lock poisoned")
                .insert(
                    expired_explicit_pit_id.clone(),
                    PitContext {
                        indices: vec!["logs-expired-explicit-pit-segments".to_string()],
                        documents: Arc::new(BTreeMap::new()),
                        keep_alive_millis: 1,
                        expires_at_millis: now_millis.saturating_sub(1),
                        creation_time_millis: now_millis.saturating_sub(2),
                    },
                );
        }
        let explicit_expired_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/_cat/pit_segments?format=json")
                .with_json_body(serde_json::json!({ "pit_id": expired_explicit_pit_id })),
        );
        assert_eq!(explicit_expired_response.status, 404);
        assert_eq!(
            explicit_expired_response.body["error"]["root_cause"][0]["type"],
            "search_context_missing_exception"
        );
        assert!(!node
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned")
            .contains_key(&build_local_pit_id(103)));
    }

    #[test]
    fn cat_recovery_routes_serve_json_text_and_target_filters() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        {
            let mut created_indices = node
                .created_indices_state
                .lock()
                .expect("created indices state lock poisoned");
            created_indices.insert("logs-000001".to_string());
            created_indices.insert("metrics-000001".to_string());
        }

        let mut recovery_json_request = RestRequest::new(RestMethod::Get, "/_cat/recovery");
        recovery_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let recovery_json_response = node.handle_rest_request(recovery_json_request);
        assert_eq!(recovery_json_response.status, 200);
        assert_eq!(
            recovery_json_response
                .body
                .as_array()
                .expect("cat recovery array")
                .len(),
            2
        );
        assert!(recovery_json_response.body[0].get("start_time").is_none());

        let mut selected_recovery_json_request =
            RestRequest::new(RestMethod::Get, "/_cat/recovery");
        selected_recovery_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        selected_recovery_json_request.query_params.insert(
            "h".to_string(),
            "i,s,start,start_millis,stop,stop_millis,t,ty,st,shost,snode,thost,tnode,rep,snap,f,fr,fp,tf,b,br,bp,tb,to,tor,top".to_string(),
        );
        let selected_recovery_json_response =
            node.handle_rest_request(selected_recovery_json_request);
        assert_eq!(selected_recovery_json_response.status, 200);
        assert_eq!(selected_recovery_json_response.body[0]["i"], "logs-000001");
        assert_eq!(selected_recovery_json_response.body[0]["start_millis"], "0");
        assert_eq!(selected_recovery_json_response.body[0]["ty"], "peer");
        assert_eq!(selected_recovery_json_response.body[0]["rep"], "n/a");
        assert!(selected_recovery_json_response.body[0]
            .get("index")
            .is_none());

        let mut recovery_text_request = RestRequest::new(RestMethod::Get, "/_cat/recovery/logs-*");
        recovery_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        let recovery_text_response = node.handle_rest_request(recovery_text_request);
        let recovery_text = recovery_text_response
            .body
            .as_str()
            .expect("cat recovery text body");
        assert!(recovery_text.contains("index shard time type stage source_host source_node target_host target_node repository snapshot files files_recovered files_percent files_total bytes bytes_recovered bytes_percent bytes_total translog_ops translog_ops_recovered translog_ops_percent"));
        assert!(recovery_text.contains("logs-000001"));
        assert!(!recovery_text.contains("metrics-000001"));

        let mut selected_recovery_text_request =
            RestRequest::new(RestMethod::Get, "/_cat/recovery/logs-*");
        selected_recovery_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        selected_recovery_text_request.query_params.insert(
            "h".to_string(),
            "i,s,start,start_millis,stop,stop_millis,t,ty,st,shost,snode,thost,tnode,rep,snap,f,fr,fp,tf,b,br,bp,tb,to,tor,top".to_string(),
        );
        let selected_recovery_text_response =
            node.handle_rest_request(selected_recovery_text_request);
        let selected_recovery_text = selected_recovery_text_response
            .body
            .as_str()
            .expect("selected cat recovery text body");
        assert_eq!(
            selected_recovery_text.lines().next(),
            Some("i s start start_millis stop stop_millis t ty st shost snode thost tnode rep snap f fr fp tf b br bp tb to tor top")
        );
        assert!(selected_recovery_text.contains(
            "logs-000001 0 1970-01-01T00:00:00.000Z 0 1970-01-01T00:00:00.000Z 0 0s peer done"
        ));
        assert!(!selected_recovery_text.contains("metrics-000001"));
    }

