    #[test]
    fn remote_transport_thread_pool_telemetry_reads_live_gate_snapshot() {
        let gate = Arc::new(RemoteTransportQueueGate::new(1, 1000));
        gate.execute_blocking(|| {
            Ok::<_, os_transport::internal_transport::InternalTransportError>(())
        })
        .unwrap();
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node-a".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        })
        .with_remote_transport_queue_gate(Arc::clone(&gate));
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });

        let mut cat_remote_transport =
            RestRequest::new(RestMethod::Get, "/_cat/thread_pool/remote_transport");
        cat_remote_transport
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_remote_transport = node.handle_rest_request(cat_remote_transport);
        assert_eq!(cat_remote_transport.status, 200);
        assert_eq!(cat_remote_transport.body[0]["node_id"], "node-a");
        assert_eq!(cat_remote_transport.body[0]["active"], "0");
        assert_eq!(cat_remote_transport.body[0]["queue"], "0");
        assert_eq!(cat_remote_transport.body[0]["rejected"], "0");
        assert_eq!(cat_remote_transport.body[0]["completed"], "1");

        let stats = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/stats"));
        assert_eq!(stats.status, 200);
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["remote_transport"]["completed"],
            1
        );
    }

    #[test]
    fn cat_plugins_route_reports_extension_registry_modules() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        })
        .with_extension_registry(ExtensionBoundaryRegistry {
            manifest_path: Some(PathBuf::from("/tmp/steelsearch-extensions.json")),
            knn_plugin_enabled: true,
            ml_commons_enabled: true,
        });

        let mut plugins_json_request = RestRequest::new(RestMethod::Get, "/_cat/plugins");
        plugins_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let plugins_json_response = node.handle_rest_request(plugins_json_request);
        assert_eq!(plugins_json_response.status, 200);
        let rows = plugins_json_response
            .body
            .as_array()
            .expect("cat plugins array");
        assert_eq!(rows.len(), 3);
        assert!(rows
            .iter()
            .any(|row| row["component"] == "steelsearch-runtime"));
        assert!(rows.iter().any(|row| row["component"] == "opensearch-knn"));
        assert!(rows
            .iter()
            .any(|row| row["component"] == "opensearch-ml-commons"));
        assert!(rows[0].get("id").is_none());
        assert!(rows[0].get("description").is_none());
        assert!(rows[0].get("classname").is_none());

        let mut selected_plugins_json_request = RestRequest::new(RestMethod::Get, "/_cat/plugins");
        selected_plugins_json_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        selected_plugins_json_request
            .query_params
            .insert("h".to_string(), "id,n,c,v,d".to_string());
        let selected_plugins_json_response =
            node.handle_rest_request(selected_plugins_json_request);
        let selected_rows = selected_plugins_json_response
            .body
            .as_array()
            .expect("selected cat plugins array");
        assert_eq!(selected_rows[0]["id"], "steel-node");
        assert_eq!(selected_rows[0]["n"], "steel-node");
        assert!(selected_rows.iter().any(|row| row["c"] == "opensearch-knn"));
        assert!(selected_rows[0].get("component").is_none());

        let mut plugins_text_request = RestRequest::new(RestMethod::Get, "/_cat/plugins");
        plugins_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        let plugins_text_response = node.handle_rest_request(plugins_text_request);
        let plugins_text = plugins_text_response
            .body
            .as_str()
            .expect("cat plugins text body");
        assert!(plugins_text.contains("name component version"));
        assert!(!plugins_text.contains("description"));
        assert!(!plugins_text.contains("classname"));
        assert!(plugins_text.contains("opensearch-knn"));
        assert!(plugins_text.contains("opensearch-ml-commons"));

        let mut selected_plugins_text_request = RestRequest::new(RestMethod::Get, "/_cat/plugins");
        selected_plugins_text_request
            .query_params
            .insert("v".to_string(), "true".to_string());
        selected_plugins_text_request
            .query_params
            .insert("h".to_string(), "id,n,c,v,d".to_string());
        let selected_plugins_text_response =
            node.handle_rest_request(selected_plugins_text_request);
        let selected_plugins_text = selected_plugins_text_response
            .body
            .as_str()
            .expect("selected cat plugins text body");
        assert_eq!(selected_plugins_text.lines().next(), Some("id n c v d"));
        assert!(selected_plugins_text.contains("steel-node steel-node opensearch-knn"));
    }

