    #[test]
    fn extension_registry_registration_table_lists_enabled_routes_and_actions() {
        let registry = ExtensionBoundaryRegistry {
            manifest_path: Some(PathBuf::from("/tmp/steelsearch-extensions.json")),
            knn_plugin_enabled: true,
            ml_commons_enabled: false,
        };
        let entries = registry.registration_table();
        assert_eq!(entries.len(), 2);
        assert!(entries.iter().any(|entry| {
            entry.module == "steelsearch-runtime"
                && entry.feature == "runtime-observability"
                && entry.rest_routes
                    == &[
                        "/_cat/plugins",
                        "/_steelsearch/dev/extensions",
                        "/_steelsearch/dev/extensions/_shutdown",
                        "/_steelsearch/dev/extensions/_recovery_failed",
                    ]
                && entry.transport_actions.is_empty()
                && entry
                    .lifecycle_hooks
                    .contains(&"sync_shared_runtime_state_from_disk")
                && entry
                    .lifecycle_hooks
                    .contains(&"refuse_task_submission_if_unavailable")
        }));
        assert!(entries.iter().any(|entry| {
            entry.module == "opensearch-knn"
                && entry.feature == "knn-rest-compatibility"
                && entry.rest_routes.contains(&"/_plugins/_knn/models")
                && entry.transport_actions.is_empty()
                && entry.lifecycle_hooks.is_empty()
        }));
        assert!(!entries
            .iter()
            .any(|entry| entry.module == "opensearch-ml-commons"));
    }

    #[test]
    fn extension_registry_uses_rust_native_extension_api_descriptors() {
        let registry = ExtensionBoundaryRegistry {
            manifest_path: Some(PathBuf::from("/tmp/steelsearch-extensions.json")),
            knn_plugin_enabled: true,
            ml_commons_enabled: true,
        };
        let descriptors = registry.rust_native_extension_descriptors();
        assert_eq!(descriptors.len(), 3);
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "steelsearch-runtime"
                && descriptor.classname == "org.steelsearch.runtime.Plugin"
                && descriptor.rest_routes
                    == &[
                        "/_cat/plugins",
                        "/_steelsearch/dev/extensions",
                        "/_steelsearch/dev/extensions/_shutdown",
                        "/_steelsearch/dev/extensions/_recovery_failed",
                    ]
                && descriptor.transport_actions.is_empty()
                && descriptor
                    .lifecycle_hooks
                    .contains(&"set_live_shutdown_in_progress")
                && descriptor
                    .lifecycle_hooks
                    .contains(&"set_shared_runtime_state_recovery_failed")
        }));
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "opensearch-knn"
                && descriptor.module == os_plugin_knn::KNN_PLUGIN_NAME
                && descriptor.feature == "knn-rest-compatibility"
                && descriptor.feature == os_plugin_knn::KNN_EXTENSION_FEATURE
                && descriptor.description.contains("Rust-native k-NN")
                && descriptor.rest_routes.contains(&"/_plugins/_knn/settings")
                && descriptor.transport_actions.is_empty()
                && descriptor.lifecycle_hooks.is_empty()
        }));
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "opensearch-ml-commons"
                && descriptor.module == os_ml_commons::ML_COMMONS_EXTENSION_MODULE
                && descriptor.feature == "ml-commons-rest-compatibility"
                && descriptor.feature == os_ml_commons::ML_COMMONS_EXTENSION_FEATURE
                && descriptor.description.contains("Rust-native ML Commons")
                && descriptor.rest_routes.contains(&"/_plugins/_ml/connectors")
                && descriptor.transport_actions.is_empty()
                && descriptor.lifecycle_hooks.is_empty()
        }));
    }

    #[test]
    fn extension_lifecycle_hooks_execute_for_activation_shutdown_and_recovery_boundaries() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        })
        .with_extension_registry(ExtensionBoundaryRegistry {
            manifest_path: Some(PathBuf::from("/tmp/steelsearch-extensions.json")),
            knn_plugin_enabled: true,
            ml_commons_enabled: true,
        });

        let activation = node.extension_lifecycle_execution_transcript();
        assert_eq!(activation.len(), 2);
        assert!(activation.iter().any(|entry| {
            entry.module == "steelsearch-runtime"
                && entry.phase == "startup"
                && entry.hook == "sync_shared_runtime_state_from_disk"
                && entry.action == "activate"
                && entry.status == "executed"
        }));
        assert!(activation.iter().any(|entry| {
            entry.module == "steelsearch-runtime"
                && entry.phase == "steady_state"
                && entry.hook == "refuse_task_submission_if_unavailable"
                && entry.action == "activate"
                && entry.status == "admitted"
        }));
        assert!(!activation
            .iter()
            .any(|entry| entry.module == "opensearch-knn"));
        assert!(!activation
            .iter()
            .any(|entry| entry.module == "opensearch-ml-commons"));
        assert!(node.refuse_task_submission_if_unavailable().is_none());

        node.deactivate_registered_extensions_for_shutdown();
        let shutdown = node.extension_lifecycle_execution_transcript();
        assert!(shutdown.iter().any(|entry| {
            entry.module == "steelsearch-runtime"
                && entry.phase == "shutdown"
                && entry.hook == "set_live_shutdown_in_progress"
                && entry.action == "deactivate"
                && entry.status == "executed"
        }));
        assert_eq!(node.runtime_lifecycle_snapshot().active_phase, "shutdown");
        let shutdown_refusal = node
            .refuse_task_submission_if_unavailable()
            .expect("shutdown lifecycle should refuse task submission");
        assert_eq!(shutdown_refusal.status, 503);

        node.mark_registered_extensions_recovery_failed();
        let recovery = node.extension_lifecycle_execution_transcript();
        assert!(recovery.iter().any(|entry| {
            entry.module == "steelsearch-runtime"
                && entry.phase == "recovery"
                && entry.hook == "set_shared_runtime_state_recovery_failed"
                && entry.action == "recovery_failed"
                && entry.status == "executed"
        }));
        assert!(node
            .runtime_lifecycle_snapshot()
            .blockers
            .contains(&"shared_runtime_state_recovery_failed".to_string()));
    }

