    #[test]
    fn rethrottle_multi_level_tasks_keep_independent_rate_readback() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![
                    ClusterManagerTaskRecord {
                        task_id: 251,
                        task: ClusterManagerTask {
                            source: "parent multi-level rethrottle probe".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                    ClusterManagerTaskRecord {
                        task_id: 252,
                        task: ClusterManagerTask {
                            source: "child multi-level rethrottle probe".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: Some("node-a:251".to_string()),
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                    ClusterManagerTaskRecord {
                        task_id: 253,
                        task: ClusterManagerTask {
                            source: "grandchild multi-level rethrottle probe".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: Some("node-a:252".to_string()),
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                ],
                ..Default::default()
            });

        let mut parent_rethrottle =
            RestRequest::new(RestMethod::Post, "/_reindex/node-a:251/_rethrottle");
        parent_rethrottle
            .query_params
            .insert("requests_per_second".to_string(), "3.0".to_string());
        let parent_rethrottle = node.handle_rest_request(parent_rethrottle);
        assert_eq!(parent_rethrottle.status, 200);
        assert_eq!(
            parent_rethrottle.body["task"]["status"]["requests_per_second"],
            serde_json::json!(3.0)
        );

        for (task_id, expected_rate) in [
            ("node-a:251", 3.0),
            ("node-a:252", -1.0),
            ("node-a:253", -1.0),
        ] {
            let get = node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                &format!("/_tasks/{task_id}"),
            ));
            assert_eq!(get.status, 200, "task {task_id}");
            assert_eq!(
                get.body["task"]["status"]["requests_per_second"],
                serde_json::json!(expected_rate),
                "task {task_id}"
            );
        }

        let mut grandchild_rethrottle =
            RestRequest::new(RestMethod::Post, "/_update_by_query/node-a:253/_rethrottle");
        grandchild_rethrottle.body = br#"{"requests_per_second":9.0}"#.to_vec();
        let grandchild_rethrottle = node.handle_rest_request(grandchild_rethrottle);
        assert_eq!(grandchild_rethrottle.status, 200);
        assert_eq!(
            grandchild_rethrottle.body["task"]["status"]["requests_per_second"],
            serde_json::json!(9.0)
        );

        let list = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(list.status, 200);
        assert_eq!(
            list.body["nodes"]["node-a"]["tasks"]["node-a:251"]["status"]["requests_per_second"],
            serde_json::json!(3.0)
        );
        assert_eq!(
            list.body["nodes"]["node-a"]["tasks"]["node-a:252"]["status"]["requests_per_second"],
            serde_json::json!(-1.0)
        );
        assert_eq!(
            list.body["nodes"]["node-a"]["tasks"]["node-a:253"]["status"]["requests_per_second"],
            serde_json::json!(9.0)
        );
    }

    #[test]
    fn reindex_route_copies_source_documents_into_destination_index() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create_source =
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-reindex-source"));
        assert_eq!(create_source.status, 200);

        let put_doc = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-reindex-source/_doc/doc-1").with_json_body(
                serde_json::json!({
                    "message": "reindex me"
                }),
            ),
        );
        assert_eq!(put_doc.status, 201);

        let reindex = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-source" },
                "dest": { "index": "logs-reindex-dest" }
            })),
        );
        assert_eq!(reindex.status, 200);
        assert_eq!(reindex.body["total"], 1);
        assert_eq!(reindex.body["created"], 1);
        assert_eq!(reindex.body["failures"], Value::Array(vec![]));

        let get_dest = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-reindex-dest/_doc/doc-1",
        ));
        assert_eq!(get_dest.status, 200);
        assert_eq!(get_dest.body["_source"]["message"], "reindex me");
    }

    #[test]
    fn reindex_route_surfaces_wildcard_source_missing_dest_and_overwrite_semantics() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-reindex-source-a"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-reindex-source-b"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-reindex-dest"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-reindex-source-a/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "message": "from source a",
                        "tenant": "tenant-a"
                    })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-reindex-source-b/_doc/doc-2")
                    .with_json_body(serde_json::json!({
                        "message": "from source b",
                        "tenant": "tenant-b"
                    })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-reindex-dest/_doc/doc-1").with_json_body(
                    serde_json::json!({
                        "message": "stale dest copy",
                        "tenant": "tenant-old"
                    })
                ),
            )
            .status,
            201
        );

        let missing_dest = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-source-*" }
            })),
        );
        assert_eq!(missing_dest.status, 400);
        assert_eq!(
            missing_dest.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            missing_dest.body["error"]["reason"],
            "reindex dest.index is required"
        );

        let scripted_reindex = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-source-a" },
                "dest": { "index": "logs-reindex-dest" },
                "script": {
                    "source": "ctx._source.message = 'scripted reindex'"
                }
            })),
        );
        assert_eq!(scripted_reindex.status, 200);
        assert_eq!(scripted_reindex.body["total"], 1);
        assert_eq!(scripted_reindex.body["updated"], 1);
        let scripted_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-reindex-dest/_doc/doc-1",
        ));
        assert_eq!(scripted_doc.status, 200);
        assert_eq!(
            scripted_doc.body["_source"]["message"],
            Value::String("scripted reindex".to_string())
        );

        let scripted_param_reindex = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-source-a" },
                "dest": { "index": "logs-reindex-script-params-dest" },
                "script": {
                    "source": "ctx._source.processed = params.processed",
                    "params": {
                        "processed": true
                    }
                }
            })),
        );
        assert_eq!(scripted_param_reindex.status, 200);
        assert_eq!(scripted_param_reindex.body["total"], 1);
        assert_eq!(scripted_param_reindex.body["created"], 1);
        let scripted_param_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-reindex-script-params-dest/_doc/doc-1",
        ));
        assert_eq!(scripted_param_doc.status, 200);
        assert_eq!(
            scripted_param_doc.body["_source"]["processed"],
            Value::Bool(true)
        );

        let wildcard_reindex = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-source-*" },
                "dest": { "index": "logs-reindex-dest" }
            })),
        );
        assert_eq!(wildcard_reindex.status, 200);
        assert_eq!(wildcard_reindex.body["total"], 2);
        assert_eq!(wildcard_reindex.body["updated"], 1);
        assert_eq!(wildcard_reindex.body["created"], 1);
        assert_eq!(wildcard_reindex.body["batches"], 1);
        assert_eq!(wildcard_reindex.body["failures"], Value::Array(vec![]));

        let overwritten_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-reindex-dest/_doc/doc-1",
        ));
        assert_eq!(overwritten_doc.status, 200);
        assert_eq!(overwritten_doc.body["_source"]["message"], "from source a");
        assert_eq!(overwritten_doc.body["_source"]["tenant"], "tenant-a");

        let created_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-reindex-dest/_doc/doc-2",
        ));
        assert_eq!(created_doc.status, 200);
        assert_eq!(created_doc.body["_source"]["message"], "from source b");
        assert_eq!(created_doc.body["_source"]["tenant"], "tenant-b");
    }

    #[test]
    fn reindex_route_honors_destination_routing_and_require_alias() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for index in [
            "logs-reindex-routing-source",
            "logs-reindex-routing-keep",
            "logs-reindex-routing-discard",
            "logs-reindex-routing-forced",
            "logs-reindex-routing-alias-target",
        ] {
            assert_eq!(
                node.handle_rest_request(RestRequest::new(RestMethod::Put, &format!("/{index}")))
                    .status,
                200
            );
        }
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-reindex-routing-source/_doc/doc-a?routing=tenant-a",
                )
                .with_json_body(serde_json::json!({
                    "message": "tenant a",
                    "tenant": "tenant-a"
                })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-reindex-routing-source/_doc/doc-b?routing=tenant-b",
                )
                .with_json_body(serde_json::json!({
                    "message": "tenant b",
                    "tenant": "tenant-b"
                })),
            )
            .status,
            201
        );

        let invalid_routing = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-routing-source" },
                "dest": {
                    "index": "logs-reindex-routing-keep",
                    "routing": "copy"
                }
            })),
        );
        assert_eq!(invalid_routing.status, 400);
        assert_eq!(
            invalid_routing.body["error"]["type"],
            "action_request_validation_exception"
        );
        assert_eq!(
            invalid_routing.body["error"]["reason"],
            "Validation Failed: 1: routing must be unset, [keep], [discard] or [=<some new value>];"
        );

        let keep = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-routing-source" },
                "dest": {
                    "index": "logs-reindex-routing-keep",
                    "routing": "keep"
                }
            })),
        );
        assert_eq!(keep.status, 200);
        assert_eq!(keep.body["created"], 2);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-keep/_doc/doc-a?routing=tenant-a",
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-keep/_doc/doc-a?routing=tenant-b",
            ))
            .status,
            404
        );

        let discard = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-routing-source" },
                "dest": {
                    "index": "logs-reindex-routing-discard",
                    "routing": "discard"
                }
            })),
        );
        assert_eq!(discard.status, 200);
        assert_eq!(discard.body["created"], 2);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-discard/_doc/doc-a",
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-discard/_doc/doc-a?routing=tenant-a",
            ))
            .status,
            404
        );

        let forced = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": { "index": "logs-reindex-routing-source" },
                "dest": {
                    "index": "logs-reindex-routing-forced",
                    "routing": "=tenant-z"
                }
            })),
        );
        assert_eq!(forced.status, 200);
        assert_eq!(forced.body["created"], 2);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-forced/_doc/doc-a?routing=tenant-z",
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-forced/_doc/doc-a?routing=tenant-a",
            ))
            .status,
            404
        );

        let require_alias_on_concrete = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex?require_alias=true").with_json_body(
                serde_json::json!({
                    "source": { "index": "logs-reindex-routing-source" },
                    "dest": { "index": "logs-reindex-routing-forced" }
                }),
            ),
        );
        assert_eq!(require_alias_on_concrete.status, 404);
        assert_eq!(
            require_alias_on_concrete.body["error"]["reason"],
            "[require_alias] request flag is [true] and [logs-reindex-routing-forced] is not an alias"
        );

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-reindex-routing-alias-target/_alias/logs-reindex-routing-write",
            ))
            .status,
            200
        );
        let require_alias_on_alias = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex?require_alias=true").with_json_body(
                serde_json::json!({
                    "source": { "index": "logs-reindex-routing-source" },
                    "dest": {
                        "index": "logs-reindex-routing-write",
                        "routing": "discard"
                    }
                }),
            ),
        );
        assert_eq!(require_alias_on_alias.status, 200);
        assert_eq!(require_alias_on_alias.body["created"], 2);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-reindex-routing-alias-target/_doc/doc-a",
            ))
            .status,
            200
        );
    }

    #[test]
    fn head_index_route_serves_bodyless_exact_wildcard_and_missing_existence() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-head-index-000001"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-head-index-000002"))
                .status,
            200
        );

        for (path, expected_status) in [
            ("/logs-head-index-000001", 200),
            ("/logs-head-index-*", 200),
            ("/missing-head-index-000001", 404),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Head, path));
            assert_eq!(response.status, expected_status, "path {path}");
            assert!(response.body.is_null(), "path {path}");
        }
    }

    #[test]
    fn delete_by_query_route_surfaces_matched_unmatched_and_repeated_delete_semantics() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-delete-query-probe"
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-delete-query-probe/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "tenant": "tenant-a",
                        "message": "delete me"
                    })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-delete-query-probe/_doc/doc-2")
                    .with_json_body(serde_json::json!({
                        "tenant": "tenant-b",
                        "message": "keep me"
                    })),
            )
            .status,
            201
        );

        let matched = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-delete-query-probe/_delete_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-a" }
                }
            })),
        );
        assert_eq!(matched.status, 200);
        assert_eq!(matched.body["total"], 1);
        assert_eq!(matched.body["deleted"], 1);
        assert_eq!(matched.body["batches"], 1);

        let deleted_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-delete-query-probe/_doc/doc-1",
        ));
        assert_eq!(deleted_doc.status, 404);

        let unmatched = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-delete-query-probe/_delete_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-z" }
                }
            })),
        );
        assert_eq!(unmatched.status, 200);
        assert_eq!(unmatched.body["total"], 0);
        assert_eq!(unmatched.body["deleted"], 0);
        assert_eq!(unmatched.body["batches"], 0);

        let repeated = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-delete-query-probe/_delete_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-a" }
                }
            })),
        );
        assert_eq!(repeated.status, 200);
        assert_eq!(repeated.body["total"], 0);
        assert_eq!(repeated.body["deleted"], 0);
        assert_eq!(repeated.body["batches"], 0);

        let remaining_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-delete-query-probe/_doc/doc-2",
        ));
        assert_eq!(remaining_doc.status, 200);
        assert_eq!(remaining_doc.body["_source"]["message"], "keep me");

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-delete-query-probe/_doc/doc-routed-a?routing=tenant-a",
                )
                .with_json_body(serde_json::json!({
                    "tenant": "tenant-routed",
                    "message": "delete routed a"
                })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-delete-query-probe/_doc/doc-routed-b?routing=tenant-b",
                )
                .with_json_body(serde_json::json!({
                    "tenant": "tenant-routed",
                    "message": "keep routed b"
                })),
            )
            .status,
            201
        );

        let routed = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-delete-query-probe/_delete_by_query?routing=tenant-a",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-routed" }
                }
            })),
        );
        assert_eq!(routed.status, 200);
        assert_eq!(routed.body["total"], 2);
        assert_eq!(routed.body["deleted"], 2);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-delete-query-probe/_doc/doc-routed-a?routing=tenant-a",
            ))
            .status,
            404
        );
        let routed_remaining = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-delete-query-probe/_doc/doc-routed-b?routing=tenant-b",
        ));
        assert_eq!(routed_remaining.status, 404);
    }

    #[test]
    fn update_by_query_route_surfaces_matched_unmatched_and_noop_semantics() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-update-query-probe"
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-update-query-probe/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "tenant": "tenant-a",
                        "processed": false
                    })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-update-query-probe/_doc/doc-2")
                    .with_json_body(serde_json::json!({
                        "tenant": "tenant-b",
                        "processed": false
                    })),
            )
            .status,
            201
        );

        let matched = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-query-probe/_update_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-a" }
                },
                "script": {
                    "source": "ctx._source.processed = true"
                }
            })),
        );
        assert_eq!(matched.status, 200);
        assert_eq!(matched.body["total"], 1);
        assert_eq!(matched.body["updated"], 1);
        assert_eq!(matched.body["noops"], 0);

        let unmatched = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-query-probe/_update_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-z" }
                },
                "script": {
                    "source": "ctx._source.processed = true"
                }
            })),
        );
        assert_eq!(unmatched.status, 200);
        assert_eq!(unmatched.body["total"], 0);
        assert_eq!(unmatched.body["updated"], 0);
        assert_eq!(unmatched.body["noops"], 0);
        assert_eq!(unmatched.body["batches"], 0);

        let repeated = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-query-probe/_update_by_query",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-a" }
                },
                "script": {
                    "source": "ctx._source.processed = true"
                }
            })),
        );
        assert_eq!(repeated.status, 200);
        assert_eq!(repeated.body["total"], 1);
        assert_eq!(repeated.body["updated"], 1);
        assert_eq!(repeated.body["noops"], 0);

        let updated = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-update-query-probe/_doc/doc-1",
        ));
        assert_eq!(updated.status, 200);
        assert_eq!(updated.body["_source"]["processed"], Value::Bool(true));

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-update-query-probe/_doc/doc-routed-a?routing=tenant-a",
                )
                .with_json_body(serde_json::json!({
                    "tenant": "tenant-routed",
                    "processed": false
                })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-update-query-probe/_doc/doc-routed-b?routing=tenant-b",
                )
                .with_json_body(serde_json::json!({
                    "tenant": "tenant-routed",
                    "processed": false
                })),
            )
            .status,
            201
        );
        let routed = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-query-probe/_update_by_query?routing=tenant-a",
            )
            .with_json_body(serde_json::json!({
                "query": {
                    "term": { "tenant": "tenant-routed" }
                },
                "script": {
                    "source": "ctx._source.processed = true"
                }
            })),
        );
        assert_eq!(routed.status, 200);
        assert_eq!(routed.body["total"], 2);
        assert_eq!(routed.body["updated"], 2);

        let routed_updated = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-update-query-probe/_doc/doc-routed-a?routing=tenant-a",
        ));
        assert_eq!(routed_updated.status, 200);
        assert_eq!(
            routed_updated.body["_source"]["processed"],
            Value::Bool(true)
        );
        let routed_untouched = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-update-query-probe/_doc/doc-routed-b?routing=tenant-b",
        ));
        assert_eq!(routed_untouched.status, 200);
        assert_eq!(
            routed_untouched.body["_source"]["processed"],
            Value::Bool(true)
        );
    }

    #[test]
    fn routed_search_and_by_query_routes_select_shards_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let routed_value = "tenant-a";
        let routed_shard = opensearch_routing_shard(routed_value, 3);
        let different_routing = (0..100)
            .map(|candidate| format!("tenant-other-{candidate}"))
            .find(|candidate| opensearch_routing_shard(candidate, 3) != routed_shard)
            .expect("routing value on a different shard");

        for index in [
            "logs-routing-search",
            "logs-routing-count",
            "logs-routing-delete-by-query",
            "logs-routing-update-by-query",
        ] {
            assert_eq!(
                node.handle_rest_request(
                    RestRequest::new(RestMethod::Put, &format!("/{index}")).with_json_body(
                        serde_json::json!({
                            "settings": {
                                "index": {
                                    "number_of_shards": 3,
                                    "number_of_replicas": 0
                                }
                            },
                            "mappings": {
                                "properties": {
                                    "tenant": { "type": "keyword" },
                                    "processed": { "type": "boolean" }
                                }
                            }
                        }),
                    ),
                )
                .status,
                200,
                "{index}"
            );
            assert_eq!(
                node.handle_rest_request(
                    RestRequest::new(
                        RestMethod::Put,
                        &format!("/{index}/_doc/doc-a?routing={routed_value}"),
                    )
                    .with_json_body(serde_json::json!({
                        "tenant": "same-query-value",
                        "processed": false
                    })),
                )
                .status,
                201,
                "{index}"
            );
            assert_eq!(
                node.handle_rest_request(
                    RestRequest::new(
                        RestMethod::Put,
                        &format!("/{index}/_doc/doc-b?routing={different_routing}"),
                    )
                    .with_json_body(serde_json::json!({
                        "tenant": "same-query-value",
                        "processed": false
                    })),
                )
                .status,
                201,
                "{index}"
            );
        }

        let routed_search = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                &format!("/logs-routing-search/_search?routing={routed_value}"),
            )
            .with_json_body(serde_json::json!({
                "query": { "term": { "tenant": "same-query-value" } },
                "size": 10
            })),
        );
        assert_eq!(routed_search.status, 200);
        assert_eq!(routed_search.body["hits"]["total"]["value"], 1);
        assert_eq!(routed_search.body["hits"]["hits"][0]["_id"], "doc-a");

        let routed_count = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                &format!("/logs-routing-count/_count?routing={routed_value}"),
            )
            .with_json_body(serde_json::json!({
                "query": { "term": { "tenant": "same-query-value" } }
            })),
        );
        assert_eq!(routed_count.status, 200);
        assert_eq!(routed_count.body["count"], 1);

        let routed_delete = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                &format!("/logs-routing-delete-by-query/_delete_by_query?routing={routed_value}"),
            )
            .with_json_body(serde_json::json!({
                "query": { "term": { "tenant": "same-query-value" } }
            })),
        );
        assert_eq!(routed_delete.status, 200);
        assert_eq!(routed_delete.body["total"], 1);
        assert_eq!(routed_delete.body["deleted"], 1);
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                "/logs-routing-delete-by-query/_doc/doc-a?routing=tenant-a",
            ))
            .status,
            404
        );
        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                &format!("/logs-routing-delete-by-query/_doc/doc-b?routing={different_routing}"),
            ))
            .status,
            200
        );

        let routed_update = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                &format!("/logs-routing-update-by-query/_update_by_query?routing={routed_value}"),
            )
            .with_json_body(serde_json::json!({
                "query": { "term": { "tenant": "same-query-value" } },
                "script": { "source": "ctx._source.processed = true" }
            })),
        );
        assert_eq!(routed_update.status, 200);
        assert_eq!(routed_update.body["total"], 1);
        assert_eq!(routed_update.body["updated"], 1);

        let updated_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-routing-update-by-query/_doc/doc-a?routing=tenant-a",
        ));
        assert_eq!(updated_doc.status, 200);
        assert_eq!(updated_doc.body["_source"]["processed"], Value::Bool(true));
        let untouched_doc = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            &format!("/logs-routing-update-by-query/_doc/doc-b?routing={different_routing}"),
        ));
        assert_eq!(untouched_doc.status, 200);
        assert_eq!(
            untouched_doc.body["_source"]["processed"],
            Value::Bool(false)
        );
    }

    #[test]
    fn create_doc_routes_create_once_and_conflict_on_repeat() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for path in [
            "/logs-create-probe/_create/doc-put",
            "/logs-create-probe/_create/doc-post",
        ] {
            let method = if path.ends_with("doc-put") {
                RestMethod::Put
            } else {
                RestMethod::Post
            };
            let created = node.handle_rest_request(RestRequest::new(method, path).with_json_body(
                serde_json::json!({
                    "message": "created once"
                }),
            ));
            assert_eq!(created.status, 201, "path {path}");
            assert_eq!(created.body["result"], "created", "path {path}");

            let conflict = node.handle_rest_request(RestRequest::new(method, path).with_json_body(
                serde_json::json!({
                    "message": "created twice"
                }),
            ));
            assert_eq!(conflict.status, 409, "path {path}");
            assert_eq!(
                conflict.body["error"]["type"],
                Value::String("version_conflict_engine_exception".to_string()),
                "path {path}"
            );
        }

        let refresh_created = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-create-probe/_create/doc-refresh?refresh=true",
            )
            .with_json_body(serde_json::json!({
                "message": "refresh-visible"
            })),
        );
        assert_eq!(refresh_created.status, 201);
        assert_eq!(refresh_created.body["forced_refresh"], Value::Bool(true));

        let refresh_visible = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-create-probe/_doc/doc-refresh?realtime=false",
        ));
        assert_eq!(refresh_visible.status, 200);
        assert_eq!(
            refresh_visible.body["_source"]["message"],
            "refresh-visible"
        );
    }

    #[test]
    fn update_doc_routes_surface_missing_noop_and_script_update_semantics() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-update-probe"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-update-probe/_doc/doc-1").with_json_body(
                    serde_json::json!({
                        "message": "stateful route probe",
                        "tenant": "tenant-a"
                    }),
                ),
            )
            .status,
            201
        );

        let missing = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-update-probe/_update/missing-doc")
                .with_json_body(serde_json::json!({
                    "doc": { "processed": true }
                })),
        );
        assert_eq!(missing.status, 404);
        assert_eq!(missing.body["error"]["type"], "document_missing_exception");

        let noop = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-update-probe/_update/doc-1").with_json_body(
                serde_json::json!({
                    "doc": {
                        "message": "stateful route probe",
                        "tenant": "tenant-a"
                    }
                }),
            ),
        );
        assert_eq!(noop.status, 200);
        assert_eq!(noop.body["result"], "noop");
        assert_eq!(noop.body["_version"], 1);

        let overlapping_source_filters = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-probe/_update/doc-1?_source_includes=message,tenant&_source_excludes=tenant",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "processed": false
                }
            })),
        );
        assert_eq!(overlapping_source_filters.status, 400);
        assert_eq!(
            overlapping_source_filters.body["error"]["reason"],
            "The same entry [tenant] cannot be both included and excluded in _source."
        );

        let scripted = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-probe/_update/doc-1?refresh=true",
            )
            .with_json_body(serde_json::json!({
                "script": {
                    "source": "ctx._source.processed = params.processed",
                    "params": {
                        "processed": true
                    }
                }
            })),
        );
        assert_eq!(scripted.status, 200);
        assert_eq!(scripted.body["result"], "updated");
        assert_eq!(scripted.body["_version"], 2);
        assert_eq!(scripted.body["forced_refresh"], Value::Bool(true));

        let update_with_source = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-probe/_update/doc-1?_source=processed&refresh=true",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "processed": false,
                    "visible": true
                }
            })),
        );
        assert_eq!(update_with_source.status, 200);
        assert_eq!(update_with_source.body["result"], "updated");
        assert_eq!(
            update_with_source.body["get"]["_source"],
            serde_json::json!({
                "processed": false
            })
        );

        let updated = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-update-probe/_doc/doc-1?realtime=false",
        ));
        assert_eq!(updated.status, 200);
        assert_eq!(updated.body["_source"]["processed"], Value::Bool(false));

        let plain_upsert = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-probe/_update/doc-plain-upsert",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "message": "ignored-doc-patch"
                },
                "upsert": {
                    "message": "plain-upsert",
                    "level": "notice"
                }
            })),
        );
        assert_eq!(plain_upsert.status, 201);
        assert_eq!(plain_upsert.body["result"], "created");

        let plain_upsert_readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-update-probe/_doc/doc-plain-upsert",
        ));
        assert_eq!(plain_upsert_readback.status, 200);
        assert_eq!(
            plain_upsert_readback.body["_source"],
            serde_json::json!({
                "message": "plain-upsert",
                "level": "notice"
            })
        );

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-update-stored-fields").with_json_body(
                    serde_json::json!({
                        "mappings": {
                            "properties": {
                                "foo": { "type": "keyword", "store": true }
                            }
                        }
                    }),
                ),
            )
            .status,
            200
        );
        let update_with_stored_fields = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-update-stored-fields/_update/doc-1?stored_fields=foo",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "foo": "baz"
                },
                "upsert": {
                    "foo": "bar"
                }
            })),
        );
        assert_eq!(update_with_stored_fields.status, 400);
        assert_eq!(
            update_with_stored_fields.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            update_with_stored_fields.body["error"]["reason"],
            "request [/logs-update-stored-fields/_update/doc-1] contains unrecognized parameter: [stored_fields]"
        );
    }

    #[test]
    fn single_doc_get_and_head_routes_match_opensearch_options() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-get-options-probe"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-get-options-probe/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "message": "baseline",
                        "tenant": "tenant-a"
                    })),
            )
            .status,
            201
        );

        let head_existing = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/logs-get-options-probe/_doc/doc-1",
        ));
        assert_eq!(head_existing.status, 200);
        assert_eq!(head_existing.body, Value::Null);

        let head_missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/logs-get-options-probe/_doc/missing-doc",
        ));
        assert_eq!(head_missing.status, 404);
        assert_eq!(head_missing.body, Value::Null);

        let stored_fields = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-get-options-probe/_doc/doc-1?stored_fields=tenant",
        ));
        assert_eq!(stored_fields.status, 200);
        assert_eq!(stored_fields.body["found"], Value::Bool(true));
        assert!(stored_fields.body.get("_source").is_none());
        assert!(stored_fields.body.get("fields").is_none());

        let legacy_fields = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-get-options-probe/_doc/doc-1?fields=tenant",
        ));
        assert_eq!(legacy_fields.status, 400);
        assert_eq!(
            legacy_fields.body["error"]["type"],
            Value::String("illegal_argument_exception".to_string())
        );
        assert_eq!(
            legacy_fields.body["error"]["reason"],
            Value::String(
                "the parameter [fields] is no longer supported, please use [stored_fields] to retrieve stored fields or [_source] to load the field from _source"
                    .to_string()
            )
        );

        let legacy_fields_head = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/logs-get-options-probe/_doc/doc-1?fields=tenant",
        ));
        assert_eq!(legacy_fields_head.status, 400);
        assert_eq!(legacy_fields_head.body, Value::Null);
    }

    #[test]
    fn single_doc_routes_surface_conflict_and_routing_negative_cases() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-write-negatives"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-write-negatives/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "message": "baseline",
                        "tenant": "tenant-a"
                    })),
            )
            .status,
            201
        );

        let create_conflict = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-write-negatives/_create/doc-1")
                .with_json_body(serde_json::json!({
                    "message": "duplicate create"
                })),
        );
        assert_eq!(create_conflict.status, 409);
        assert_eq!(
            create_conflict.body["error"]["type"],
            "version_conflict_engine_exception"
        );

        let stale_seq_term = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives/_doc/doc-1?if_seq_no=7&if_primary_term=1",
            )
            .with_json_body(serde_json::json!({
                "message": "stale write"
            })),
        );
        assert_eq!(stale_seq_term.status, 409);
        assert_eq!(
            stale_seq_term.body["error"]["type"],
            "version_conflict_engine_exception"
        );

        let missing_primary_term = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives/_doc/doc-1?if_seq_no=0",
            )
            .with_json_body(serde_json::json!({
                "message": "missing primary term"
            })),
        );
        assert_eq!(missing_primary_term.status, 400);
        assert_eq!(
            missing_primary_term.body["error"]["reason"],
            "Validation Failed: 1: ifSeqNo is set, but primary term is [0];"
        );

        let missing_seq_no = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/logs-write-negatives/_doc/doc-1?if_primary_term=1",
        ));
        assert_eq!(missing_seq_no.status, 400);
        assert_eq!(
            missing_seq_no.body["error"]["reason"],
            "Validation Failed: 1: ifSeqNo is unassigned, but primary term is [1];"
        );

        let delete_missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/logs-write-negatives/_doc/missing-doc",
        ));
        assert_eq!(delete_missing.status, 404);
        assert_eq!(delete_missing.body["_index"], "logs-write-negatives");
        assert_eq!(delete_missing.body["_id"], "missing-doc");
        assert_eq!(delete_missing.body["result"], "not_found");

        let create_with_occ = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives/_create/doc-occ?if_seq_no=0&if_primary_term=1",
            )
            .with_json_body(serde_json::json!({
                "message": "create with occ"
            })),
        );
        assert_eq!(create_with_occ.status, 400);
        assert_eq!(
            create_with_occ.body["error"]["reason"],
            "Validation Failed: 1: create operations do not support compare and set. use index instead;"
        );

        let update_with_version = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-write-negatives/_update/doc-1?version=1",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "processed": true
                }
            })),
        );
        assert_eq!(update_with_version.status, 400);
        assert_eq!(
            update_with_version.body["error"]["reason"],
            "Validation Failed: 1: internal versioning can not be used for optimistic concurrency control. Please use `if_seq_no` and `if_primary_term` instead;"
        );

        let update_upsert_with_occ = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-write-negatives/_update/doc-missing?if_seq_no=0&if_primary_term=1",
            )
            .with_json_body(serde_json::json!({
                "upsert": {
                    "message": "upsert with occ"
                }
            })),
        );
        assert_eq!(update_upsert_with_occ.status, 400);
        assert_eq!(
            update_upsert_with_occ.body["error"]["reason"],
            "Validation Failed: 1: upsert requests don't support `if_seq_no` and `if_primary_term`;"
        );

        let require_alias_on_concrete = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives/_doc/doc-require-alias?require_alias=true",
            )
            .with_json_body(serde_json::json!({
                "message": "concrete target should fail"
            })),
        );
        assert_eq!(require_alias_on_concrete.status, 404);
        assert_eq!(
            require_alias_on_concrete.body["error"]["type"],
            "index_not_found_exception"
        );
        assert_eq!(
            require_alias_on_concrete.body["error"]["reason"],
            "[require_alias] request flag is [true] and [logs-write-negatives] is not an alias"
        );

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives/_alias/logs-write-negatives-alias",
            ))
            .status,
            200
        );
        let require_alias_on_alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-write-negatives-alias/_doc/doc-require-alias?require_alias=true",
            )
            .with_json_body(serde_json::json!({
                "message": "alias target succeeds"
            })),
        );
        assert_eq!(require_alias_on_alias.status, 201);
        let update_require_alias_on_alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-write-negatives-alias/_update/doc-require-alias?require_alias=true",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "processed": true
                }
            })),
        );
        assert_eq!(update_require_alias_on_alias.status, 200);

        let wrong_routing = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-write-negatives/_update/doc-1?routing=tenant-route",
            )
            .with_json_body(serde_json::json!({
                "doc": {
                    "processed": true
                }
            })),
        );
        assert_eq!(wrong_routing.status, 404);
        assert_eq!(
            wrong_routing.body["error"]["type"],
            "document_missing_exception"
        );
    }

    #[test]
    fn routed_get_and_mget_stored_fields_surface_routing_meta_field() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-routing-meta").with_json_body(
                    serde_json::json!({
                        "settings": {
                            "index": {
                                "number_of_shards": 5,
                                "number_of_replicas": 0
                            }
                        }
                    }),
                ),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-routing-meta/_doc/1?routing=5")
                    .with_json_body(serde_json::json!({
                        "foo": "bar"
                    })),
            )
            .status,
            201
        );

        let routed_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-routing-meta/_doc/1?routing=5&stored_fields=_routing",
        ));
        assert_eq!(routed_get.status, 200);
        assert_eq!(routed_get.body["found"], Value::Bool(true));
        assert_eq!(routed_get.body["_routing"], Value::String("5".to_string()));
        assert!(routed_get.body.get("_source").is_none());

        let missing_without_routing = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-routing-meta/_doc/1",
        ));
        assert_eq!(missing_without_routing.status, 404);
        assert_eq!(missing_without_routing.body["found"], Value::Bool(false));

        assert_eq!(
            node.handle_rest_request(RestRequest::new(
                RestMethod::Put,
                "/logs-routing-meta-one-shard"
            ))
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(
                    RestMethod::Put,
                    "/logs-routing-meta-one-shard/_doc/1?routing=tenant-a",
                )
                .with_json_body(serde_json::json!({
                    "foo": "one-shard"
                })),
            )
            .status,
            201
        );
        let same_shard_without_routing = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-routing-meta-one-shard/_doc/1",
        ));
        assert_eq!(same_shard_without_routing.status, 200);
        assert_eq!(same_shard_without_routing.body["found"], Value::Bool(true));

        let routed_mget = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-routing-meta/_mget?stored_fields=_routing",
            )
            .with_json_body(serde_json::json!({
                "docs": [
                    { "_id": "1" },
                    { "_id": "1", "routing": "4" },
                    { "_id": "1", "routing": "5" }
                ]
            })),
        );
        assert_eq!(routed_mget.status, 200);
        let docs = routed_mget.body["docs"].as_array().unwrap();
        assert_eq!(docs[0]["found"], Value::Bool(false));
        assert_eq!(docs[1]["found"], Value::Bool(false));
        assert_eq!(docs[2]["found"], Value::Bool(true));
        assert_eq!(docs[2]["_routing"], Value::String("5".to_string()));
    }

    #[test]
    fn get_and_mget_stored_fields_return_stored_source_fields_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-stored-fields").with_json_body(
                    serde_json::json!({
                        "mappings": {
                            "properties": {
                                "foo": { "type": "keyword", "store": true },
                                "count": { "type": "integer", "store": true },
                                "tenant": { "type": "keyword" }
                            }
                        }
                    }),
                ),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-stored-fields/_doc/1").with_json_body(
                    serde_json::json!({
                        "foo": "bar",
                        "count": 1,
                        "tenant": "tenant-a"
                    }),
                ),
            )
            .status,
            201
        );

        let get_foo = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-stored-fields/_doc/1?stored_fields=foo",
        ));
        assert_eq!(get_foo.status, 200);
        assert_eq!(get_foo.body["fields"]["foo"], serde_json::json!(["bar"]));
        assert!(get_foo.body.get("_source").is_none());

        let get_with_source = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-stored-fields/_doc/1?stored_fields=foo,count,_source",
        ));
        assert_eq!(get_with_source.status, 200);
        assert_eq!(
            get_with_source.body["fields"],
            serde_json::json!({
                "foo": ["bar"],
                "count": [1]
            })
        );
        assert_eq!(get_with_source.body["_source"]["foo"], "bar");

        let mget = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-stored-fields/_mget").with_json_body(
                serde_json::json!({
                    "docs": [
                        { "_id": "1" },
                        { "_id": "1", "stored_fields": "foo" },
                        { "_id": "1", "stored_fields": ["foo", "_source"] }
                    ]
                }),
            ),
        );
        assert_eq!(mget.status, 200);
        let docs = mget.body["docs"].as_array().unwrap();
        assert_eq!(docs[0]["_source"]["foo"], "bar");
        assert!(docs[0].get("fields").is_none());
        assert_eq!(docs[1]["fields"]["foo"], serde_json::json!(["bar"]));
        assert!(docs[1].get("_source").is_none());
        assert_eq!(docs[2]["fields"]["foo"], serde_json::json!(["bar"]));
        assert_eq!(docs[2]["_source"]["foo"], "bar");

        let overlap = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-stored-fields/_mget?_source_includes=foo,tenant&_source_excludes=tenant",
            )
            .with_json_body(serde_json::json!({
                "docs": [
                    { "_id": "1" }
                ]
            })),
        );
        assert_eq!(overlap.status, 400);
        assert_eq!(
            overlap.body["error"]["reason"],
            "The same entry [tenant] cannot be both included and excluded in _source."
        );
    }

