    #[test]
    fn root_alias_route_supports_global_get_and_put_contracts() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-root-alias-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);
        let create_second = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-root-alias-000002")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create_second.status, 200);

        let put_alias = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_alias").with_json_body(serde_json::json!({
                "actions": [
                    {
                        "add": {
                            "index": "logs-root-alias-000001",
                            "alias": "logs-root-read",
                            "is_write_index": true
                        }
                    }
                ]
            })),
        );
        assert_eq!(put_alias.status, 200);
        assert_eq!(put_alias.body["acknowledged"], Value::Bool(true));

        let readback = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias"));
        assert_eq!(readback.status, 200);
        assert_eq!(
            readback.body["logs-root-alias-000001"]["aliases"]["logs-root-read"]["is_write_index"],
            Value::Bool(true)
        );

        let readback_with_options = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias?local=true&ignore_unavailable=false&allow_no_indices=true&ignore_throttled=false&expand_wildcards=open,hidden&cluster_manager_timeout=30s&master_timeout=30s",
        ));
        assert_eq!(readback_with_options.status, 200);
        assert_eq!(
            readback_with_options.body["logs-root-alias-000001"]["aliases"]["logs-root-read"]
                ["is_write_index"],
            Value::Bool(true)
        );

        let unknown_param =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias?foo=bar"));
        assert_eq!(unknown_param.status, 400);
        assert_eq!(
            unknown_param.body["error"]["reason"],
            "request [/_alias] contains unrecognized parameter: [foo]"
        );

        let invalid_bool =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias?local=maybe"));
        assert_eq!(invalid_bool.status, 400);
        assert_eq!(
            invalid_bool.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let invalid_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias?cluster_manager_timeout=bogus",
        ));
        assert_eq!(invalid_timeout.status, 400);
        assert_eq!(
            invalid_timeout.body["error"]["reason"],
            "failed to parse setting [cluster_manager_timeout] with value [bogus] as a time value"
        );

        let invalid_expand = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_expand.status, 400);
        assert_eq!(
            invalid_expand.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );

        let named_put = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_alias/logs-root-write?timeout=30s&cluster_manager_timeout=30s&master_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "index": "logs-root-alias-000001",
                "is_write_index": true
            })),
        );
        assert_eq!(named_put.status, 200);

        let named_put_unknown = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_alias/logs-root-bad?local=true").with_json_body(
                serde_json::json!({
                    "index": "logs-root-alias-000001"
                }),
            ),
        );
        assert_eq!(named_put_unknown.status, 400);
        assert_eq!(
            named_put_unknown.body["error"]["reason"],
            "request [/_alias/logs-root-bad] contains unrecognized parameter: [local]"
        );

        let named_put_bad_timeout = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_alias/logs-root-bad?timeout=bogus")
                .with_json_body(serde_json::json!({
                    "index": "logs-root-alias-000001"
                })),
        );
        assert_eq!(named_put_bad_timeout.status, 400);
        assert_eq!(
            named_put_bad_timeout.body["error"]["reason"],
            "failed to parse setting [timeout] with value [bogus] as a time value"
        );

        let named_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_aliases/logs-root-search").with_json_body(
                serde_json::json!({
                    "index": "logs-root-alias-000001",
                    "searchRouting": "tenant-a",
                    "is_hidden": true
                }),
            ),
        );
        assert_eq!(named_post.status, 200);

        let named_post_unknown_body = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_aliases/logs-root-body-bad").with_json_body(
                serde_json::json!({
                    "index": "logs-root-alias-000001",
                    "indices": ["logs-root-alias-000001"]
                }),
            ),
        );
        assert_eq!(named_post_unknown_body.status, 400);
        assert_eq!(
            named_post_unknown_body.body["error"]["reason"],
            "unknown field [indices]"
        );

        let named_get =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/logs-root-write"));
        assert_eq!(named_get.status, 200);
        assert_eq!(
            named_get.body["logs-root-alias-000001"]["aliases"]["logs-root-write"]
                ["is_write_index"],
            Value::Bool(true)
        );

        let missing_named_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias/logs-root-missing",
        ));
        assert_eq!(missing_named_get.status, 404);
        assert_eq!(
            missing_named_get.body["error"],
            "alias [logs-root-missing] missing"
        );
        assert_eq!(missing_named_get.body["status"], 404);

        let partially_missing_named_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias/logs-root-write,logs-root-missing",
        ));
        assert_eq!(partially_missing_named_get.status, 404);
        assert_eq!(
            partially_missing_named_get.body["error"],
            "alias [logs-root-missing] missing"
        );
        assert!(
            partially_missing_named_get.body["logs-root-alias-000001"]["aliases"]
                .get("logs-root-write")
                .is_some()
        );

        let named_head = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_alias/logs-root-write",
        ));
        assert_eq!(named_head.status, 200);

        let named_head_with_options = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_alias/logs-root-write?local=true&ignore_unavailable=false&allow_no_indices=true&ignore_throttled=false&expand_wildcards=open&cluster_manager_timeout=30s&master_timeout=30s",
        ));
        assert_eq!(named_head_with_options.status, 200);

        let named_head_unknown = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_alias/logs-root-write?foo=bar",
        ));
        assert_eq!(named_head_unknown.status, 400);
        assert_eq!(
            named_head_unknown.body["error"]["reason"],
            "request [/_alias/logs-root-write] contains unrecognized parameter: [foo]"
        );

        let named_head_invalid_bool = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_alias/logs-root-write?local=maybe",
        ));
        assert_eq!(named_head_invalid_bool.status, 400);
        assert_eq!(
            named_head_invalid_bool.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let wildcard_named_put = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_alias/logs-root-wildcard").with_json_body(
                serde_json::json!({
                    "index": "logs-root-alias-*"
                }),
            ),
        );
        assert_eq!(wildcard_named_put.status, 200);

        let wildcard_named_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_alias/logs-root-wildcard",
        ));
        assert_eq!(wildcard_named_get.status, 200);
        assert!(wildcard_named_get
            .body
            .get("logs-root-alias-000001")
            .is_some());
        assert!(wildcard_named_get
            .body
            .get("logs-root-alias-000002")
            .is_some());

        let duplicate_named_put = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_alias/logs-root-write").with_json_body(
                serde_json::json!({
                    "index": "logs-root-alias-000001",
                    "is_write_index": true
                }),
            ),
        );
        assert_eq!(duplicate_named_put.status, 200);

        let duplicate_readback =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/logs-root-write"));
        assert_eq!(duplicate_readback.status, 200);
        assert_eq!(
            duplicate_readback
                .body
                .as_object()
                .map(|indices| indices.len()),
            Some(1)
        );
        assert_eq!(
            duplicate_readback.body["logs-root-alias-000001"]["aliases"]["logs-root-write"]
                ["is_write_index"],
            Value::Bool(true)
        );

        let bulk_alias_timeout = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_aliases?timeout=30s&cluster_manager_timeout=30s&master_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "actions": [
                    {
                        "add": {
                            "index": "logs-root-alias-000001",
                            "alias": "logs-root-bulk-timeout"
                        }
                    }
                ]
            })),
        );
        assert_eq!(bulk_alias_timeout.status, 200);

        let bulk_alias_unknown = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_aliases?local=true").with_json_body(
                serde_json::json!({
                    "actions": []
                }),
            ),
        );
        assert_eq!(bulk_alias_unknown.status, 400);
        assert_eq!(
            bulk_alias_unknown.body["error"]["reason"],
            "request [/_aliases] contains unrecognized parameter: [local]"
        );

        let aliases_get = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_aliases"));
        assert_eq!(aliases_get.status, 200);
        assert!(aliases_get.body["logs-root-alias-000001"]["aliases"]
            .get("logs-root-search")
            .is_some());
        assert_eq!(
            aliases_get.body["logs-root-alias-000001"]["aliases"]["logs-root-search"]
                ["search_routing"],
            "tenant-a"
        );
        assert_eq!(
            aliases_get.body["logs-root-alias-000001"]["aliases"]["logs-root-search"]["is_hidden"],
            Value::Bool(true)
        );
    }

    #[test]
