    #[test]
    fn refresh_routes_serve_global_and_targeted_shard_counts_for_get_and_post() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-refresh-000001")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-refresh-000002")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/metrics-refresh-000001")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );

        for (method, path, expected_total, expected_successful) in [
            (RestMethod::Get, "/_refresh", 6, 3),
            (RestMethod::Post, "/_refresh", 6, 3),
            (RestMethod::Get, "/logs-refresh-000001/_refresh", 2, 1),
            (RestMethod::Post, "/logs-refresh-000001/_refresh", 2, 1),
            (RestMethod::Get, "/logs-refresh-*/_refresh", 4, 2),
            (RestMethod::Post, "/logs-refresh-*/_refresh", 4, 2),
        ] {
            let response = node.handle_rest_request(RestRequest::new(method, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(
                response.body["_shards"]["total"], expected_total,
                "path {path}"
            );
            assert_eq!(
                response.body["_shards"]["successful"], expected_successful,
                "path {path}"
            );
            assert_eq!(response.body["_shards"]["failed"], 0, "path {path}");
        }
    }

    #[test]
    fn source_routes_serve_targeted_source_body_and_head_existence() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-source-000001")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-source-000001/_doc/doc-1").with_json_body(
                    serde_json::json!({
                        "message": "source-doc",
                        "tenant": "tenant-a",
                        "secret": "hidden"
                    })
                ),
            )
            .status,
            201
        );

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/doc-1",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(get_response.body["message"], "source-doc");
        assert_eq!(get_response.body["tenant"], "tenant-a");

        let filtered_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/doc-1?_source_includes=message,tenant&_source_excludes=tenant",
        ));
        assert_eq!(filtered_response.status, 400);
        assert_eq!(
            filtered_response.body["error"]["reason"],
            "The same entry [tenant] cannot be both included and excluded in _source."
        );

        let singular_filtered_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/doc-1?_source_include=message,tenant&_source_exclude=tenant",
        ));
        assert_eq!(singular_filtered_response.status, 400);
        assert_eq!(
            singular_filtered_response.body["error"]["reason"],
            "The same entry [tenant] cannot be both included and excluded in _source."
        );

        let get_doc_overlap = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_doc/doc-1?_source_includes=message,tenant&_source_excludes=tenant",
        ));
        assert_eq!(get_doc_overlap.status, 400);
        assert_eq!(
            get_doc_overlap.body["error"]["reason"],
            "The same entry [tenant] cannot be both included and excluded in _source."
        );

        let filtered_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/doc-1?_source_includes=message,tenant&_source_excludes=secret",
        ));
        assert_eq!(filtered_response.status, 200);
        assert_eq!(
            filtered_response.body,
            serde_json::json!({"message":"source-doc","tenant":"tenant-a"})
        );

        let disabled_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/doc-1?_source=false",
        ));
        assert_eq!(disabled_response.status, 400);
        assert_eq!(
            disabled_response.body["error"]["type"],
            "action_request_validation_exception"
        );
        assert!(disabled_response.body["error"]["reason"]
            .as_str()
            .unwrap()
            .contains("fetching source can not be disabled"));

        let head_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/logs-source-000001/_source/doc-1",
        ));
        assert_eq!(head_response.status, 200);
        assert_eq!(head_response.body, Value::Null);

        let missing_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-source-000001/_source/missing-doc",
        ));
        assert_eq!(missing_response.status, 404);
    }

