    #[test]
    fn nodes_info_variant_routes_serve_node_info_shape() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steel-cluster".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "steel-node".to_string(),
            nodes: vec![
                DevelopmentClusterNode {
                    node_id: "steel-node".to_string(),
                    node_name: "steel-node".to_string(),
                    http_address: Some("127.0.0.1:9200".to_string()),
                    transport_address: "127.0.0.1:9300".to_string(),
                    roles: vec!["cluster_manager".to_string(), "data".to_string()],
                    local: true,
                },
                DevelopmentClusterNode {
                    node_id: "other-node".to_string(),
                    node_name: "other-node".to_string(),
                    http_address: Some("127.0.0.1:9201".to_string()),
                    transport_address: "127.0.0.1:9301".to_string(),
                    roles: vec!["data".to_string()],
                    local: false,
                },
            ],
            coordination: None,
        });

        for path in [
            "/_nodes",
            "/_nodes/_all",
            "/_nodes/_all/http",
            "/_nodes/_all/info/http",
            "/_nodes/http",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(response.body["nodes"].is_object(), "path {path}");
        }

        let http_only = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/http"));
        let first_node = &http_only.body["nodes"]["steel-node"];
        assert!(first_node["http"].is_object());
        assert!(first_node.get("settings").is_none());

        let unknown_metric_ignored =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/_all/bogus"));
        assert_eq!(unknown_metric_ignored.status, 200);
        let first_node = &unknown_metric_ignored.body["nodes"]["steel-node"];
        assert!(first_node["name"].is_string());
        assert!(first_node.get("http").is_none());
        assert!(first_node.get("settings").is_none());

        let selected_node =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/other-node/http"));
        assert_eq!(selected_node.status, 200);
        assert!(selected_node.body["nodes"]["other-node"].is_object());
        assert!(selected_node.body["nodes"]["steel-node"].is_null());
    }

    #[test]
    fn search_shards_routes_serve_global_and_targeted_shapes_for_get_and_post() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-search-shards-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-search-shards-000001")
                .with_json_body(serde_json::json!({})),
        );

        for (method, path, expected_groups) in [
            (RestMethod::Get, "/_search_shards", 2usize),
            (RestMethod::Post, "/_search_shards", 2usize),
            (
                RestMethod::Get,
                "/logs-search-shards-*/_search_shards",
                1usize,
            ),
            (
                RestMethod::Post,
                "/logs-search-shards-*/_search_shards",
                1usize,
            ),
        ] {
            let request = if method == RestMethod::Post {
                RestRequest::new(method, path)
                    .with_json_body(serde_json::json!({"query": {"match_all": {}}}))
            } else {
                RestRequest::new(method, path)
            };
            let response = node.handle_rest_request(request);
            assert_eq!(response.status, 200, "path {path}");
            assert!(response.body["nodes"].is_object(), "path {path}");
            assert!(response.body["indices"].is_object(), "path {path}");
            assert_eq!(
                response.body["shards"]
                    .as_array()
                    .map(Vec::len)
                    .unwrap_or_default(),
                expected_groups,
                "path {path}"
            );
        }
    }

    #[test]
    fn cluster_allocation_explain_routes_match_bounded_get_and_post_shapes() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create_index = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-stateful-probe").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index.number_of_shards": 1,
                        "index.number_of_replicas": 1
                    }
                }),
            ),
        );
        assert_eq!(create_index.status, 200);

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/allocation/explain",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(
            get_response.body["current_state"],
            Value::String("unassigned".to_string())
        );

        let post_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_cluster/allocation/explain").with_json_body(
                serde_json::json!({
                    "index": "logs-stateful-probe",
                    "shard": 0,
                    "primary": true
                }),
            ),
        );
        assert_eq!(post_response.status, 200);
        assert_eq!(
            post_response.body["index"],
            Value::String("logs-stateful-probe".to_string())
        );
        assert_eq!(post_response.body["primary"], Value::Bool(true));
        assert_eq!(
            post_response.body["current_state"],
            Value::String("started".to_string())
        );
        assert_eq!(
            post_response.body["current_node"]["weight_ranking"],
            Value::Number(1.into())
        );
        assert!(post_response.body["current_node"]["roles"].is_array());
        assert_eq!(
            post_response.body["can_rebalance_cluster"],
            Value::String("no".to_string())
        );
        assert_eq!(
            post_response.body["can_move_to_other_node"],
            Value::String("no".to_string())
        );
        assert!(post_response.body["move_explanation"].as_str().is_some());
        assert!(post_response.body["cluster_info"]["nodes"].is_object());
        assert!(post_response.body["cluster_info"]["shard_sizes"].is_object());
        assert_eq!(
            get_response.body["node_allocation_decisions"][0]["deciders"][0]["decision"],
            Value::String("NO".to_string())
        );
        assert_eq!(get_response.body["configured_delay"], "0ms");
        assert_eq!(get_response.body["remaining_delay_in_millis"], 0);
        assert_eq!(
            get_response.body["unassigned_info"]["failed_allocation_attempts"],
            0
        );
        assert!(
            get_response.body["node_allocation_decisions"][0]["deciders"][0]["explanation"]
                .as_str()
                .unwrap_or_default()
                .contains("bounded development allocation explain")
        );
    }

    #[test]
    fn cluster_state_route_surfaces_index_metadata_and_routing_entries() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });

        let create_index = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-cluster-state-000001").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index.number_of_shards": 1,
                        "index.number_of_replicas": 1
                    },
                    "mappings": {
                        "properties": {
                            "tenant": { "type": "keyword" }
                        }
                    }
                }),
            ),
        );
        assert_eq!(create_index.status, 200);

        {
            let mut manifest = node
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            manifest["indices"]["logs-cluster-state-000001"]["aliases"] = serde_json::json!({
                "logs-cluster-state-alias": {}
            });
        }

        let state = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/state"));
        assert_eq!(state.status, 200);
        assert_eq!(state.body["cluster_name"], "steelsearch-dev");
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["settings"]["index"]
                ["number_of_replicas"],
            "1"
        );
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["mappings"]
                ["properties"]["tenant"]["type"],
            "keyword"
        );
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["aliases"],
            serde_json::json!(["logs-cluster-state-alias"])
        );
        assert_eq!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["state"],
            "STARTED"
        );
        assert_eq!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["allocation_id"]["id"],
            "logs-cluster-state-000001-p-0"
        );
        assert!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["recovery_source"]
                .is_null()
        );
        assert_eq!(
            state.body["routing_nodes"]["nodes"]["node-a"][0]["index"],
            "logs-cluster-state-000001"
        );
        assert_eq!(
            state.body["routing_nodes"]["nodes"]["node-a"][0]["allocation_id"],
            "logs-cluster-state-000001-p-0"
        );
    }

    #[test]
    fn cluster_state_route_validates_wait_and_timeout_params_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for (path, expected_reason) in [
            (
                "/_cluster/state?local=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_cluster/state?cluster_manager_timeout=soon",
                "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value",
            ),
            (
                "/_cluster/state?master_timeout=soon",
                "failed to parse setting [master_timeout] with value [soon] as a time value",
            ),
            (
                "/_cluster/state?wait_for_timeout=soon",
                "failed to parse setting [wait_for_timeout] with value [soon] as a time value",
            ),
            (
                "/_cluster/state?wait_for_metadata_version=abc",
                "Failed to parse value [abc] for [wait_for_metadata_version] as a long",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "{path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
            assert_eq!(response.body["error"]["reason"], expected_reason, "{path}");
        }

        let waited = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/state?wait_for_metadata_version=1&wait_for_timeout=1s",
        ));
        assert_eq!(waited.status, 200);
        assert_eq!(waited.body["wait_for_timed_out"], Value::Bool(false));
    }

    #[test]
    fn cluster_pending_tasks_route_surfaces_task_metadata_visibility() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 7,
                    task: ClusterManagerTask {
                        source: "reroute shards".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 8,
                    task: ClusterManagerTask {
                        source: "publish state".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let response =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"));
        assert_eq!(response.status, 200);
        let tasks = response.body["tasks"]
            .as_array()
            .expect("pending tasks array");
        assert_eq!(tasks.len(), 2);
        assert_eq!(tasks[0]["node"], "node-a");
        assert_eq!(tasks[0]["node_name"], "steel-node-a");
        assert_eq!(tasks[0]["action"], "cluster:admin/reroute");
        assert!(tasks[0]["description"].as_str().is_some());
        assert_eq!(tasks[0]["priority"], "URGENT");
        assert_eq!(tasks[0]["time_in_queue_millis"], 0);
        assert_eq!(tasks[0]["executing"], false);
        assert_eq!(tasks[1]["executing"], true);
    }

